o s u p rim ir la p e n sió n , c u a lq u ie ra q u e fu e ra la p e n u ria de las arcas fisca le s. Lo ú n ic o q u e se
p o d ría h ace r se ria im p o n e rle u n a c o n trib u c ió n . T o d o lo d e m á s se ría in c o n s titu c io n a l”404.
“A p esar de q u e tan to la revo cació n co m o la a n u la c ió n p ro d u ce n el efecto de e lim in a r un acto
