En c u a lq u ie r m o m e n to , los a d m in is tra d o s p u e d e n fo rm u la r q u e ja co n tra los defectos de tra
m ita c ió n y, en e sp e cia l, los q u e su p o n g a n p a ra liz a c ió n , in fra cció n de los p lazo s e sta b le c id o s
