d e n tro de los tres d ía s sig u ie n te s, p revio tra s la d o al q u e ja d o , a fin de q u e p u e d a p re se n tar el
in fo rm e q u e e stim e c o n v e n ie n te al d ía sig u ie n te d e s o lic ita d o 408.
