tivos, in ic iá n d o s e el co rre sp o n d ie n te p ro c e d im ie n to re cu rsivo 412. "Los recu rsos a d m in is tra tiv o s
y los re cla m o s son m o d o s de co ntro l de la a c tiv id a d a d m in is tra tiv a ; so lo que a in ic ia tiv a de
los p a r t ic u la re s y no de oficio. Es un tip o de co ntro l q u e p ro m u e v e n su je to s a je n o s al a p a rato
e statal; in c lu so los e m p le a d o s p ú b lic o s en d e fe n sa de su s d e re ch o s e intereses le g ítim o s q u e
n ace n de su re la ció n ju r íd ic a con el Estado. Lo cu al no im p id e que, si la ley lo a u to riza , ta m b ié n
los p e tic io n a n te s q u e fu e ran entes d e sc e n tra liz a d o s e statale s p u d ie ra n u tiliz a r recu rsos d e n
tro d e la A d m in is tra c ió n a la q u e pertenecen"413.
