UBILEX
2 .1. Recursos administrativos
“Por m e d io del recurso a d m in is tra tiv o , se p ro m u e v e el co ntro l d e la le g a lid a d (le g it im id a d y
o p o rtu n id a d ) de un acto e m a n a d o d e la a u to rid a d a d m in is tra tiv a , a fin d e q u e se lo revoq u e
o m o d ifiq u e con el o b je to de re sta b le ce r el d e re ch o s u b je tiv o o interés le g ítim o le sio n a d o por
d ic h o acto’’417. Los recu rsos a d m in is tra tiv o s so n 418:
a) Recurso de reconsideración. El recu rso d e re co n sid e ra c ió n se in te rp o n d rá ante el m is m o
ó rg a n o q u e d ictó el p rim e r acto q u e es m a te ria d e la im p u g n a c ió n y d e b e rá su ste n ta rse
en n u e va p ru e b a. En los casos d e acto s a d m in is tra tiv o s e m itid o s por ó rg a n o s q u e co n sti
tu y e n ú n ic a in s ta n c ia no se re q u ie re n u e v a p ru e b a . Este recu rso es o p c io n a l y su no in ter
p o sició n no im p id e el e je rcicio d el recu rso de a p e la c ió n 419.
b) Recurso de apelación. El recu rso d e a p e la c ió n se in te rp o n d rá c u a n d o la im p u g n a c ió n se
su ste n te en d ife re n te in te rp re ta c ió n de las p ru e b a s p ro d u c id a s o c u a n d o se trate d e cu e s
tio n e s de puro d erech o , d e b ie n d o d irig irs e a la m is m a a u to rid a d q u e e x p id ió el acto q u e
se im p u g n a p ara q u e eleve lo a c tu a d o al su p e rio r je rá rq u ic o 420.
S o lo en caso q u e por le y o d ecreto le g isla tiv o se e stab le zca e x p re sam e n te , cab e la in te rp o si
ció n del recurso a d m in is tra tiv o d e re v isió n 421.
El té rm in o p ara la in te rp o sic ió n de los recu rsos es de q u in c e (15) d ía s p e ren to rio s, y d eb en
resolverse en el p lazo d e tre in ta (30) d ías, con e x cep ció n del recu rso de re co n sid e ra c ió n q u e se
resu elve en el p lazo de q u in c e (15) d ías. E x ce p cio n a lm e n te , en los p ro c e d im ie n to s a d m in is t r a
tivos de in s ta n c ia ú n ic a de co m p e te n c ia de los co n se jo s d ire ctiv o s d e los o rg a n is m o s re g u la
d ores, el recurso de re co n sid e ra c ió n se resu elve en el p lazo de tre in ta (30) d ía s 422.
2.2. Requisitos del recurso
El escrito del recurso d e b e rá s e ñ a la r el acto del q u e se recurre y c u m p lir á los d e m á s re q u isito s
p revistos en el a rtíc u lo 1 2 4 423.
2.3. Resolución
La re so lu ció n d el recu rso e stim a rá en to d o o en p arte o d e se stim a rá las p re te n sio n e s fo rm u la
d a s en el m is m o o d e c la ra rá su in a d m is ió n 424.
