3. Procedim iento de evaluación previa con silencio positivo
Los procedimientos de evaluación previa están sujetos a silencio positivo, cuando se trate de
algunos de los siguientes supuestos437:
a) Todos los procedimientos a instancia de parte no sujetos al silencio administrativo nega
tivo taxativo.
b) Recursos destinados a cuestionar la desestimación de una solicitud cuando el particular
haya optado por la aplicación del silencio administrativo negativo.
Como constancia de la aplicación del silencio positivo de la solicitud del administrado, basta
la copia del escrito o del formato presentado conteniendo el sello oficial de recepción, sin ob
servaciones e indicando el número de registro de la solicitud, fecha, hora y firm a del agente
receptor438.
En los procedimientos administrativos sujetos asilencio positivo, la petición del administrado
se considera aprobada si, vencido el plazo establecido o máximo para pronunciarse, la enti
dad no hubiera notificado el pronunciamiento correspondiente, no siendo necesario expedir
se pronunciamiento o documento alguno para que el administrado pueda hacer efectivo su
derecho, bajo responsabilidad del funcionario o servidor público que lo requiera439.
No obstante, vencido el plazo para que opere el silencio positivo en los procedimientos de
evaluación previa, sin que la entidad hubiera emitido pronunciamiento sobre lo solicitado,
los administrados, si lo consideran pertinente y de manera complementaria, pueden presen
tar una Declaración Jurada ante la propia entidad que configuró dicha aprobación ficta, con
la finalidad de hacer valer el derecho conferido ante la misma o terceras entidades de la ad
ministración, constituyendo el cargo de recepción de dicho documento, prueba suficiente de
la resolución aprobatoria ficta de la solicitud o trámite iniciado. En el caso que la autoridad
administrativa se niegue a recibir la Declaración Jurada, el administrado puede rem itirla por
conducto notarial, surtiendo los mismos efectos440.
4. Procedimientos de evaluación previa con silencio negativo
Excepcionalmente, el silencio negativo es aplicable en aquellos casos en los que la petición
del administrado puede afectar significativamente el interés público e incida en los siguientes
bienes jurídicos: la salud, el medio ambiente, los recursos naturales, la seguridad ciudada
na, el sistema financiero y de seguros, el mercado de valores, la defensa comercial, la defensa
nacional y el patrimonio cultural de la nación, así como en aquellos procedimientos de pro-
