casinos de juego y máquinas tragamonedas441. “La identificación de la afectación significativa
al interés público en relación a la salud y medio ambiente, para efectos de la aplicación del
silencio negativo, requiere considerar la protección y realización de la comunidad en conjunto
sobre tales derechos, teniendo en consideración la circunstancia objetiva y subjetiva, y aquel
o aquellos actos que afecten significativamente el interés público incidiendo en los derechos
anotados, lo que corresponde identificar según las circunstancias de cada caso concreto al
momento de la aplicación”442.
Asimismo, es de aplicación para aquellos procedimientos por los cuales se transfiera faculta
des de la administración pública443.
En materia tributaria y aduanera, el silencio administrativo se rige por sus leyes y normas es
peciales. Tratándose de procedimientos administrativos que tengan incidencia en la determi
nación de la obligación tributaria o aduanera, se aplica el Código Tributario444.
5. Plazo máximo del procedimiento administrativo de evaluación previa
El plazo que transcurra desde el inicio de un procedimiento administrativo de evaluación pre
via hasta que sea dictada la resolución respectiva, no puede exceder de treinta (30) días hábi
les, salvo que por ley o decreto legislativo se establezcan procedimientos cuyo cumplim iento
requiera una duración mayor445.
IX. PROCEDIMIENTO TRILATERAL
El procedimiento administrativo especial trilateral también es denominado procedimiento
triangular o cuasijurisdiccional, siendo su rasgo distintivo esencial la existencia de dos (2) o
más administrados que se someten a la decisión de una autoridad administrativa, esta resulta
ser una aproximación amplia a lo que es el procedimiento trilateral, siendo necesario para su
comprensión recurrir a una clasificación doctrinal de los procedimientos administrativos que
se relacionan con el procedimiento trilateral.
1. ¿Qué es el procedimiento trilateral?
El procedimiento trilateral importa un proceso especial en el cual la Administración dirime un
conflicto entre dos administrados446, es decir, el procedimiento trilateral es el procedimiento
administrativo contencioso seguido entre dos o más administrados ante las entidades de la
