Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1251 of 1506 --

Temas de Adm inistrativo
administración447 y para las entidades públicas consistente en las personas jurídicas bajo el
régimen privado que prestan servicios públicos o ejercen función administrativa, en virtud de
concesión, delegación o autorización del Estado448.
Ergo, cuando se indica contencioso esto es sinónimo de conflicto, por lo que, en el ordena
miento jurídico peruano, no habrá procedimiento trilateral cuando no exista conflicto de in
tereses entre administrados, de tal manera que los procedimientos concurrenciales en nues
tro ordenamiento jurídico no son procedimientos trilaterales, verbigratia, de procedimientos
concurrenciales serían los procedimientos para selección de personal y los procedimientos
administrativos de selección para contratación pública; asimismo, prueba que nuestro orde
namiento jurídico diferencia entre procedimientos trilaterales y concurrenciales es lo previsto
en el numeral 151.4 del a rtículoisi del TUO de la Ley 27444 que indica:
"La preclusión por el vencimiento de plazos administrativos opera en procedimientos trilaterales, con
currenciales, y en aquellos que por existir dos o más administrados con intereses divergentes, deba
asegurárselas tratamiento paritario." (El resaltado es nuestro)
Por otro lado, se establece que el procedimiento trilateral implica un conflicto entre dos o más
administrados ante las entidades de la administración; un procedimiento administrativo tri
lateral entre un consumidory un proveedor, implica un conflicto entre dos administrados; un
procedimiento trilateral como sería un procedimiento concursal entre varios acreedores en
contra de una empresa ante la Comisión de Procedimientos Concúrsales del INDECOPI, im pli
cará un conflicto entre más de dos administrados; por lo que podemos decirque los primeros
son procedimientos trilaterales simplesy los segundos procedimientos trilaterales complejos.
Ahora bien, tomando en cuenta la existencia de sólo dos (2) administrados en conflicto pode
mos establecer dos supuestos de procedimientos trilaterales:
a) El procedimiento trilateral es el procedimiento administrativo contencioso seguido entre
dos o más administrados ante las entidades de la administración.
b) El procedimiento trilateral es el procedimiento administrativo contencioso para las per
sonas jurídicas bajo el régimen privado que prestan servicios públicos o ejercen función
administrativa, en virtud de concesión, delegación o autorización del Estado.
2. Etapas del procedimiento trilateral
Ab initio, el procedimiento trilateral se rige por lo dispuesto en el Capítuloxdel Título IV del
TUO de la Ley 27444 y en lo demás por lo previsto en el TUO de la Ley 2 7 4 4 4 ; respecto de los
procedimientos administrativos trilaterales regidos por leyes especiales, el C apítuloidel Títu
lo IV de! TUO de la Ley 27444 tendrá únicamente carácter supletorio449.
