2.1. Siliciod/ei procedimiento. El procedimiento trilateral se inicia mediante la presentación de
una reclamación o de oficio450, la parte que inicia el procedimiento con la presentación de una
reclamación será designada como “reclamante” y cualquiera de los emplazados será designa
do como “reclamado”451. Por su parte, un procedimiento trilateral de oficio, verbigratia, sería el
procedimiento sumario donde el consumidor - administrado denuncia a un proveedor ante
INDECOPI quien inicia de oficio el procedimiento, siendo parte del mismo el administrado
denunciante, generándose latrilateralidad.
2.2. Reclamación. La reclamación deberá contener los requisitos de los escritos, en efecto todo
escritcxque se presente ante cualquier entidad debe contener lo siguiente452:
a. Nombres y apellidos completos, domicilio y número de Documento Nacional de Iden
tidad o carné de extranjería del administrado, y en su caso, la calidad de representante y
de la persona a quien represente. La reclamación también debe contener el nombre y la
dirección de cada reclamado, los motivos de la reclamación y la petición de sanciones u
otro tipo de acción afirmativa453.
b. La expresión concreta de lo pedido, los fundamentos de hecho que lo apoye y, cuando le
sea posible, los de derecho. La autoridad podrá solicitar aclaración de la reclamación de
admitirla, cuando existan dudas en la exposición de los hechos o fundamentos de dere
cho respectivos454.
c. Lugar, fecha, firm a o huella digital, en caso de no saber firm ar o estar impedido.
d. La indicación del órgano, la entidad o la autoridad a la cual es dirigida, entendiéndose por
tal, en lo posible, a la autoridad de grado más cercano al usuario, según la jerarquía, con
competencia para conocerlo y resolverlo.
e. La dirección del lugar donde se desea recibir las notificaciones del procedimiento, cuan
do sea diferente al domicilio real, este señalamiento de dom icilio surte sus efectos desde
su indicación y es presumido subsistente, mientras no sea comunicado expresamente su
cambio.
f. La relación de los documentos y anexos que acompaña, indicados en el TUPA. La recla
mación deberá ofrecer las pruebas y acompañará como anexos las pruebas de las que
disponga455
g. La identificación del expediente de la materia, tratándose de procedimientos ya inicia
dos.
