acuse de recibo a la entidad competente457.
2.3. Contestación de la reclamación. Una vez admitida a trámite la reclamación se pondrá en
conocimiento del redamado a fin de que éste presente su descargo458. El reclamado deberá
presentar la contestación de la reclamación dentro de los quince (15) días posteriores a la noti
ficación de ésta; vencido este plazo, la Administración declarará en rebeldía al reclamado que
no la hubiera presentado. La contestación deberá contener los requisitos de los escritos indi
cados utsupra, así como la absolución de todos los asuntos controvertidos de hechoy de dere
cho; las alegaciones y los hechos relevantes de la reclamación, salvo que hayan sido específi
camente negadas en la contestación, se tendrán por aceptadas o merituadas como ciertas459.
Las cuestiones se proponen conjunta y únicamente al contestar la reclamación o la réplica y
son resueltas con la resolución final460. Las cuestiones que planteen los administrados durante
la tramitación del procedimiento sobre extremos distintos al asunto principal, no suspenden
su avance, debiendo ser resueltas en la resolución final de la instancia, salvo disposición ex
presa en contrario de la ley461.
En el caso de que el reclamado no cumpla con presentar la contestación dentro del plazo es
tablecido, la administración podrá permitir, si lo considera apropiado y razonable, la entrega
de la contestación luego del vencimiento del plazo462. Esta es una excepción, a la regla: la pre
clusión por el vencimiento de plazos administrativos opera en procedimientos trilaterales,
por existir dos o más administrados con intereses divergentes, deba asegurárselas tratam ien
to paritario463.
Adicionalmente a la contestación, el reclamado podrá presentar una réplica alegando viola
ciones a la legislación respectiva, dentro de la competencia del organismo correspondiente de
la entidad. La presentación de réplicas y respuestas a aquellas réplicas se rige por las reglas
para la presentación y contestación de reclamaciones, excluyendo lo referente a los derechos
administrativos de trám ite464.
