3. Conciliación y transacción extrajudicial
Durante el desarrollo del procedimiento trilateral la administración debe favorecer y facilitar
la solución conciliada de la controversia477. En los casos en los que la Ley lo permita y antes de
que se notifique la resolución final, la autoridad podrá aprobar acuerdos, pactos, convenios
o contratos con los administrados que importen una transacción extrajudicial o conciliación,
con el alcance, requisitos, efectos y régimen jurídico específico que en cada caso prevea la dis
posición que lo regule, pudiendo tales actos poner fm al procedimiento administrativo y dejar
sin efecto las resoluciones que se hubieren dictado en el procedimiento. El acuerdo podrá ser
recogido en una resolución administrativa478. Los citados instrumentos deberán constar por
escrito y establecer como contenido mínimo la identificación de las partes intervinientes y el
plazo de vigencia479. Al aprobar los acuerdos, la autoridad podrá continuar el procedimiento
de oficio si del análisis de los hechos considera que podría estarse afectando intereses de ter
ceros o la acción suscitada por la iniciación del procedimiento entrañase interés general480.
Por otro lado, en el procedimiento trilateral procede el desistimiento481, ergo, procede el de
sistimiento del procedimiento, el desistimiento de la pretensión y el desistimiento de actos y
recursos administrativos.
