X. PROCEDIMIENTO SANCIONADOR
Las disposiciones del procedimiento administrativo sancionador disciplinan la facultad quese
atribuye a cualquiera de las entidades para establecer infracciones administrativas y las con
secuentes sanciones a los administrados. Estas disposiciones se aplican con carácter supleto
rio a todos los procedimientos establecidos en leyes especiales. Los procedimientos especia
les no pueden imponer condiciones menos favorables a los administrados, que las previstas
en el procedimiento administrativo sancionador general.
La potestad sancionadora disciplinaria sobre el personal de las entidades se rige por la norma
tiva sobre la materia482.
482 Cfr. Artículo 247 Decreto Supremo 004-2019-JUS, Perú.
256 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1257 of 1506 --

Temas de Adm inistrativo
I . Principios «fe ia potestad sancionadora adm inistrativa
Son principios de la potestad sancionadora los siguientes483:
1. Legalidad. Sólo pornorm acon rango de ley cabe atribuirá las entidades la potestad san-
cionadoray la consiguiente previsión de las consecuencias administrativas que a título de
sanción son posibles de aplicar a un administrado, las que en ningún caso habilitarán a
disponer la privación de libertad.
2. Debido procedimiento. No se pueden imponer sanciones sin que se haya tram itado el
procedimiento respectivo, respetando las garantías del debido procedimiento. Los pro
cedimientos que regulen el ejercicio de la potestad sancionadora deben establecer la
debida separación entre la fase instructora y la sancionadora, encomendándolas a auto
ridades distintas.
3. Razonabilidad. Las autoridades deben prever que la comisión de la conducta sanciona-
ble no resulte más ventajosa para el infractorque cum plir las normas infringidas o asumir
lasanción.
4. Tipicidad. Solo constituyen conductas sancionables administrativamente las infraccio
nes previstas expresamente en normas con rango de ley mediante su tipificación como
tales, sin adm itir interpretación extensiva o analogía.
5. Irretroactividad. Son aplicables las disposiciones sancionadoras vigentes en el momento
de incurrir el administrado en la conducta a sancionar, salvo que las posteriores le sean
más favorables.
6 . Concurso de Infracciones. Cuando una misma conducta califique como más de una in
fracción se aplicará la sanción prevista para la infracción de mayor gravedad, sin perjuicio
que puedan exigirse las demás responsabilidades que establezcan las leyes.
y. Continuación de infracciones. Para determinar la procedencia de la imposición de san
ciones por infracciones en las que el administrado incurra en forma continua, se requiere
que hayan transcurrido por lo menos treinta (30) días hábiles desde la fecha de la imposi
ción de la últim a sanción y que se acredite habersolicitado al administrado que demues
tre haber cesado la infracción dentro de dicho plazo.
8. Causalidad. La responsabilidad debe recaer en quien realiza la conducta omisiva o activa
constitutiva de infracción sancionable.
9. Presunción de licitud. Las entidades deben presumir que los administrados han actuado
apegados a sus deberes mientras no cuenten con evidencia en contrario.
10. Culpabilidad. La responsabilidad administrativa es subjetiva, salvo los casos en que por
ley o decreto legislativo se disponga la responsabilidad administrativa objetiva.
II. N on b is m ídem. No se podrán imponer sucesiva o simultáneamente una penay una san
ción administrativa por el mismo hecho en los casos en que se aprecie la identidad del
sujeto, hecho y fundamento.
483 Cfr. Artículo 248 Decreto Supremo 004-2019-]US, Perú.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1258 of 1506 --

UBILEX
2. Estabilidad de Sa eempetencsa para la potestad sancionadora
El ejercicio de la potestad sancionadora corresponde a las autoridades administrativas a quie
nes le hayan sido expresamente atribuidas por disposición legal o reglamentaria, sin que pue
da asumirla o delegarse en órgano distinto484.
3. Determinación de la responsabilidad
Las sanciones administrativas que se impongan al administrado son compatibles con el dicta
do de medidas correctivas conducentes a ordenar la reposición o la reparación de la situación
alterada por la infracción a su estado anterior, incluyendo la de los bienes afectados, así como
con la indemnización por los daños y perjuicios ocasionados, las que son determinadas en el
proceso judicial correspondiente. Las medidas correctivas deben estar previamente tipifica
das, ser razonables y ajustarse a la intensidad, proporcionalidad y necesidades de los bienes
jurídicos tutelados que se pretenden garantizar en cada supuesto concreto.
Cuando el cumplimiento de las obligaciones previstas en una disposición legal corresponda a
varias personas conjuntamente, responderán en forma solidaria de las infracciones que, en su
caso, se cometan, y de las sanciones que se impongan485.
4. Prescripción
La facultad de la autoridad para determinar la existencia de infracciones administrativas,
prescribe en el plazo que establezcan las leyes especiales, sin perjuicio del cómputo de los
plazos de prescripción respecto de las demás obligaciones que se deriven de los efectos de
la comisión de la infracción. En caso ello no hubiera sido determinado, dicha facultad de la
autoridad prescribirá a los cuatro (4) años. El cómputo del plazo de prescripción de la facultad
para determinar la existencia de infracciones comenzará a partir del día en que la infracción
se hubiera cometido en el caso de las infracciones instantáneas o infracciones instantáneas de
efectos permanentes, desde el día que se realizó la últim a acción constitutiva de la infracción
en el caso de infracciones continuadas, o desde el día en que la acción cesó en el caso de las in
fracciones permanentes. El cómputo del plazo de prescripción sólo se suspende con la inicia
ción del procedimiento sancionador a través de la notificación al administrado de los hechos
constitutivos de infracción que les sean imputados a título de cargo. La autoridad declara de
oficio la prescripcióny da por concluido el procedimiento cuando advierta que se ha cumplido
el plazo para determinar la existencia de infracciones. Asimismo, los administrados pueden
plantear la prescripción por vía de defensay la autoridad debe resolverla sin más trám ite que
la constatación de los plazos486.
484 Cfr. Artículo 249 Decreto Supremo 004-2019-JUS, Perú.
485 Cfr. Artículo 251 Decreto Supremo 004-2019-]US, Perú.
