5. Caracteres del procedimiento sasicienador
Son características del procedimiento administrativo sancionador las siguientes487:
1. Diferenciar en su estructura entre la autoridad que conduce la fase instructora y la que
decide la aplicación de la sanción.
2. Considerar que los hechos probados por resoluciones judiciales firmes vinculan a las en
tidades en sus procedimientos sancionadores.
3 . Notificara los administrados los hechos que se le imputen a título de cargo, la calificación
de las infracciones que tales hechos pueden constituí ry la expresión de las sanciones que,
en su caso, se le pudiera imponer, así como la autoridad competente para imponer la san
ción y la norma que atribuya tal competencia.
4 . Otorgar al administrado un plazo de cinco días para form ular sus alegaciones y utilizar los
medios de defensa admitidos por el ordenamiento jurídico.
La Administración revisa de oficio las resoluciones administrativas fundadas en hechos
contradictorios con los probados en las resoluciones judiciales con calidad de cosa juzga
da, de acuerdo con las normas que regulan los procedimientos de revisión de oficio.
6. Procedim iento sancionador
El procedimiento sancionador observa los siguiente488:
1. El procedimiento sancionador se inicia siempre de oficio, bien por propia iniciativa o
como consecuencia de orden superior, petición motivada de otros órganos o entidades o
pordenuncia.
2. Con anterioridad a la iniciación formal del procedimiento se podrán realizar actuaciones
previas de investigación, averiguación e inspección con el objeto de determinar con carác
ter prelim inarsi concurren circunstancias que justifiquen su iniciación.
3 . Decidida la iniciación del procedimiento sancionador, la autoridad instructora del proce
dim iento formula la respectiva notificación de cargo al posible sancionado, para que pre
sente sus descargos por escrito en un plazo que no podrá ser inferior a cinco días hábiles
contados a partir de la fecha de notificación.
4. Vencido dicho plazo y con el respectivo descargo o sin él, la autoridad que instruye el
procedimiento realizará de oficio todas las actuaciones necesarias para el examen de los
hechos, recabando los datos e informaciones que sean relevantes para determinar, en su
caso, la existencia de responsabilidad susceptible de sanción.
5 . Concluida, de ser el caso, la recolección de pruebas, la autoridad instructora del procedi
miento concluye determinando la existencia de una infracción y, por ende, la imposición
de una sanción; o la no existencia de infracción. La autoridad instructora form ula un in
forme final de instrucción. Recibido el informe final, el órgano competente para decidir la
487 Cfr. Artículo 254 Decreto Supremo 004-2019-]US, Perú.
488 Cfr. Artículo 255 Decreto Supremo 004-2019-]US, Perú.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1260 of 1506 --

UBILEX
aplicación de la sanción puede disponer la realización de actuaciones complementarias,
siempre que las considere indispensables para resolver el procedimiento.
6 . La resolución que aplique la sanción o la decisión de archivar el procedimiento será noti
ficada tanto al administrado como al órgano u entidad que form uló la solicitud o a quién
denunció la infracción, de ser el caso.
7. Eximentes de responsabilidad adm inistrativa
Son eximentes de responsabilidad administrativa489:
a) El caso fortuito o la fuerza mayor debidamente comprobada.
b) Obraren cumplimiento de un deber legal o el ejercicio legítimo del derecho de defensa.
c) La incapacidad mental debidamente comprobada por la autoridad competente, siempre
que esta afecte la aptitud para entender la infracción.
d) La orden obligatoria de autoridad competente, expedida en ejercicio de sus funciones.
e) El error inducido por la Administración o por disposición administrativa confusa o ilegal.
f) La subsanación voluntaria por parte del posible sancionado del acto u omisión imputado
como constitutivo de infracción administrativa, con anterioridad a la notificación de la
imputación de cargos.
8. Atenuantes de la responsabilidad adm inistrativa
Son atenuantes de la responsabilidad administrativa490:
a) Si iniciado un procedimiento administrativo sancionadorel infractor reconoce su respon
sabilidad de forma expresay por escrito.
b) Otros que se establezcan por norma especial.
9. Resolución
En la resolución que ponga fm al procedimiento no se podrán aceptar hechos distintos de los
determinados en el curso del procedimiento, con independencia de su diferente valoración
jurídica. La resolución será ejecutiva cuando ponga fin a la vía administrativa. La administra
ción podrá adoptar las medidas cautelares precisas para garantizar su eficacia, en tanto no
sea ejecutiva. Cuando el infractor sancionado recurra o impugne la resolución adoptada, la
resolución de los recursos que interponga no podrá determinar la imposición de sanciones
más graves para el sancionado491.
489 Cfr. Artículo 257 Decreto Supremo 004-2019-]US, Perú.
490 Cfr. Artículo 257 Decreto Supremo 004-2019-] US, Perú.
