26 ■ BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1261 of 1506 --

Temas de Adm inistrativo
1 0 o C a d u c id a d a c l n i i i i s t r a t i w a
El plazo para resolver los procedimientos sancionadores iniciados de oficio es de nueve (9)
meses contado desde la fecha de notificación de la imputación de cargos. Este plazo puede ser
ampliado de manera excepcional, como máximo por tres (3) meses, debiendo el órgano com
petente em itir una resolución debidamente sustentada, justificando la ampliación del plazo,
previo a su vencimiento. Transcurrido el plazo máximo para resolver, sin que se notifique la
resolución respectiva, se entiende automáticamente caducado administrativamente el proce-
dim ientoy se procederá a su archivo. La caducidad administrativa es declarada de oficio por el
órgano competente. El administrado se encuentra facultado para solicitar la caducidad adm i
nistrativa del procedimiento en caso el órgano competente no la haya declarado de oficio492.
X I. R É G IM E N E C O N Ó M IC O E N L A C O N S T IT U C IÓ N P O L ÍT IC A D E L P E R Ú
1. Principios generales
1.1. Economía Social de Mercado. La iniciativa privada es libre. Se ejerce en una economía so
cial de mercado. Bajo este régimen, el Estado orienta el desarrollo del país, y actúa principal
mente en las áreas de promoción de empleo, salud, educación, seguridad, servicios públicos
e infraestructura493.
1.2. Rol Económico del Estado. El Estado estimula la creación de riquezay garantiza la libertad
de trabajo y la libertad de empresa, comercio e industria. El ejercicio de estas libertades no
debe ser lesivo a la moral, ni a la salud, ni a la seguridad públicas. El Estado brinda oportuni
dades de superación a los sectores que sufren cualquier desigualdad; en tal sentido, promueve
las pequeñas empresas en todas sus modalidades494.
1.3. Pluralismo Económico. El Estado reconoce el pluralismo económico. La economía nacio
nal se sustenta en la coexistencia de diversas formas de propiedady de empresa. Sólo autori
zado por ley expresa, el Estado puede realizar subsidiariamente actividad empresarial, directa
o indirecta, por razón de alto interés público o de manifiesta conveniencia nacional495.
1.4. Libre competencia. El Estado facilitay vigila la libre competencia. Combate toda práctica
que la lim ite y el abuso de posiciones dominantes o monopólicas. Ninguna ley ni concertación
puede autorizar ni establecer monopolios496.
1.5. Libertad de contratar. La libertad de contratar garantiza que las partes pueden pactar vá
lidamente según las normas vigentes al tiempo del contrato. Los términos contractuales no
pueden ser modificados por leyes u otras disposiciones de cualquier clase. Los conflictos deri
vados de la relación contractual sólo se solucionan en la vía arbitral o en la judicial497.
