1.6 . Inversión nacional y extranjera. La inversión nacional y la extranjera se sujetan a las mis
mas condiciones. La producción de bienes y servicios y el comercio exterior son libres. Si otro
país o países adoptan medidas proteccionistas o discriminatorias que perjudiquen el interés
nacional, el Estado puede, en defensa de éste, adoptar medidas análogas498.
i .7. Tenencia y disposición de moneda extranjera. El Estado garantiza la libre tenenciay dis
posición de moneda extranjera499.
1.8. Protección al consumidor. El Estado defiende el interés de los consumidores y usuarios.
Para tal efecto garantizael derecho a la información sobre los bienesyserviciosqueseencuen-
tran a su disposición en el mercado. Asimismo vela, en particular, por la salud y la seguridad
de la población500.
2. Ambiente y recursos naturales
2.1. Recursos Naturales. Los recursos naturales, renovables y no renovables, son patrimonio
de la Nación. El Estado es soberano en su aprovechamiento501.
2.2. Política Ambiental. El Estado determina la política nacional del ambiente. Promueve el
uso sostenible de sus recursos naturales502.
2.3. Conservación de la diversidad biológica y áreas naturales protegidas. El Estado está
obligado a promover la conservación de la diversidad biológica y de las áreas naturales pro
tegidas503.
2.4. Desarrollo de la Amazonia. El Estado promueve el desarrollo sostenible de la Amazonia
con una legislación adecuada504.
3. Propiedad
3.1. Inviolabilidad del derecho de propiedad. El derecho de propiedad es inviolable. El Estado
lo garantiza. Se ejerce en armonía con el bien común y dentro de los límites de ley. A nadie
puede privarse de su propiedad, sino por causa de seguridad nacional o necesidad pública,
declarada por ley,y previo pago en efectivo de indemnización justipreciada que incluya com
pensación por el eventual perjuicio505.
3.2. Propiedad de los extranjeros. En cuanto a la propiedad, los extranjeros, sean personas
naturales o jurídicas, están en la misma condición que los peruanos, sin que, en caso algu
no, puedan invocar excepción ni protección diplomática. Sin embargo, dentro de cincuenta
kilómetros de las fronteras, los extranjeros no pueden adquirir ni poseer por título alguno,
