3.3. Restricciones por seguridad nacional. La ley puede, sólo por razón de seguridad nacional,
establecer temporalmente restricciones y prohibiciones específicas para la adquisición, pose
sión, explotación y transferencia de determinados bienes507.
3.4. Bienes de dominio y uso público. Los bienes de dom inio publico son inalienables e im
prescriptibles. Los bienes de uso público pueden ser concedidos a particulares conforme a ley,
para su aprovechamiento económico508.
4. Régimen tributario y presupuestal
4.1. Principio de Legalidad. Los tributos se crean, modifican o derogan, o se establece una
exoneración, exclusivamente por ley o decreto legislativo en caso de delegación de faculta
des, salvo los aranceles y tasas, los cuales se regulan mediante decreto supremo. Las leyes de
presupuesto y los decretos de urgencia no pueden contener normas sobre materia tributaria.
Las leyes relativas a tributos de periodicidad anual rigen a partir del primero de enero del año
siguiente a su promulgación509.
4.2. Deuda Pública. El Estado sólo garantiza el pago de la deuda pública contraída por go
biernos constitucionales de acuerdo con la Constitución y la ley. Las operaciones de endeu
damiento interno y externo del Estado se aprueban conforme a ley. Los municipios pueden
celebrar operaciones de crédito con cargo a sus recursos y bienes propios, sin requerir autori
zación legal510.
4 3 - Obligatoriedad de la Contrata y Licitación Pública. Las obrasy la adquisición desuminis
tros con utilización de fondos o recursos públicos se ejecutan obligatoriamente porcontratay
licitación pública, así como también la adquisición o la enajenación de bienes. La contratación
de servicios y proyectos cuya importancia y cuyo monto señala la Ley de Presupuesto se hace
por concurso público511.
4.4. Presupuesto Público. La administración económicay financiera del Estado se rige por el
presupuesto que anualmente aprueba el Congreso. La estructura del presupuesto del sector
público contiene dos secciones: Gobierno Central e instancias descentralizadas. El presupues
to asigna equitativamente los recursos públicos, su programación y ejecución responden a los
criterios de eficiencia de necesidades sociales básicas y de descentralización512.
