4 .5oProyecten -de Ley de Presupuesto., Enderademiesitoy Equilibrio Financiero, El Presidente
de la República envía al Congreso el proyecto de Ley de Presupuesto dentro de un plazo que
vence el 30 de agosto de cada año. En la misma fecha, envía también los proyectos de ley de
endeudamiento y de equilibrio financiero. El proyecto presupuestal debe estar efectivamente
