4.6. Restricciones en e! Gasto Público. Los representantes ante el Congreso no tienen iniciati
va para crear ni aumentar gastos públicos, salvo en lo que se refiere a su presupuesto514.
4.7. Sustentación del Presupuesto Público. El ministro de Economía y Finanzas sustenta,
ante la Cámara de Diputados y el Senado, reunidos en Congreso de la República, el pliego de
ingresos. Cada ministro sustenta los pliegos de egresos de su sector; previamente sustentan
los resultados y metas de la ejecución del presupuesto del año anterior y los avances en la
ejecución del presupuesto del año fiscal correspondiente. El presidente de la Corte Suprema,
el fiscal de la Nación y el presidente del Jurado Nacional de Elecciones sustentan los pliegos
correspondientes a cada institución. Si la autógrafa de la Ley de Presupuesto no es remitida
al Poder Ejecutivo hasta el treinta de noviembre, entra en vigencia el proyecto de este, que es
promulgado por decreto legislativo.
Los créditos suplementarios, habilitaciones y transferencias de partidas se tram itan ante el
Congreso de la República tal como la Ley de Presupuesto. Durante el receso parlamentario,
se tram itan ante la Comisión Permanente. Para aprobarlos, se requiere los votos de los tres
quintos del número legal de sus miembros515.
4-8. Cuenta General de la República. La Cuenta General de la República, acompañada del in
forme de auditoría de la Contraloría General de la República, es remitida por el Presidente de
la República al Congreso de la República en un plazo que vence el quince de agosto del año
siguiente a la ejecución del presupuesto.
La Cuenta General de la República es examinada y dictaminada por una comisión bicameral
integrada por igual número de senadores y diputados, conforme lo dispone el Reglamento
del Congreso, hasta el quince de octubre. El Senado y la Cámara de Diputados, reunidos en
Congreso, se pronuncian en un plazo que vence el treinta de noviembre. Si no hay pronuncia
miento del Congreso de la República en el plazo señalado, se eleva el dictamen de la comisión
bicameral al Poder Ejecutivo para que este promulgue un decreto legislativo que contenga la
Cuenta General de la República516.
4-9. Contraloría General de la República. La Contraloría General de la República es una enti
dad descentralizada de Derecho Público que goza de autonomía conforme a su ley orgánica.
Es el órgano superior del Sistema Nacional de Control. Supervisa la legalidad de la ejecución
