5. Moneda y banca
5.1. Sistema Monetario. La ley determina el sistema monetario de la República. La emisión de
billetes y monedas es facultad exclusiva del Estado. La ejerce por intermedio del Banco Central
de Reserva del Perú.518.
5.2. Banco Central de Reserva del Perú. El Banco Central es persona jurídica de derecho pú
blico. La finalidad del Banco Central es preservar la estabilidad monetaria. Sus funciones son:
regular la m oneday el crédito del sistema financiero, administrar las reservas internacionales
a su cargo, y las demás funciones que señala su ley orgánica519.
5 .3 . Reservas Internacionales. El Banco puede efectuar operaciones y celebrar convenios de
crédito para cubrir desequilibrios transitorios en la posición de las reservas internacionales.
Requiere autorización por ley cuando el monto de tales operaciones o convenios supera el
límite señalado por el Presupuesto del Sector Público, con cargo de dar cuenta al Congreso520.
5.4. Directorio del Banco Central de Reserva. El Banco Central de Reserva es gobernado por
un Directorio de siete miembros. El Poder Ejecutivo designa a cuatro, entre ellos al presidente.
El Senado ratifica a éste y elige a los tres restantes con la mayoría absoluta del número legal
de sus miembros521.
5.5. Superintendencia de Banca y Seguros. El Estado fomenta y garantiza el ahorro. La ley
establece las obligaciones y los límites de las empresas que reciben ahorros del público, así
como el modo y los alcances de dicha garantía. La Superintendencia de Banca, Seguros y Ad
ministradoras Privadas de Fondos de Pensiones ejerce el control de las empresas bancarias,
de seguros, de administración de fondos de pensiones, de las demás que reciben depósitos
del público y de aquellas otras que, por realizar operaciones conexas o similares, determine
la ley522.
6. Régimen agrario y comunidades campesinas y nativas
El Estado apoya preferentemente el desarrollo agrario. Garantiza el derecho de propiedad so
bre la tierra, en forma privada o comunal o en cualquiera otra forma asociativa. Las tierras
