BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1267 of 1506 --

Temas de Consum idor
I. DEFINICION
La nueva realidad social y económica ha impulsado la creación del novísimo Derecho del Con
sumidor o Derecho de los Consumidores, como una rama jurídica especial, m ultidisplinaria,
cuya función principal es la de protección del consumidor de bienes y servicios, figurando en
su contenido temas como: la masificación de las relaciones de consumo; la información veraz,
adecuada y oportuna al consumidor; la composición de los productos y servicios y el control
de calidad y seguridad de los mismos; la invalidez de las cláusulas contractuales abusivas; el
control administrativo de la contratación estándar; la problemática del acceso a la justicia y
de la representación de los consumidores; la criminalidad del consumo; la protección contra
productos y servicios riesgosos; la publicidad engañosa y abusiva; el combate a los monopo
lios y oligopolios; el derecho a un medio ambiente sano; la interpretación de la contratación
masiva in dubio pro consumidor.
En el Perú el Derecho de los Consumidores está regulado por el Código de Protección y De
fensa del Consumidor (en adelante CPDC) aprobado mediante Ley N° 29571, publicada en el
diario El Peruano con fecha 02.09.201 o, dispositivo que derogo las múltiples leyes especiales
existentes en esta materia.
El CPCD instituye como primordial su finalidad es instituir la protección de los derechos de
los consumidores como principio rector de la política social y económica del Estado. Para ello
promueve el acceso a una diversidad de productosy servicios idóneos reduciendo la asimetría
informativay fomentando la libertad de elección en un marco de librey honesta competencia,
con sujeción a la Constitución y al ordenamiento jurídico nacional.
Su prioridad es proteger al consumidor que se encuentra directa o indirectamente expuesto o
comprendido por una relación de consumo. Además, sus disposiciones se aplicarán a las rela
ciones de consumo que se celebran en el territorio nacional o cuando sus efectos se producen
en éste, con excepción de las operaciones a título gratuito, salvo que tengan un propósito co
mercial dirigido a fomentar el consumo. Para la aplicación del CPCD se tomará como referen-
ciael parámetro de un consumidorque actúa de buenafey diligenciaordinaria. Mientrasque,
en el proveedor, será en base al principio de buena fe, lealtad comercial y de razonabilidad.
Señala también que el Instituto Nacional de Defensa de la Competenciay de la Protección de
la Propiedad Intelectual (INDECOPI), en su calidad de Autoridad Nacional de Protección del
Consumidor, ejerce las atribuciones y funciones que le confieren las leyes, para velar por el
cumplim iento de las disposiciones contenidas en el presente texto, sin perjuicio de las atribu-
cionesy autonomía de los demás integrantes del sistema.
Crea el Sistema Nacional Integrado de Protección del Consumidor, como el conjunto de prin
cipios, normas, procedimientos, técnicas e instrumentos destinados a armonizar las políticas
públicas con el fin de optim izar las actuaciones de la administración del Estado para garanti
zar el cumplim iento de las normas de defensa del consumidor en todo el país.
