UBILEX
II. BIEN JURÍDICO PROTEGIDO EN EL DERECHO DEL CONSUMIDOR
1. La buena fe, el principio de veracidad y lealtad propio de los actos jurídicos y de comercio
que impiden un proceder empresarial que sea abusivo, perjudicial o induzca a error al
consumidor.
2. El Interés Humano. - El hombre debe proveer a la seguridad, salud y confort, sin llegar a
desproteger al empresario.
3. El interés económico también merece protección, los detrimentos sufridos en su patri
monio por abuso empresarial deben ser reparados de algún modo.
III. MARCO NORMATIVO DE LA PROTECCIÓN AL CONSUMIDOR
En los últim os años la protección del consum idor constituye una de las disciplinas que ha
generado gran preocupación en la política económica de la mayoría de los países, y por
ello se le trata de proteger en diferentes niveles, como ejem plo podemos citar a la Organi
zación M undial de la Propiedad Intelectual (OMPI), que ha puesto mucha atención en el
tema de los derechos de los consumidores.
Para la efectiva protección del consum idor debe asegurarse la existencia de un merca
do libre y com petitivo; reprim iendo las prácticas desleales, procurar una publicidad leal,
constituir un órgano estatal ante el cual se reclame y se puedan resolver los problemas
planteados por los consumidores de manera ráplday eficaz,y a través del cual se verifique
el expendio de productos en buenas condiciones y se garantice que los consumidores no
sean engañados por productos que utilizan etiquetas y marcas falsificadas.
En el ám bito nacional el Derecho del Consumidor se integra por normas contenidas en la
Constitución, en el Código de Protección y Defensa del Consumidor, el Código Civil y, una
que otra, en los otros códigos (Derecho codificado); y por las normas contractuales con
tenidas en los contratos estándar (normas particulares), cuyo esquema contractual está
siempre presto a ser m odificado unllateralm ente, en un proceso de adecuación cerrado y
veloz, según las m utables exigencias de los empresarios predisponentes.
U dLrtícu.\o65de\dLC onst\t[ic\ónd\$ponec\[ieuelEstadodefendeel¡nterésdelosconsumidoresyusua--
rios. Para ta l efecto g a ra n tiza el derecho a ia inform ación sobre ¡os bienesy servicios que se encuentran
a su disposición en el mercado. Asim ism o vela, en particular, porla saludy Ia seguridad de la población”.
La decidida defensa de los intereses de los consum idoresy usuarios, asumida por la Cons
titución de 1993, es explicada por Carlos Torres y Torres Lara525, señalando, en prim er lugar,
la Constitución vigente traslada el control económico más hacia la defensa del consum i
dor, ya que el centro del Derecho Empresarial, deja de ser la empresa misma, para trasla
darse a la relación “em presa-consum idor”, que es donde el Estado ahora puede jugar un
papel más objetivo.
“Cada tiem po tiene su núcleo de tensión- señala Torres y Torres Lara-y esto se refleja en
el Derecho, el cual no es más que la síntesis de la ideología de su época. Así, durante el
525 Torres y Torres Lara, Carlos: La constitución económica en el Perú. Desarrollo y Paz Editores. Lima Noviembre 1994,
pp. 9iy ss.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1269 of 1506 --

Temas de Consum idor
desarrollo del Derecho Romano, el centro de las tensiones estuvo vinculado al propietario
inm obiliario. Luego desde el siglo XV el Derecho se centra en la protección preferencial
del propietario m obiliario, base del desarrollo del capitalism o inicial, que se difundiría
a partir de las libertades consagradas por la Revolución Francesa, hasta la aparición del
fenómeno socialista, desde el cual el núcleo se ubica en el trabajador. Con el desarrollo de
la sociedad de consumo hoy se abre un nuevo centro de tensión: el consumidor".
Es así, que el artículo 130o de la Constitución de 1979, era inspiración- según Torres y To
rres Lara- de otra época en la que el centro del derecho era la Empresa. Ahora, siendo la
relación “Empresa-Consumidor” lo central, entonces, otro es el rum bo que debe asum irel
Derecho, en este caso, la protección del consumidor. Este nuevo concepto- añade Torres
y Torres Lara - de gestión estatal, suprim e el control de la llam ada eficiencia empresarial
contenido en la anterior Constitución y lo sustituye por el control del producto m ediante
la gestión del propio consum idor a quien se le garantiza la inform ación apropiada para
su defensa.
Se expresa así, que el Estado defiende el interés de los consumidores y usuarios y, para tal
efecto, garantiza el derecho a la información sobre los bienesy servicios que se encuentran
a disposición en el mercado. Con ello se genera una obligación para la empresa- como es
el de inform ar convenientemente-y, para el consum idor un derecho a la inform ación- o
derecho a ser inform ado idóneamente-. Esto es consecuencia de lo que se ha venido en
llam ar el problema de la asimetría inform ativa entere laem presay el consumidor, lo que
busca ser contrarrestado por el derecho a la información del consumidor.
El Código Civil tutela y garantiza los derechos de los consumidores y usuarios al regular
sobre los contratos p o rad he sión y los contratos concluidos mediante cláusulas generales
de contratación. M ientras que el contrato de adhesión coloca a una de las partes en la
alternativa de aceptar o rechazar el íntegro del contenido contractual pre redactado p o rla
otra, las cláusulas generales de contratación son redactadas por una de las partes, en for
ma general y abstracta, con miras a que sirvan de marco a una serie de contratos particu
lares futuros con elementos propios. La adhesión se refiere al contenido integral del con
trato, mientras que las cláusulas generales se refieren al contenido parcial del contrato.
En el mercado, la adquisición de bienes y servicios generalmente se hace mediante contratos
concluidos por adhesión o cláusulas generales de contratación. De ahí que existe, más que di
ferencias, una estrecha vinculación entre el sector del ordenamiento jurídico civil que regula
los contratos por adhesión y los concluidos mediante cláusulas generales con el denominado
Derecho del Consumidor, persiguiendo con ambos ordenamientos jurídicos proteger al con-
sumidorcon especial referencia a la invalidez o ineficacia de las cláusulas abusivas.
El Código de Protección y Defensa del Consumidor subsana muchas deficiencias del con
tenido del D. S. 006-2009-PCM y trae la vez muchas novedades entre ellas, esta norm a
reconoce al INDECOPI como autoridad nacional de consumo y ente rector del Sistema
Nacional Integrado de Protección al Consumidor.
El CPDC establece que el acceso a productos y servicios, por parte de los consumidores, se
haga dentro del marco de una economía social de mercado, conform e a lo establecido en
la Constitución Política del Perú.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1270 of 1506 --

UBI LEX
Asimismo, busca que, dentro de toda relación de consumo, las personas gocen de sus de
rechos como consumidores; además establece mecanismos que garantizan su protección,
corrigiendo, previniendo y elim inando conductas que afecten sus legítimos intereses.
En este sentido, el CPDC, se convierte en la única norma en m ateria de protección a los
derechos del consumidor, quedando derogadas las disposiciones legales anteriores.
Otra de las innovaciones se encuentra en el libro de reclamaciones, que una vez que se
encuentre reglamentado, facilitará la atención de los reclamos de las personas cada vez
que sus derechos sean vulnerados, garantizando la solución de los mismos.
Otra novedad es la solución de las denuncias vinculadas a productos o servicios cuya valori
zación no superen las 03 UIT, en no más de 30 días hábiles. Para ello se crearán los llamados
"órganos resolutivos de procedimientos sumarísimos”.
El CPDC prohíbe los métodos comerciales agresivos y engañosos que afecten la libertad de
elección de los consumidores, a través de figuras como el acoso o la coacción. Por ejemplo, se
rán sancionadas aquellas prácticas comerciales que hacen creeral consumidorque ha ganado
o ganará un premio cuando en realidad no es así, con el fin de hacerlo adquirir algún bien o
servicio.
En cuanto a los seguros de salud, el CPDC establece, entre otras condiciones, que los provee
dores no podrán variar unilateralmente las condiciones referidas a preexistencias para elim i
nar las coberturas inicialmente pactadas, incluso en las renovaciones de planes o seguros de
salud.
Asimismo, precisa la protección a los consumidores más vulnerables como madres gestantes,
niños, adultos mayores, personas con discapacidad y pobladores de zonas rurales y de extre
ma pobreza. Contempla programas de educación sobre los derechos del consumidor dentro
de la curricula escolar, entre otras mejoras.
El CPDC a la vez que innova también ratifica otras disposiciones legales que se dieron con an
terioridad así como la jurisprudencia emitida por el INDECOPI, en beneficio de los consumi
dores; el derecho a información veraz, suficientey de fácil comprensión; a no ser discriminado
en locales abiertos al público; a que se le informe mediante lista de precios sobre los productos
que se le ofrecen; entre otros.
IV. PRINCIPIOS DEL DERECHO DEL CONSUMIDOR
EL CPDC establece los siguientes principios en pro de la protección de los derechos del con
sumidor:
1. Principio de Soberanía del Consumidor.- Las normas de protección al consumidor fo
mentan las decisiones libres e informadas de los consumidores, a fin de que con sus de
cisiones orienten el mercado en la mejora de las condiciones de los productos o servicios
ofrecidos.
2. Principio Pro Consumidor.- En cualquier campo de su actuación, el Estado ejerce una ac
ción tuitiva a favor de los consumidores. En proyección de este principio en caso de duda
insalvable en el sentido de las normas o cuando exista duda en los alcances de los con
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1271 of 1506 --

Temas de C onsum idor
tratos por adhesión y los celebrados en base a cláusulas generales de contratación, debe
interpretarse en sentido más favorable al consumidor.
3. Principio de Transparencia.- En la actuación en el mercado, los proveedores generan
una plena accesibilidad a la información a los consumidores acerca de los productos o
servicios que ofrecen. La información brindada debe ser veraz y apropiada conforme al
presente Código.
4. Principio de Corrección de la Asimetría.- Las normas de protección al consumidor bus
can corregir las distorsiones o malas prácticas generadas por la asimetría informativa o la
situación de desequilibrio que se presente entre los proveedores y consumidores, sea en
la contratación o en cualquier otra situación relevante, que coloquen a los segundos en
una situación de desventaja respecto de los primeros al momento de actuar en el merca
do.
5. Principio de Buena Fe.- En la actuación en el mercado y en el ámbito de vigencia del
presente Código, los consumidores, los proveedores, las asociaciones de consumidores,
y sus representantes, deben guiar su conducta acorde con el principio de la buena fe de
confianzay lealtad entre las partes. Al evaluar la conducta del consumidorse analizan las
circunstancias relevantes del caso, como la información brindada, las características de la
contratación y otros elementos sobre el particular.
6. Principio de Protección Mínima.- El presente Código contiene las normas de mínima
protección a los consumidores y no impide que las normas sectoriales puedan dispensar
un nivel de protección mayor.
7. Principio Pro Asociativo.- El Estado facilita la actuación de las asociaciones de consumi
dores o usuarios en un marco de actuación responsabley con sujeción a lo previsto en el
presente Código.
8. Principio de Primacía de la Realidad.- En la determinación de la verdadera naturaleza
de las conductas, se consideran las situacionesy relaciones económicas que efectivamen
te se realicen, persigan o establezcan. La forma de los actos jurídicos utilizados en la re
lación de consumo no enerva el análisis que la autoridad efectúe sobre los verdaderos
propósitos de la conducta que subyacen al acto jurídico que la expresa.
V. COMPETENCIA DE INDECOPi
Proteger los derechos de propiedad Intelectual en todas sus manifestaciones (art. 30 Ley
25868)
Defender la libre y leal competencia, sancionando las conductas anticompetitivas y des
leales.
Corregir las distorsiones en el mercado provocadas por el daño derivado de prácticas de
dumping.
Proteger los derechos de los consumidores. (Art. 1 Ley 29571)
Regula la relación Consumidor-Proveedor.
