VI. RELACIÓN DE CONSUMO
Es la relación por la cual un consumidor adquiere un producto o contrata un servicio con un
proveedora cambio de una contraprestación económica.
En una relación de consumo las partes son aquellas que, de un lado contratan la adquisición
de un bien o la prestación de un servicio para sí mismo o su entorno inmediato (familia), y de
otro lado el proveedor de tal bien o servicio, quien recibe además la contraprestación debida
de parte de ese consumidor.
Este cgncepto funciona muy bien en la gran mayoría de casos, pero resulta insuficiente cuan
do los efectos de esa relación de consumo se proyectan hacia terceras personas que, en un co
mienzo, no han participado ni se han beneficiado de la relación original. Al respecto la Sala de
Protección al Consumidor del Tribunal de INDECOPI emitió una resolución que interpreta de
modo más extenso el numeral i del artículo III del Título Preliminar del Código de Protección
al Consumidor (Resolución N° 0951-2013/SPC-lndecopi), en un caso en que una persona recibía
constantemente notificaciones de una entidad financiera, la cual pretendía cobrar una deuda a
un tercero que, por alguna razón, había tenido o no alguna relación con el inmueble ocupado
por la denunciante, que reclamaba por estos actos de cobranza. En la medida que los efectos de
la relación de consumo entre el deudor original y la entidad financiera se proyectaban hasta la
persona que sufría los actos de cobranza sin culpa alguna, la sala admitió que estaba ante una
relación de consumo especial, por supuesto limitada a los aspectos en los que se concretaban di
chos efectos (la persona reclamante no podría, porejemplo, discutirla prescripción de la deuda).
1. Noción del consumidor
Según el diccionario de la Real Academia Española, consumidor es aquél que consume, es
decir, que utiliza un bien o servicio para satisfacer una necesidad.
De acuerdo a lo establecido en la Carta Europea de Protección del Consumidor: “el consumi
dores una persona física o jurídica a la cual le son vendidos o suministrados bienes y/o servi
cios para la satisfacción de sus necesidades”.
Conforme a la norm ativa contenida en el Código de C onsum oy al desarrollo jurispruden
cial de la Sala de Defensa de la Competencia N° 2 del Tribunal del INDECOPI, califican
como consumidores las personas naturales o jurídicas que utilicen o disfruten como des
tinatarios finales productos o servicios en beneficio propio, actuando en una esfera ajena
a su actividad profesional o empresarial. Nose considera consum idor para efectos aquien
adquiere, utiliza o disfruta de un producto o servicio norm alm ente destinado para los fi
nes de su actividad como proveedor.
2. Proveedores
Se consideran proveedores según el CPCD todas las personas naturales o jurídicas, de dere
cho público o privado, que de manera habitual fabrican, elaboran, manipulan, acondicionan,
mezclan, envasan, almacenan, preparan, expenden, suministran productos o prestan servi
cios de cualquier naturaleza a los consumidores. (Artículo IV CPCD).
