Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1273 of 1506 --

Temas de Consum idor
3. Infracciones del derecho del consumidor
Constituye infracción administrativa la conducta del proveedor que transgrede las dispo
siciones del CPCD, tanto si ello implica violar los derechos reconocidos a los consumidores
como incumplir las obligaciones que estas normas imponen a los proveedores. También son
supuestos de infracción administrativa el incumplimiento de acuerdos conciliatorios o de lau
dos arbitrales y aquellos previstos en el Decreto Legislativo núm. 807, Ley sobre Facultades,
Normas y Organización del IndecopLy en las normas que lo complementen o sustituyan.
4. Asimetría informativa
La Asimetría Informativa es una característica intrínseca a cualquier transacción económica
(e incluso a otros aspectos sociales), en tanto que siempre en un intercambio de bienes y ser
vicios habrá un actor mejor informado que otro. En efecto, dicho actor suele tener mayor y
mejor información sobre los productos y servicios que ofrece en el mercado, loque genera que
ciertas prácticas puedan distorsionar excepcionalmente el buen funcionamiento del mismo.
En términos económicos, la asimetría informativa genera costos de transacción en el merca
do, los cuales deben entenderse como aquéllos en los que las partes deben incurrir para llegar
a celebrar un contrato que satisfaga de la mejor manera posible sus intereses, tendiendo así a
maximizar la utilidad social.
En este sentido, del concepto de Asimetría Informativa se desprenden dos aspectos que se
encuentran estrechamente vinculados como dos caras de la misma moneda: el deber de in
formación y el deber de garantizar la idoneidad.
Deber de inform ación: El deber de información de los proveedores debe ser entendido como
el derecho de los consumidores a recibir de los proveedores toda la información necesaria y
oportuna para tom ar una decisión adecuada en la adquisición de un producto.
Deber de g a rantizar idoneidad: Se presenta un supuesto de falta de idoneidad cuando no existe
coincidencia entre lo que el consumidor esperay lo que el consumidor recibe; naturalmente
lo que el consumidor espera depende de la calidady cantidad de información que le ha brin
dado el proveedor.
El TC, mediante la Resolución N° 0422-2003/TDC-INDECOPI de fecha 3 de octubre de 2003,
emitió el precedente de observancia obligatoria en el que se dispuso: “(...) 3. Las personas natura-
lesy jurídicas pertenecientes a la categoría profesional de los pequeños empresarios son también sujetos
afectados por la desigualdad inform ativa en la relación de consumo y, por tanto, son considerados como
consumidores para efectos de la Ley de Protección al Consumidor cuando debido a las necesidades de su
actividad empresarial adquieran o utilicen productos,ya sean bienes o servicios, 13 para cuya adquisición
o uso no fuera previsible que debieran contar con conocimientos especializados equiparables a aquellos
de los proveedores.”
Es decir, se reitera que el eje de la tutela de la Ley de Protección del Consumidores la asimetría
informativa, la que no puede ser superada fácilmente por lo costoso que resulta a los consu
midores obtener información a diferencia de los proveedores. Sin embargo, este costo no es
simétrico ni igualmente proporcionado y costoso para todos los “proveedores" que durante el
proceso de circulación asumen el rol de “consumidores intermedios”. Ello ha llevado a consta
