tar que hay situaciones en las que un pequeño empresario se halla en una situación análoga a
la de cualquier destinatario final y que ello justifica la protección de dicha categoría en ciertos
supuestos de asimetría informativa.
Dispone también el TC sobre la determinación de “asimetría informativa” entre proveedor y
consumidoren la Resolución N °0397-2012/SC2-INDECOPI, de fecháis de febrero de 2012, en
los seguidos por Jawar Motos Industriales Alejandro E.I.R.L. contra Empresa de Transportes
Romy S.A.C. (Exp. 163-2009/CPC-l N DECOPI-PUN): “Teniendo en cuenta que el servicio de transporte
de encomienda contratado no se encuentra relacionado al giro de negocio de la denunciante, se presume
que se encontraba en asimetría inform ativa respecto a dicho proveedor. Cabe indicar que, Transportes
Romy no ha presentado ningún medio probatorio que pueda desvirtuar dicha presunción, como pudo ser,
por ejemplo, documentos que demostraran una habitualidad en la contratación del servicioy colocaran a
Jawar M IA en una posición superior a la de cualquier consumidor ordinario en términos de información”.
5. Discriminación en el consumo
En el ámbito del consumo, los artículos i° d) y 38o del CPCD regulan el tipo infractor de discri
minación en el consumo. Asimismo, el artículo 3 9 ° regula la probanza de causas objetivas y
justificadas por parte de los proveedores, a efectos de desvirtuar su responsabilidad por este
tipo infractor. Así, tenemos:
Artículo I o.- Derecho de los consumidores 1.1 En los términos establecidos por el presente Código, los
consumidores tienen los siguientes derechos: (...) d. Derecho a un trato justo y equitativo en toda tran
sacción comercial y a no ser discriminados por motivo de origen, raza, sexo, idioma, religión, opinión,
condición económica o de cualquier otra índole. (...)
Artículo 38°.- Prohibición de discriminación de consumidores 38.1 Los proveedores no pueden establecer
discriminación alguna por motivo de origen, raza, sexo, idioma, religión, opinión, condición económica o de
cualquier otra índole, respecto de los consumidores, se encuentren estos dentro o expuestos a una relación
de consumo. 38.2 Está prohibida la exclusión de personas sin que medien causas de seguridad del estable
cimiento o tranquilidad de sus clientes u otros motivos similares. 38.3 El trato diferente de los consumidores
debe obedecer a causas objetivas y razonables. La atención preferente en un establecimiento debe responder
a situaciones de hecho distintas que justifiquen un trato diferente y existir una proporcionalidad entre el fin
perseguido y el trato diferente que se otorga.
Al respecto la Sala de Defensa de la Competencia N° 2 Resolución 2135-2.012/SC2-INDECOPl
(Exp. N° 272-2011/CPC) en un caso reciente determino: “42. Consideramos im portante subrayar
que la negativa de Rímaca a filia ra la señorita Céliz al Seguro de Asistencia Médica “Red Salud”, siempre
se basó en la condición particular de esta últim a, esto es, en el hecho de que tenía Síndrome de D ow ny
sus eventuales consecuencias, no siendo esta una circunstancia que haya sido controvertida a lo largo del
presente procedimiento. Ello, sumado a que las personas con discapacidad constituyen un grupo consti
tucionalmente protegido frente a la discriminación y a que la justificación de Rímac para el trato acor
dado a la señorita Céliz, hija del denunciante, conforme invoca, ha sido desvirtuada precedentemente,
constituye evidencia suficiente de que en el presente caso se configuró el tipo infractor de discriminación
agravada contemplada por el artículo 38odel Código, esto es, discriminación en el consumo”.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1275 of 1506 --

Temas de Consum idor
6. Contratos de consumo
El contrato de consumo se define como el contrato celebrado entre dos partes, uno el proveedor
y otro el consumidor, para la compraventa de un producto o servicio, a cambio de una contrapres
tación. En esta relación contractual, el proveedor actúa de acuerdo a su quehacer profesional, es
el que tiene la información, por cuanto habitualmente fabrica y/o comercializa los productos
que vende, o es el que presta los servicios que ofrecey conoce el ámbito del negocio que maneja.
El proveedor es el que tiene la información del objeto del contrato y la otra parte es el consu
midor, usuario o destinatario final del producto o servicio, es la parte que adquiere los pro
ductos, utiliza los servicios, siendo ajeno a ellos, desconoce el ámbito del negocio, desconoce
profesionalmente sobre el objeto del contrato, tiene una mínima información, por ello carece
de poder de negociación real.
El proveedor o profesional es quien redacta el contrato tipo o la cláusula contractual, por lo
que en virtud del principio de la buena fe objetiva debe hacerlo de modo claro, sin tergiversar
ni obscurecer el sentido usual de las palabras. Asimismo, debe informar de modo transparen
te y comprensible a la otra parte, quien se entrega confiada a la conducta leal del proveedor.
De no proporcionar la información idónea, claray completase produciría un desbalance infor
mativo, que desequilibra la posición de una de las partes que es el consumidor, quien no tiene
un fuerte poder de negociary por el lo va elegir contratar o aceptar la cláusula predispuesta, en
una situación de desventaja.
En el caso de contratación por vía electrónica, telefónica o bajo cualquier sistema de atención
automatizada asistido por inteligencia artificial o asistente digital, el proveedor es responsa
ble de acreditar que la información fue puesta oportunamente a disposición del consumidor
y que este aceptó los términos contratados. Asimismo, cuando el consumidor solicite copia
de los documentos que acrediten la contratación, aplica el plazo establecido en el literal e);
siendo el proveedor responsable de su entrega.
6.1. Contrato de consumo por adhesión
En los contratos de consumo celebrados por adhesión o con cláusulas generales de contrata
ción, debe cumplirse con los siguientes requisitos:
a. Concreción, claridad y sencillez en la redacción, con posibilidad de comprensión direc
ta, sin reenvíos a textos o documentos que no se faciliten previa o simultáneamente a la
conclusión del contrato, y a los que, en todo caso, debe hacerse referencia expresa en el
documento contractual.
b. Accesibilidady legibilidad, de forma que permita al consumidory usuario el conocimien
to previo del contenido del contrato antes de su suscripción.
c. Buena fey equilibrio necesario en los derechosy obligaciones de las partes, lo que en todo
caso excluye la utilización de cláusulas abusivas.
7. Cláusulas abusivas
De acuerdo con el concepto de cláusula abusiva definida en el art. 49 del CPCD, se pueden
identificar las siguientes características que contienen dichas cláusulas: “se consideran cláusulas
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1276 of 1506 --

abusivas y, por tanto, inexigibles todas aquellas estipulaciones no negociadas individualmente que, en
contra de las exigencias de la buena fe, coloquen al consumidor, en su perjuicio, en una situación de des
ventaja o desigualdad o anulen sus derechos.”
El abuso se da en el perjuicio que el proveedor produce a la otra parte, quien acepta la cláusula
sin haberla redactado.
Se determina legalmente que una cláusula es abusiva o ilícita para restablecer el equilibrio
contractual entre las partes, en la etapa precontractual impidiendo que el proponente de las
condiciones generales cometa un abuso sobre el contratante débil o en la etapa postcontrac
tual estableciendo sanciones, en caso de incumplimiento.
El concepto o tipificación de cláusula abusiva se plasma en el ámbito del contrato de con
sumo, es decir, en la relación entre proveedores o empresarios y consumidores o usuarios y
puede darse tanto en las condiciones generales de la contratación, como en las cláusulas pre
dispuestas en un contrato particular, en el que el consumidor se lim ita a adherirse, y no hay
negociación individual. Esto significa que en las cláusulas contractuales entre profesionales o
entre personas donde hay una relación horizontal y una negociación no se incurre en este tipo
de cláusula y si hubiere abuso, las partes se sujetarían a las normas contractuales del Código
Civil, a fin de que se declare la nulidad de la cláusula que es contraria a la buena fe o a los ele
mentos del contrato.
VI. MEDIDAS CORRECTIVAS:
Conforme al art. 114 del CPCD, son aquellas medidas dictadas por el INDECOPI, al margen de
la sanción administrativa impuesta al proveedor, por una infracción al CPCD, estás pueden ser
dictadas en calidad de mandatos.
Son de dos clases:
7.1. Medidas correctivas reparadoras, tienen el objeto de resarcir las consecuencias patrimo
niales directas e inmediatas ocasionadas al consumidor por la infracción administrativa a su
estado ánteriory pueden consistir en ordenar al proveedor infractor lo siguiente:
a. Reparar productos.
b. Cambiar productos porotrosde idénticas o similares características, cuando la reparación
no sea posible o no resulte razonable según las circunstancias.
c. Entregar un producto de idénticas características o, cuando esto no resulte posible, de si
milares características, en los supuestos de pérdida o deterioro atribuible al proveedory
siempre que exista interés del consumidor.
d. Cumplir con ejecutar la prestación u obligación asumida; y si esto no resulte posible o no
sea razonable, otra de efectos equivalentes, incluyendo prestaciones dinerarias.
e. Cumplir con ejecutar otras prestaciones u obligaciones legales o convencionales a su car
go.
f. Devolver la contraprestación pagada por el consumidor, más los intereses legales corres
pondientes, cuando la reparación, reposición, o cumplim iento de la prestación u obliga
ción, según sea el caso, no resulte posible o no sea razonable según las circunstancias.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1277 of 1506 --

Temas de Consum idor
g. En los supuestos de pagos indebidos o en exceso, devolver estos montos, más los intere
ses correspondientes.
h. Pagar los gastos incurridos por el consumidor para mitigar las consecuencias de la infrac
ción administrativa.
i. Otras medidas reparadoras análogas de efectos equivalentes a las anteriores.
7.2. Medidas correctivas complementarias, las medidas correctivas complementarias tienen
el objeto de revertir los efectos de la conducta infractora o evitar que esta se produzca nueva
mente en el futuro y pueden ser, entre otras, las siguientes:
a. Que el proveedor cumpla con atender la solicitud de información requerida por el con
sumidor, siempre que dicho requerimiento guarde relación con el producto adquirido o
servicio contratado.
b. Declarar inexigibles las cláusulas que han sido identificadas como abusivas en el procedi
miento.
c. El decomiso y destrucción de la mercadería, envases, envolturas o etiquetas.
d. En caso de infracciones muy graves y de reincidencia o reiterancia:
(i) Solicitar a la autoridad correspondiente la clausura temporal del establecimiento
industrial, comercial o de servicios por un plazo máximo de seis (6) meses.
(ii) Solicitar a la autoridad competente la inhabilitación, temporal o permanente, del
proveedor en función de los alcances de la infracción sancionada.
e. Publicación de avisos rectificatorios o informativos en la forma que determine el Indeco-
pi, tomando en consideración los medios que resulten idóneos para revertir los efectos
que el acto objeto de sanción ha ocasionado.
f. Cualquier otra medida correctiva que tenga el objeto de revertir los efectos de la conducta
infractora o evitar que esta se produzca nuevamente en el futuro.
VIII. PROTECCIÓN DEL CONSUMIDOR FINANCIERO
La materia de protección al consumidor de los servicios financieros prestados por las empre
sas supervisadas por la Superintendencia de Banca, Seguros y Administradoras Privadas de
Fondos de Pensiones se rige por las disposiciones del CPCD, así como por las normas especia
les establecidas en la Ley N° 28587, Ley Complementaria a la Ley de Protección al Consumidor
en Materia de Servicios Financieros, y las normas reglamentarias emitidas para garantizar su
cumplimiento.
La regulación y supervisión del sistema financiero así como los productos y servicios se rige
en virtud del principio de especialidad normativa por la Ley N° 26702, Ley General del Sistema
Financiero y del Sistema de Seguros y Orgánica de la Superintendencia de Banca y Seguros.
IX. PROTECCIÓN DEL CONSUMIDOR INMOBILIARIO
El derecho del consumidor a la información obliga al proveedor de productos y servicios in
mobiliarios a informar sobre las características sobre el inmueble que está adquiriendo así
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1278 of 1506 --

UBILEX
como a proporcionar toda aquella información que acredite la existencia de autorizaciones
municipales, el área del inmueble, el proceso de titulación, habilitación urbana, saneamiento,
materiales empleados en la construcción y en los acabados, inscripciones regístrales del te
rreno y declaratoria de fábrica o de edificación, reglamento interno, independización y toda
aquella documentación relevante.
En toda la publicidad escrita de bien inmueble futuro de primer uso, las promotoras inm obi
liarias y las empresas constructoras de unidades inmobiliarias deben consignar la informa
ción mínima en el proceso de compra.
X. PROTECCIÓN DEL CONSUMIDOR DE PRODUCTOS Y SERVICIOS EDUCATIVOS
El proveedor de servicios educativos debe tener en consideración los lineamientos generales
del proceso educativo en la educación básica, técnico-productiva y educación superior, asegu
rando la calidad de los servicios dentro de la normativa sobre la materia.
Los derechos esenciales del consumidoren los productosy servicios educativos son: Atendien
do a la especialidad de los productosy servicios educativos, el consumidor tiene derecho esen
cialmente a lo siguiente:
a. Que se le brinde por escrito información veraz, oportuna, completa, objetiva y de buena
fe sobre las características, condiciones económicas, ventajas y demás términos y condi
ciones del producto o servicio.
b. Que se le cobre la contraprestación económica correspondiente a la prestación de un ser
vicio efectivamente prestado por el proveedor de servicios educativos.
c. Que se le informe antes de que se inicie el proceso de contratación sobre los documentos,
certificaciones, licencias o autorizaciones con que cuenta el proveedor para desarrollar
lícitamente la actividad.
d. Que se le informe de manera clara y destacada sobre la naturaleza y condiciones de la
certificación que será otorgada a la conclusión del programay servicio contratado.
e. Que no se condicione la entrega del documento que acredite, certifique o deje constancia
del uso o desarrollo del producto o servicio a pago distinto del derecho de trámite, salvo
en el caso de que el usuario registre deuda pendiente con la institución educativa, en con
cordancia con la legislación sobre la materia.
f. Que se tomen medidas inmediatas de protección cuando el servicio afecta el proceso for-
mativo de los niños, niñasy adolescentes.
g. Que la institución educativa difunday promueva objetivamente las ventajasy cualidades
que ofrecen a los usuarios.
La enumeración de los derechos establecidos en esta norma no excluye los demás que
la Constitución o normas especiales garantizan ni otros de naturaleza análoga o que se
fundan en el respeto de los derechos reconocidos en el presente Código.
