XI. DEFENSA COLECTIVA DE LOS CONSUMIDORES
El ejercicio de las acciones en defensa de los derechos del consumidor puede ser efectuado a
título individual o en beneficio del interés colectivo o difuso de los consumidores. Para estos
efectos se entiende por:
a. Interés colectivo de los consumidores.- Son acciones que se promueven en defensa de
derechos comunes a un conjunto determinado o determinable de consumidores que se
encuentren ligados con un proveedor y que pueden ser agrupados dentro de un mismo
grupo o clase.
b. Interés difuso de los consumidores.- Son acciones que se promueven en defensa de un
conjunto indeterminado de consumidores afectados.
Están legitimadas para form ular denuncias ante la Comisión de Protección al Consum idory
ante los demás órganos funcionales competentes del Indecopi, las asociaciones de consumi
dores debidamente reconocidas por el Indecopi.
Las asociaciones de consumidores son organizaciones que se constituyen de conformidad con
las normas establecidas para tal efecto en el Código Civil. Su finalidad es proteger, defender,
inform ary representara los consumidoresy usuarios.
En la vía judicial pueden promover procesos en defensa de los intereses difusos o colectivos de
los consumidores, sujetándose a lo previsto en los artículos 130y 131.
La legitim idad de las asociaciones de consumidores se extiende también para actuar a nom
bre de sus asociados y de las personas que les hayan otorgado poder ante los organismos re
guladores de los servicios públicos en los procesos en materia de protección al consumidor, así
como en defensa de los intereses difusos o colectivos de los consumidores.
Para efectos de la independencia y transparencia de las asociaciones de consumidores, estas
no pueden:
a. Incluir como asociadas a personas jurídicas con fines de lucro.
b. Percibirfinanciamiento de los proveedores que comercializan productos y servicios.
c. Dedicarse a actividades distintas a su finalidad o incompatibles con ella.
d. Destinar los fondos públicos entregados por concepto de multas para una finalidad dis
tinta a la asignada.
e. Actuar con manifiesta temeridad presentando denuncias maliciosas debidamente san
cionadas en la vía administrativa o judicial.
f. Incumplir las disposiciones establecidas por el presente Código o las resoluciones em iti
das por el Consejo Directivo del Indecopi sobre la materia.
El incumplimiento de cualquiera de estas disposiciones es sancionado por el Indecopi con la
suspensión o la cancelación del registro especial hasta por un período de dos (2) años, previo
procedimiento, teniendo en cuenta la gravedad o el reiterado incumplimiento de las disposi
ciones establecidas para estos efectos.
