XII. VÍAS PROCIDIMENTáLES
El CPCD leda la posibilidad al usuario, en caso se le vulnere algún derecho, de acudirá dos vías:
1. Servicio de Atención al Ciudadano (SAC).- El usuario empleará el servicio de atención gra
tuita de reclamos, la atención es en varias formas: por vía telefónica, personalmente ante el
Indecopi, o mediante el Internet.
Efectivizado el reclamo ante el SAC y notificado el empresario proveedor del mismo, estos
pueden arribara una conciliación vinculante y definitiva de forma sencillay rápida.
2. Órgano Resolutivo de Procedimientos Sumarísimos (ORPS) de la Oficina de Protección
al Consumidor. - El Órgano Resolutivo de Procedimientos Sumarísimos adm itirá la denuncia
si está relacionada a un caso no muy complejo y que el valor del producto o servicio adquirido
u ofertado no supere 3 UIT.
Adm itida a trám ite la denuncia, emplazará al denunciado para que conteste, luego el jefe del
Órgano Resolutivo de Procedimientos Sumarísimos citará a audienciay posteriormente em iti
rá resolución final. Todo este trám ite durará 30 días hábiles, con plazo improrrogable.
En caso que los involucrados estén disconformes con lo resuelto por el Órgano Resolutivo de
Procedimientos Sumarísimos, interpondrán apelación,y el expediente administrativo será re
m itido ante la Comisión de Protección al Consumidor, y de ser el caso, en vía de revisión, se
resolverá ante la Sala competente en materia de Protección al Consumidor del Tribunal del
Indecopi. En ambas instancias, el plazo también es perentorio de 30 días hábiles, tiempo que
con la legislación anterior no se daba, lo cual es un avance en el tema.
