I. MARCO NORMATIVO
La norma III del TUO del Código Tributario señala que son fuentes del Derecho Tributario:
a) Las disposiciones constitucionales.
b) Los tratados internacionales aprobados por el Congreso y ratificados por el Presidente de
la República.
c) Las leyes tributarias y las normas de rango equivalente.
d) Las leyes orgánicas o especiales que norman la creación de tributos regionales o munici
pales.
e) Los decretos supremos y las normas reglamentarias.
f) Lajurisprudencia.
g) Las resoluciones de carácter general emitidas por la Administración Tributaria.
h) La doctrina jurídica.
Agrupándolas podemos darnos cuenta que hay tres grupos de fuente: El derecho positivo o la
ley en sentido amplio, lajurisprudenciay la doctrina jurídica.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
