-- 1281 of 1506 --

Temas de Tributario
El grupo conformado por el derecho positivo es fuente principal y obligatoria, dejando como
fuente secundaria a la jurisprudencia. Sin embargo, la jurisprudencia del Tribunal Fiscal ad
quiere un importante papel, en tanto se convierta en precedente de observancia obligatoria,
que deberá ser acata por todos los órganos administradores. En este grupo también debe in
cluirse a la jurisprudencia del Poder] udicial y del Tribunal Constitucional.
En cuanto a la doctrina jurídica tributaria, si bien no es fuente obligatoria, pero sirve de orien
tación para una mejor comprensión y de ayuda a los operadores del derecho tributario.
II. PRINCIPIOS TRIBUTARIOS
Si bien es cierto que la Constitución le reconoce potestad tributaria al Estado, también recono
ce que ésta debe ser ejercida dentro de límites a fin de que no se incurra en abusos. Los límites
a esta facultad son los PRINCIPIOS CONSTITUCIONALES que se encuentran enunciados en
el artículo 74 de nuestra Constitución de 1993. Mediante STC Exp. N° 042-2004-AI/TC (Caso
Alejandro Lobatón) el Tribunal Constitucional ha definido dichos principios.
Principio de legalidad: Se entiende como la subordinación de todos los poderes públicos a
leyes generales y abstractas que disciplinan su forma de ejercicio y cuya observancia se halla
sometida a un control de legitimidad por jueces independientes.
En el ámbito constitucional tributario, el principio de legalidad no quiere decirque el ejercicio
de la potestad tributaria por parte del Estado está sometida sólo a las leyes de la materia, sino,
antes bien, que la potestad tributaria se realiza principalmente de acuerdo con lo establecido
en la Constitución. Por ello no puede haber tributo sin un mandato constitucional que así lo
ordene526. La potestad tributaria, por tanto, está sometida, en primer lugar, a la Constitución
(principio de constitucionalidad) y, en segundo lugar, a la ley.
Principio de reserva de ley: este principio implica una determinación constitucional que im
pone la regulación, sólo por ley, de ciertas materias. A criterio del Tribunal Constitucional NO
existe identidad entre el principio de legalidad y el de reserva de ley. El principio de reserva
de ley significa que el ámbito de la creación, modificación, derogación, o exoneración-entre
otros- de tributos queda reservada para ser actuada únicamente mediante una ley.
Mientras el Principio de Legalidad supone una subordinación del Ejecutivo al Legislativo, la
Reserva no sólo es eso sino que el Ejecutivo no puede entrar, a través de sus disposiciones ge
nerales, en lo materialmente reservado por la Constitución al Legislativo. De ahí que se afirme
la necesidad de la Reserva,ya que su papel no se cubre con el principio de legalidad, en cuanto
es sólo límite, mientras que la Reserva implica exigencia reguladora.
