-- 1282 of 1506 --

UBILEX
Principio de igualdad: Igualdad ante la ley. No se puede otorgar privilegios personales en ma
teria tributaria. La administración tributaria no puede tratar a unos de una manera y a otros
de otra manera. Todos deben ser tratados por igual ante la administración. Consiste en que la
norma tributaria debe aplicarse a todos los que cumplan con la hipótesis de incidencia espe
cificada en la norma; es decir, los que realizan el hecho generador.
Principio de no confiscatoriedad: Este principio informa y lim ita el ejercicio de la potestad
tributaria estatal y, como tal, constituye un mecanismo de defensa de ciertos derechos cons
titucionales, empezando, desde luego, por el derecho de propiedad, ya que evita que la ley
tributaria pueda afectar irrazonable y desproporcionadamente la esfera patrimonial de las
personas. Se transgrede este principio cada vez que un tributo excede el límite que razonable
mente puede admitirse como justificado en un régimen en el que se ha garantizado consti
tucionalmente el derecho subjetivo a la propiedad y se ha considerado a la propiedad, como
institución, como uno de los componentes básicos y esenciales de nuestro modelo de Consti
tución económica.
Principio de capacidad contributiva: conocida también como capacidad económica de la
obligación, consiste como dice Francisco Ruíz de Castilla “es la aptitud económica que tiene
las personas y empresas para asumir cargas tributarias527”, tomando en cuenta la riqueza que
dicho sujeto ostenta. Impone también respetar niveles económicos mínimos, calificar como
hipótesis de incidencia circunstancias adecuadas y cuantificar las obligaciones tributarias sin
exceder la capacidad de pago.
Si bien no existe en el texto de la Constitución Política del Perú, un reconocimiento expreso
al principio de capacidad contributiva, el Tribunal Constitucional ha reconocido su carácter
implícito indicando que el mismo se alimenta o fluye del principio de igualdad (STC N°0033''
2004-AT/TC). En anteriores sentencias, el Tribunal se ha referido al principio de capacidad con
tributiva de forma indirecta, en el sentido de que la capacidad contributiva guarda un nexo
indisoluble con el hecho sometido a imposición, consideración a partir de la cual el principio
adopta un contenido concreto y se aleja de la posibilidad de ser relativizado por el legislador
hasta desaparecer al momento de la generación del tributo (STC N°i907-2003-AA/TC) distin
guiéndola de la capacidad económica (STC N° 0033--2004-AI/TC), siendo aplicable a los im
puestos y en alguna medida a las tasas y contribuciones (STC N°00053-2004-AI/TC).
Concepto: Es toda prestación obligatoria, en dinero o en especie, que el Estado exige, median
te ley, en ejercicio de su poder de imperio.
La característica principal del tributo es su obligatoriedad, se prescinde de la voluntad del obli
gado en lo que respecta a la génesis de la obligación tributaria.
