Para Geraldo Ataliba es la obligación jurídica pecuniaria exlege que no constituye sanción por
acto ilícito, cuyo sujeto activo es en principio una persona públicay cuyo sujeto pasivo es una
persona que ha sido puesta en dicha situación por la ley528.
Según Héctor Villegas, la norma tributaria es una regla hipotética cuyo mandato se concreta
cuando se configura el hecho imponible (circunstancia fáctica condicionante prevista en ella
como presupuesto de la obligación). Es la prestación comúnmente en dinero que el Estado
exige de los particulares en base a su poder de im perioy atendiendo a la capacidad contribu
tiva de éstos en virtud de una leyy para cubrir los gastos que demandan la satisfacción de las
necesidades públicos.
Clasificación: El TUO del Código Tributario, aprobado por D.S. 133-2013-EF, publicado el 22 de
junio de 2013, en la norma II del Título Preliminar, hace la siguiente división de los tributos;
Impuesto: Es el tributo cuyo cumplimiento no origina una contraprestación directa a favor del
contribuyente por parte del Estado.
Contribución: Es el tributo cuya obligación tiene como hecho generador beneficios derivados
de la realización de obras públicas o de actividades estatales.
Tasa: Es el tributo cuya obligación tiene como hecho generador la prestación efectiva por el
Estado de un servicio público individualizado en el contribuyente.
No se considera tasa al pago que se recibe por un servicio de origen contractual.
Las tasas pueden ser:
i. Arbitrios: Son tasas que se pagan por la prestación o mantenimiento de un servicio públi
co.
ii. Derechos-. Son tasas que se pagan por la prestación de un servicio administrativo público o
el uso o aprovechamiento de bienes públicos.
iii. Licencias: Son tasas que gravan la obtención de autorizaciones específicas para la realiza
ción de actividades de provecho particular sujetas a control o fiscalización.
IV. HECHO IMPONIBLE
Determina el nacimiento de la obligación tributaria, es la configuración en la realidad de la
hipótesis de incidencia, con todas las características que esta estableció, Geraldo Ataliba lo de
fine como “(...) un hecho concreto, localizado en tiempo y espacio, sucedido efectivamente en
el universo fenoménico que - por corresponder rigurosamente a la descripción previa, hipoté
ticamente formulada por la hipótesis de incidencia-da nacimiento a la obligación tributaria”.
El hecho imponible debe contemplar los siguientes aspectos:
Aspecto material: Consiste en la descripción objetiva del hecho o situación previstos en
forma abstracta por las normas jurídicas que genera la obligación tributaria.
