A s p e c to personal o s u b je tiv o : Es la determinación de la persona o personas a cuyo res
pecto se configura el aspecto material; es decir, se establece quien es el acreedory el deu
dor de la obligación tributaria.
Aspecto espacial.* Es la determinación del lugar donde se tiene que configurar el hecho
imponible de tal forma que se considere que se ha generado la obligación tributaria,
como por ejemplo, que el hecho imponible se configure dentro del territorio nacional.
Aspecto temporal: Indica el momento en que se configura, o en que la norma tiene por
configurada, la descripción objetiva, por lo general es durante la vigencia de la norma.
El hecho imponible puede ser:
a. De realización inm ediata: donde el devengo del tributo se produce en el instante de reali
zación del hecho gravado, como por ejemplo; el impuesto de alcabala, el impuesto a los
espectáculos y otros.
b. De realización periódica: la obligación tributaria surge cada cierto tiempo, de tal forma que
el devengo ocurre en la oportunidad o fecha prefijada en la ley a este fin, este momento
coincide por lo general con el inicioy el fin del periodo al que corresponde el tributo. Por
ejemplo: el impuesto a la renta anual, el impuesto predial y el impuesto a la propiedad
vehicular.
