VI. EXIGIBILIDAD DE LA OBLIGACIÓN TRIBUTARIA
La obligación tributaria es exigí ble:
1. Si debe ser determinado por el deudor tributario: desde el día siguiente al vencimiento
del plazo fijado por Ley o reglamento y a falta de este plazo, a partir del décimo sexto día
del mes siguiente al nacimiento de la obligación.
Tratándose de tributos administrados por la Superintendencia Nacional de adm inistra
ción tributaria (SUNAT): desde el día siguiente al vencimiento de los plazos fijados por
el Art. 29 del T.U.O. del Código Tributario, según el tributo sea de liquidación mensual,
anual, cuyos hechos imponibles sean de realización inmediata, o anticipos a cuenta.
2. Cuando la obligación deba ser determinada por la administración tributaria, será exigible
desde el día siguiente al vencimiento del plazo para el pago que figure en la resolución
que contenga la determinación de la deuda tributaria, en falta de este plazo será exigible
al décimo sexto día siguiente al de su notificación.
La exigibilidad de la obligación tributaria no coincide con la exigibilidad de la deuda tri
butaria, en vista que la obligación, como hemos visto, se genera con el cumplim iento del
plazo señalado por ley, mientras que la exigibilidad de la deuda tributaria depende de
ciertos requerimientos de pago, así como el hecho que el obligado no haya reclamado la
determinación de la deuda tributaria o ésta no se encuentre en un proceso de reclama
ción o apelación.
V il. EXTINCIÓN DE LA OBLIGACIÓN TRIBUTARIA
El Art. 27 del TUO del Código Tributario señala que son medios extintivos de la obligación
tributaria:
i. El pago: Puede ser efectuado por los deudores directos, deudores responsables (son deu
dores solidarios, ya sea en calidad de representantes, sucesores a título universal, suceso
res a título gratuito y agentes de retención o percepción), terceros extraños a la realiza
ción del hecho imponible. El pago solo puede ser exigido al deudortributario a pesar que
parte de la deuda fuese cubierta por un tercero.
En cuanto a la forma de pago; éste se realizará en la forma, lugary plazos que señale
la ley o en su defecto el reglamento, a falta de éstos de acuerdo lo dispuesto en las
Resoluciones de la Administración Tributaria. Se prevé que los cronogramas de pago
se aplicarán no sólo para tributos administrados por la SUNAT, sino también para
aquellos cuya recaudación les sea encargado (SENCICO, aportaciones a ESSALUDy
ONP). Nota: A p a rtir de julio de 1999, la SUNAT se encarga de la recaudación de las aporta
ciones a ESSALUDy ONP.
