La compensación requiere ser declarada por el órgano administrador del tributo para
sufrir efectos cancelatorios, tal declaración puede tener lugar de oficio o a solicitud del
deudor.
Las obligaciones se compensan por lo menos hasta el límite de la menor de ellas, subsis
tiendo la mayor por el saldo restante.
i í l La condonación: El TUOdel Código Tributario contempla la figura de lacondonación pre
cisando que únicamente opera por norma expresa con rango de ley. Excepcionalmente,
los Gobiernos Locales podrán condonar, con carácter general, el interés moratorio y las
