iv. La Consolidación: Es el medio porel cual se da término a la obligación tributariayse con
figura cuando se transfiere al Estado bienes sujetos a tributo, caso en el cual se consolida
en el fisco la calidad de acreedor y deudor. En este supuesto el sujeto activo no puede ser
deudor de sí mismo y la obligación se extingue.
v. Por Resolución de la Administración Tributaria: La obligación tributaria se extingue por
Resolución de la Administración Tributaria sobre deudas de cobranza dudosa o de recu
peración onerosa que conste en las respectivas Resoluciones de Determinación, Resolu
ciones de Multa u Órdenes de Pago.
VIII. RESOLUCION DE DETERMINACION
Es el documento que emplea la Administración para hacer de conocimiento del deudor la
existencia de una deuda tributaria a su cargo o de un saldo a su favor, como resultado de un
proceso de fiscalización.
Según el art. 76 del TUO del Código Tributario la resolución de determinación es el acto porel
cual la Administración Tributaria pone en conocimiento del deudor tributario el resultado de
su labor destinada a controlar el cumplimiento de las obligaciones tributarias, y establece la
existencia del crédito o de la deuda tributaria.
La emisión de una resolución de determinación implica un procedimiento de fiscalización o
verificación previo.
De acuerdo con el art. 115 del TUO del Código Tributario, para que una resolución de determ i
nación sea exigióle coactivamente deber ser notificada al contribuyente y no reclamada por
éste dentro del plazo de ley.
IX. ORDEN DE PAGO:
Según el art. 78 del TUO del Código Tributario, la orden de pago es al acto en virtud del cual la
Administración exige al deudortributario la cancelación de la deuda tributaria, sin necesidad
de emitirse previamente la Resolución de Determinación en los casos siguientes:
1. Portributos autoliquidados porel deudortributario.
2. Por anticipos o pagos a cuenta, exigidos de acuerdo a ley.
