UBILEX
X!. INFRACCIONES TRIBUTARIAS
Es toda acción u omisión que importe violación de normas tributarias, que establezcan obliga
ciones formales, constituye infracción sancionablede acuerdo con lo establecido por el código
tributario.
Con frecuencia se confunde a la infracción tributaria con el delito tributario, llegar a estable
cer la distinción es vital, pues todo aquello que sea esencialmente delito, deberá regirse por
los principios generales del Derecho Penal común y juzgarse por la justicia penal ordinaria, a
diferencia de las infracciones tributarias, las cuales deberán regirse por principios y órganos
jurisdiccionales propios.
La diferencia entre Infracción Tributariay Delito Tributario consiste en que para la primera se
requiere el incumplimiento de la norma tributaria, cualquiera sea la intención del agente; en
cambio el delito tributario exige intención dolosa de su autor.
Además, en la infracción tributaria la responsabilidad es objetiva, no interesa si hubo inten
ción o no, sólo se exige el resultado. En cambio, en el delito tributario la responsabilidad es
subjetiva, se investiga la intención dolosa en la comisión.
El delito tributario está regulado en el Código Penal y en la Ley Penal T rib u ta ria - Decreto Le
gislativo N° 813; y las infracciones tributarias se regulan en el Código T ributario-Libro Cuarto.
El artículo 164 del mismo TUO del Código señala que “Es infracción tributaria, toda acción u om i
sión que importe la violación de normas tributarias, siempre que se encuentre tipificada como tal en el
presente Título (infracciones y Sanciones Adm inistrativas) o en otras leyes o decretos legislativos”.
Es infracción tributaria, por ejemplo, “No inscribirse en los registros de la Administración Tri
butaria” tipificado como tal en el numeral 1 del artículo 173 del TUO Código y es delito la de
fraudación tributaria bajo las modalidades “Ocultar, total o parcialmente, bienes, ingresos o
rentas, o consignar pasivos, total o parcialmente falsos, para anular o reducir el tributo a pa
gar”, tipificado en el literal A del artículo z del Decreto Legislativo N° 813.
Las infracciones tributarias se originan por el incumplimiento de las obligaciones siguientes.
De inscribirse, actualizar o acreditar la inscripción.
De emitir, otorgary exigir comprobantes de pagoy/u otros documentos.
De llevar libros y/o registros o contar con informes u otros documentos.
De presentar declaraciones y comunicaciones.
De permitir el control de la Administración Tributaria, informary comparecer ante la misma.
Otras obligaciones tributarias.
Al respecto el Tribunal Fiscal establece:
"El artículo 165 del Código Tributario establece que las infracciones se determinan en forma objetiva
y en el caso de la mencionada Infracción se sanciona el incumplimiento de una obligación
formal, que corresponde a la presentación de las declaraciones tributarias, consignando en
ellas datos reales y correctos, la que se configura en forma independiente al cumplimiento de
la obligación tributaria sustantiva, por lo que de acuerdo con el criterio recogido en las Resolu
ciones N° 12434-4-2007 y 11209-4- 2012, entreoirás, la ausencia de dolo no exime ai infractor de
la aplicación de la sanción". Resolución N° 03829-9-2024 de! Tribunal Fiscal. (El resaltado es nuestro)
Jurisprudencia de observancia obligatoria.
