XI!. SANCIONES ADMINISTRATIVAS
La infracción será determinada en forma objetiva y sancionada administrativamente con pe
nas pecuniarias, comiso de bienes, internamiento temporal de vehículos, cierre temporal de
establecimiento u oficina de profesionales independientes y suspensión de licencias, permi
sos, concesiones o autorizaciones vigentes otorgadas por entidades del Estado para el desem
peño de actividades o servicios públicos.
En el control del cumplim iento de obligaciones tributarias administradas por la Superinten
dencia Nacional de Administración Tributaria - SUNAT, se presume la veracidad de los actos
comprobados por los agentes fiscalizadores, de acuerdo a lo que se establezca mediante De
creto Supremo.
En un caso hipotético, en la fecha i, el Código Tributario establece que el incumplimiento tar
dío de una declaración jurada conlleva una multa de 3000. En la fecha 2, un contribuyente
presenta tardíamente su declaración de ICV. Posteriormente, en la fecha 3, una ley modifica el
Código Tributario, reduciendo la multa por incumplimiento tardío a 1000. Finalmente, en la
fecha4, el contribuyente paga la multa.
Existen dos posibles alternativas:
1. Si el nuevo texto del Código Tributario dispone expresamente que las normas que redu
cen sanciones se aplican retroactivamente, entonces la nueva norma que establece una
multa de 1000 modificaría la consecuencia que ya había ocurrido en la fecha 2: el naci
miento de la obligación de pagar una multa de 3000. En este caso, el contribuyente paga
ría una m ulta de 1000.
2. Si el nuevo texto del Código Tributario no establece expresamente la aplicación retroacti
va de las normas que reducen sanciones, surge la interrogante sobre si es posible aplicar
retroactivamente este tipo de normas. Según el numeral 5 del artículo 230 de la Ley del
Procedimiento Administrativo General, que permite la aplicación retroactiva de normas
que reducen sanciones administrativas, sería válido aplicar retroactivamente la nueva
norma que reduce la multa a 1000. Por lo tanto, en la fecha 4, el contribuyente estaría
obligado a pagar una multa de 1000.
Este tema se complica debido a que, antes de la Ley del Procedimiento Administrativo Gene
ral, el Tribunal Fiscal había establecido, mediante jurisprudencia de observancia obligatoria,
que no era posible aplicar retroactivamente las normas que suprimen o reducen sanciones por
infracciones tributarias.
Además, existe la figura de la ultractividad, que implica que una norma derogada puede se
guir produciendo efectos para ciertos hechos posteriores a su derogación.
Respecto del caso hipotético planteado el Tribunal Fiscal se ha pronunciado recientemente,
estableciendo como jurisprudencia de observancia obligatoria, en un caso similar pero no
igual, indicando lo siguiente:
(í,) - "Por lo expuesto, haciendo una Interpretación del 103 de la Constitución y del artículo 168
del Código Tributario y, sobre la base de la teoría de los hechos cumplidos, se concluye que
no procede aplicar retroactivamente la modificación introducida al numeral 1 del artículo 178
del Código Tributario por el Decreto Legislativo N° 1311 a infracciones cometidas antes de su
entrada en vigencia". Acia de Sala Plena H° 2024-05 de! 18 de setiembre de 2 0 2 4 .
