11947'' 2022-Uma, que se refiere también a la aplicación del artículo 168 del Código Tributario
en el caso de la modificación al numeral 1 de su artículo 178 dispuesta por el Decreto Legisla
tivo N° 1311, se señala expresamente que: “La irretroactividad de la s n o r m a s s a m i o n a t o r i a s r e g u
la d o e n el mencionado a r t íc u lo , se v in c u la con la a p lic a c ió n del Decreto Legislativo N .°i3 n , publica
do el treinta de diciembre de dos mil dieciséis. S i bien el mencionado Decreto Legislativo modificó la
in f r a c c ió n prevista en el n u m e r a l 1 ) del artículo 178 del TUO del Código Tributario, corresponde a la
Administración Tributaria q u e al ejercer la potestad s a n c io n a d o r a , sancione al contribuyente con la
norma vigente, por principio de aplicación inmediata de la n o r m a , no pudiendo a p lic a r s e el Decreto
