DERECHO AM3UEHTAL
S. CONCEPTO
Según Leo Fíeld"El Derecho Ambiental es la rama del derecho público interno o internacio
nal, cuyas normas tienen como objetivo el de proteger la salud y calidad de vida individual
y colectiva del hombre, preservando bienes naturales y regulando las actividades humanas
susceptibles de contaminar su entorno o de causar desequilibrios ecológicos".
529 Acta de Sala Plena N° 2024-05 del 18 de setiembre de 2024. Cons.2.
292 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1293 of 1506 --

Temas de Am biental
El derecho ambiental ha evolucionado significativamente en la era moderna, aunque sigue
siendo una disciplina relativamente joven. Fue en la segunda mitad del sigloxx:cuando se
consolidó el consenso internacional para frenar los efectos negativos del hombre sobre el am
biente. Sin embargo, gran parte del contenido del derecho ambiental sigue en desarrollo de
bido a la constante adaptación a nuevos conocimientos científicos y tecnologías, lo que puede
hacer que las normas ambientales se vuelvan obsoletas rápidamente.
El derecho ambiental se enfoca en regular el ambiente, que se define como el lugar donde el
hombrey los seres vivos se desenvuelven. Los componentes del ambiente se clasifican en tres
categorías: el ambiente natural, el ambiente construido por el hombre y el ambiente social.
Sin embargo, el ambiente no se puede entender como la suma de estos componentes, sino
como el sistema que los integra o interconecta.
La noción del derecho ambiental ha experimentado cambios significativos a lo largo del tie m
po. Se pueden identificar tres etapas claras: la primera, en la que se buscaba proteger la natu
raleza indirectamente; la segunda, en la que se reconoce al ambiente como un bien jurídico
que debe ser protegido; y la etapa de sostenibilidad, que se centra en el desarrollo sostenible.
Existen varias definiciones del derecho ambiental, pero en general se puede decir que es el
subsistema jurídico que regula las actividades humanas que afectan el ambiente con el obje
tivo de m inimizar su influencia negativa y fomentar actividades respetuosas del ambiente. El
derecho ambiental también busca orientar las conductas individualesy sociales para prevenir
daños ambientales y regular las normas para restringir, perm itir o regular conductas relacio
nadas con el ambiente y los recursos naturales.
II. CONVENIOS
Convenio sobre Diversidad Biológica. Firmado en Río de Janeiro en 1992 y ratificado por el
Perú, en 1993, establece los compromisos mundialesy nacionales referentes a la identificación
y monitoreo de la biodiversidad; la conservación in situ (áreas protegidas, introducción de es
pecies foráneas, mantención y protección de los conocimientos de las poblaciones locales) y
ex situ (colecciones biológicas y bancos genéticos); el uso sostenible de los componentes de
la biodiversidad; la investigación, capacitación, educación y conciencia públicas; el control y
minimización de impactos negativos; el acceso a los recursos genéticos y a la tecnología; el
intercambio de información y cooperación entre los países desarrollados y en desarrollo para
la conservación y uso sostenible de la biodiversidad.
Convención Marco de las Naciones Unidas sobre Cambio Climático. Fue adoptada en N ueva
York el 9 de mayo de 1992 y entró en vigor el 21 de marzo de 1994. Permite, entre otras cosas,
reforzar la conciencia pública, a escala mundial, de los problemas relacionados con el cambio
climático. En 1997, los gobiernos acordaron incorporar una adición al tratado, conocida con
el nombre de Protocolo de Kyoto, que cuenta con medidas más enérgicas (y jurídicamente
vinculantes). En 2006 se enmendó en Nairobi este Protocolo a la Convención Marco de Na
ciones Unidas sobre Cambio Climático y se tenía previsto adoptar un nuevo protocolo en el
año 2009 en Copenhague, lo cual se tendrá que retrasar a México en el 2010.
