CONSTITUCIÓN POLÍTICA DE 1993 (NORMA FUNDAMENTAL)
El artículo 2 inc. 22 de la Constitución Política del Estado, contempla como derecho fundamen
tal, el derecho a gozar de un ambiente equilibrado y adecuado al desarrollo de la vida, el cual
se complementa con el artículo 67 de la citada Carta Fundamental, en el sentido, que el Estado
determina la política nacional del ambiente, en base a ello el Consejo Nacional del Ambiente
y el Fondo Nacional del Ambiente, eran las entidades encargadas de ejercer las funciones del
recién creado mediante Decreto Legislativo 1013, Ministerio del Ambiente, que tendrá como
función general diseñar, establecer, ejecutar y supervisar la política nacional y sectorial am
biental, asumiendo la rectoría con respecto a ella. Asimismo, los artículos 6 6 y 69 han previsto
un capítulo denominado, del Ambiente y los Recursos Naturales, promueven el uso racional
de los Recursos Naturales y el reconocimiento de conservar la diversidad biológica, además,
la obligación del Estado de promover el desarrollo de la Amazonia mediante una legislación
adecuada,ya que es considerada como uno de los pocos pulmones del mundo.
