Como es de verse nuestro Tribunal Constitucional ha desarrollado una doctrina jurispruden
cial sobre el contenido del derecho un medio ambiente equilibradoy adecuado, disgregándo
lo en dos elementos, orientado al goce y preservación del ambiente.
De igual forma, exalta la Responsabilidad del Estado en cuanto a la Política Nacional del am
biente para su preservación, lo que se vendría cumpliendo con la creación del Ministerio del
Ambiente. Aunque no debemos olvidar, que también existe una Responsabilidad de la so
ciedad, que es en lo que también ha insistido el Tribunal Constitucional, en el sentido que
aunado a las obligaciones del Estado, se requiere la participación de la ciudadanía, pues, el
ambiente no sólo constituye un sector de la realidad nacional, sino un todo integral de los
sectores y actividades humanas, así los problemas y cuestiones ambientales deben ser consi
derados y asumidos globalmente, (Fundamento 3/Exp. 0002-2003-CC/TC).
