LEYG EN ER A L DEL A M BIEN TE
Se menciona en primer lugar que sobre el derecho y deber ambiental de todo ciudadano con
relación a habitar en un medio ambiente adecuado, la conservación de la diversidad biológi
ca, el aprovechamiento sostenible de los recursos naturalesy el desarrollo sostenible del país.
Asimismo, conceptualiza como “ambiente” o a “sus componentes” a los elementos físicos, quí
micos y biológicos de origen natural o antropogénico que, en forma individual o asociada,
conforman el medio en el que se desarrolla la vida, siendo los factores que aseguran la salud
individual y colectiva de las personas y la conservación de los recursos naturales, la diversidad
biológicay el patrimonio cultural asociado a ellos, entre otros.
En relación al ordenamiento territorial ambiental, se sostiene que es sólo un instrumento que
forma parte de la política de ordenamiento territorial, más no se identifica como un elemento
más del concepto de ambiente.
En definitiva, se puede llegar a la conclusión que en la Ley General del Ambiente, se llega de
terminar de forma muy confusa y lata el concepto de medio ambiente, del cual no se puede
advertir que el referido concepto se sostiene en una posición estricta o amplia según lo seña
lado por la doctrina.
PRINCIPIOS DEL DERECHO AMBIENTAL
Los principios del derecho ambiental son concepciones generales que guían la toma de deci
siones y la aplicación de las normas ambientales. Debido a la juventud de esta disciplina y su
rápido crecimiento, los principios cumplen un papel fundamental en definir las bases de lo
que puede convertirse en normas vinculantes en el futuro.
Principio de Sostenibilidad, que se basa en el Informe Brundtland de las Naciones Uni
das. Según este informe, el desarrollo sostenible implica satisfacer las necesidades huma
nas del presente sin comprometer la capacidad de las generaciones futuras para atender
sus propias necesidades. El objetivo es que las actividades humanas sean responsables
y armoniosas con los fines sociales y económicos del país. De esta manera, el desarrollo
sostenible requiere una gestión del ambiente equilibrada entre los aspectossociales, am-
bientalesy económicos. Aunque la influencia ambiental es aún incipiente, el Principio de
Sostenibilidad es clave para garantizar un futuro prósperoy sostenible.
El Principio de Buena Vecindad y Cooperación Internacional, que establece la obliga
ción de prevenir, reduciry controlar la contaminación y el daño ambiental dentro de las
fronteras de cada Estado, así como la cooperación en la mitigación de riesgos y emergen
cias ambientales.
El Principio de Responsabilidades Comunes pero Diferenciadas, que reconoce que
los Estados deben cooperar en la conservación y restauración del ambiente teniendo en
cuenta su aporte histórico y capacidades técnicas y económicas.
El Principio de Prevención, que prioriza la prevención, vigilancia y evitación de la de
gradación ambiental,ya que la reparación del daño no siempre regresa el ambiente a su
situación inicial.
296 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1297 of 1506 --

Temas de Ambiental
El Principio Precaytorio, que establece que, en caso de peligro de daño grave o irrever
sible, no se debe postergar la adopción de medidas eficaces para impedir la degradación
del ambiente, aunque no haya certeza científica absoluta.
El Principio de Internalización de Costos, que obliga a cualquier persona o entidad a
asumir los costos de los riesgos o daños que genere sobre el ambiente.
El Principio de Responsabilidad Ambiental, que obliga al causante de la degradación
del ambiente a adoptar medidas para su restauración, rehabilitación o reparación.
El Principio de Gobernanza Ambiental, que se refiere al conjunto de reglas, prácticas
y entidades que enmarcan la gestión del ambiente y tiene como objetivo armonizar las
políticas, instituciones y normas para facilitar la participación efectiva de los actores pú
blicos y privados en la toma de decisionesy manejo de conflictos.
IV. DERECHOS DE LOS PUEBLOS INDÍGENAS
Derechos individuales de ios Pueblos Indígenas, son los derechos que protegen a las personas
indígenas en su condición de miembros de un pueblo.
Derechos colectivos de los Pueblos Indígenas, son derechos que protegen al conjunto de los
miembros de un pueblo Indígena en su condición de pueblo o entidad colectiva.
El derecho Internacional de los derechos humanos reconoce derechos a los pueblos indígenas,
lo que implica que estos son de cumplimiento obligatorio dentro del país y que el cuerpo de
normas que reconocen estos derechos ostenta rango constitucional. Nos referimos a la Cons
titución Política, a la jurisprudencia del TC en forma reiterada, a los tratados internacionalesy
de manera específica al Convenioi69 de laOIT,y a lajurisprudenciade laCorte Interamericana
de Derechos Humanos. Es decir, se les reconoce a este DIDH la mayor jerarquía en el sistema
de fuentes del derecho, lo cual significa que ninguna norma de rango legal o reglamentario
(infra legal) puede contradecirlo, bajo sanción de invalidez. La consecuencia es práctica, el
Congreso y el Gobierno tiene la facultad de configurar sus normas legales y tom ar decisio
nes de índole administrativa, sin embargo, no pueden afectar, amenazar y menos violar los
derechos fundamentales, entre los que se encuentra el Convenio 169 de la OIT. En definitiva,
los derechos fundamentales son criterios de validez material sustantiva. El problema es que
todas estas normas que tiene su origen fundamentalmente en el DIDH son desconocidas o,
en el mejor de los casos, subutilizadas.
Convenio 169 de la OIT:
Reconoce la capacidad de los pueblos indígenas para asumir el control de sus propias
instituciones, formas de viday su desarrollo económico.
Reconoce el derecho de los pueblos indígenas a la autodefinición, a mantenery fortalecer
su identidad, lenguasy religión.
Reconoce el derecho de los pueblos indígenas a la participación en el desarrollo de las
acciones dirigidas a proteger sus derechos y garantizar el respeto de su integridad.
Reconoce el derecho de los pueblos indígenas a ser consultados cada vez que se prevean medi
das susceptibles de afectarles directamente (Leyes, Reglamentos, Autorización de Contratos).
