Reconoce la relación especial que tienen los pueblos indígenas con las tierras o territorios
que ocupan o utilizan de alguna otra manera, y en particular los aspectos colectivos de
esa relación.
Reconoce el derecho de propiedady posesión sobre las tierras que tradicionalmente ocu
pan y a su protección frente a toda intrusión no autorizada.
El Convenio incluye derechos relativos a la contratación y condiciones de empleo, seguri
dad social y salud, educación.
Los pueblos indígenas deberán tener protección contra la violación desús derechos y po
der iniciar procedimientos legales, sea personalmente o bien por conducto desús organi
zaciones representativas, para asegurar el respeto efectivo de tales derechos.
Los Gobiernos deberán tomarse medidas para garantizar que los miembros de dichos
pueblos puedan comprendery hacerse comprender en procedimientos legales, facilitán
doles, si fuese necesario, intérpretes u otros medios eficaces.
Constitución de 1 9 9 3 :
Consagra el derecho de toda persona a la tutela jurisdiccional, al libre acceso a la justicia,
en otras palabras, toda personatiene derecho a recurrirante los órganos responsables de
administrar justicia en nombre del Estado buscando la tutela efectiva de sus derechos.
(Art. 139 inciso 3).
Todo peruano tiene derecho a usar su propio idioma ante cualquier autoridad mediante
un intérprete.
DL 22175:
Dispone, que los funcionarios y empleados públicos, quedan obligados bajo responsabilidad
civil y penal, a dar curso inmediato a las denuncias presentadas por comuneros nativos refe
rentes, entre otros aspectos, a la ocupación o explotación ilícita de recursos naturales pertene
cientes a la Comunidad, u otros hechos o acciones que le perjudique. (Art. 23).
V. DERECHO A LA CONSULTA PREVIA (LEY N° 2 9 7 8 5 )
Es el derecho de los pueblos indígenas u originarios a ser consultados de forma previa sobre
las medidas legislativas o administrativas que afecten directamente sus derechos colectivos,
sobre su existencia física, identidad cultural, calidad de vida o desarrollo. También correspon
de efectuar la consulta respecto a los planes, programas y proyectos de desarrollo nacional
y regional que afecten directamente estos derechos. La consulta a la que hace referencia la
presente Leyes implementada de forma obligatoria solo por el Estado.
La finalidad de la consulta es alcanzar un acuerdo o consentimiento entre el Estado y los pue
blos indígenas u originarios respecto a la medida legislativa o administrativa que les afecten
directamente, a través de un diálogo intercultural que garantice su inclusión en los procesos
de toma de decisión del Estado y la adopción de medidas respetuosas de sus derechos colec
tivos.
Principios:
Los principios rectores del derecho a la consulta son los siguientes:
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1299 of 1506 --

Temas de Competencia
a) Oportunidad, El proceso de consulta se realiza de forma previa a la medida legislativa o
administrativa a ser adoptada por las entidades estatales.
b) Interculturalidad. El proceso de consulta se desarrolla reconociendo, respetando y adap
tándose a las diferencias existentes entre las culturasy contribuyendo al reconocimiento
y valor de cada una de ellas.
c) Buena fe. Las entidades estatales analizany valoran la posición de los pueblos indígenas
u originarios durante el proceso de consulta, en un clima de confianza, colaboración y
respeto mutuo. El Estado y los representantes de las instituciones y organizaciones de los
pueblos indígenas u originarios tienen el deber de actuar de buena fe, estando prohibi
dos de todo prosel itismo partidario y conductas antidemocráticas.
d) Flexibilidad. La consulta debe desarrollarse mediante procedimientos apropiados al
tipo de medida legislativa o administrativa que se busca adoptar, así como tomando en
cuenta las circunstancias y características especiales de los pueblos indígenas u origina
rios involucrados.
e) Plazo razonable. El proceso de consulta se lleva a cabo considerando plazos razonables
que permitan a las instituciones u organizaciones representativas de los pueblos indí
genas u originarios conocer, reflexionary realizar propuestas concretas sobre la medida
legislativa o administrativa objeto de consulta.
f) Ausencia de coacción o condicionamiento. La participación de los pueblos indígenas u
originarios en el proceso de consulta debe ser realizada sin coacción o condicionamiento
alguno.
g) Información oportuna. Los pueblos indígenas u originarios tienen derecho a recibir por
parte de las entidades estatales toda la información que sea necesaria para que puedan
manifestar su punto de vista, debidamente informados, sobre la medida legislativa o ad
ministrativa a ser consultada. El Estado tiene la obligación de brindar esta información
desde el inicio del proceso de consultaycon la debida anticipación.
DERECHO DE LA COMPETENCIA
I. ÁMBITOS DE LA LIBRE COMPETENCIA
Como señala José Antonio Olaechea, el "Derecho de la Libre Competencia se encuentra inmer
so en el nuevo derecho del tráfico económico que incluye tres disciplinas, a saber:
Las normas sobre Competencia Desleal que tratan acerca de las pautas que deben seguir
los competidores entre sí.
Las normas de Defensa del Consumidor que protegen los intereses de los consumidores,
en oposición a aquellas que regulan a productores y comerciantes.
El derecho de la Libre Competencia que vela por el sistema de libre mercado en su con
junto”.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1300 of 1506 --

UBILEX
II. CONCEPTO DE U B R E COM PETENCIA
Hablamos de una libre competencia cuando las empresas y los usuarios de un determinado
mercado pueden satisfacer sus necesidades respectivas, trabajando bajo condiciones equita-
tivasy justas para cada uno de los participantes.
La libre competencia tiene como principal finalidad proteger la libertad del consum idory de
las empresas para que elaboren elecciones de acuerdo a sus necesidades.
La libre competencia se ve reflejada cuando en un mercado las entidades empresariales (ri
vales entre sí), buscan captar la atención de los consumidores sin afectar a los demás partici
pantes.
La competencia de las empresas se manifiesta en:
El tipo de bienes o servicios que ofrecen.
El precio de sus bienes o servicios.
Según lo señalado por INDECOPI, la competencia está basada en la libertad de decisión de
los que participan en el mercado, en un contexto en el que las reglas de juego son claras para
todos y se cumplen efectivamente. La libre competencia se basa fundamentalmente en la li
bertad de elección tanto para el consumidor, a quien no se debe privar de opciones para que
elija libremente lo que mejor se adecúe a sus necesidades, como para el productor, quien debe
tom ar libremente sus decisiones empresariales en función de lo que considere más apropiado
a sus intereses. La libertad de elección del consum idory la del productor son inseparables y
de ellas depende en gran medida que se logre una asignación eficiente de recursos en la eco
nomía, cuando se cumplen ciertas condiciones básicas que se plantearán más adelante. Es a
través de estos principios que el mecanismo del mercado asegura que los recursos productivos
(conocimiento, trabajo, capital, recursos naturales) se dirijan a aquellos usos más productivos,
entendiendo por ello aquellos bienes y servicios que los consumidores prefieren en mayor
medida.
La libre competencia genera incentivos para que las empresas obtengan una ventaja com
petitiva sobre otras mediante la reducción de costos y la superioridad técnica. Esto resulta
un aumento de la eficiencia de las empresas para producir, un incremento de la calidad del
producto que se ofrecey una disminución de los precios que permite que una mayor cantidad
de consumidores tenga acceso al mercado.
Para producir los resultados deseados, el fundamento de la libre elección de consumidores
y productores tiene que darse en simultáneo con otros principios básicos del buen funciona
miento de los mercados. Éstos son la libre información en los mercados, la definición precisa
sobre los derechos de cada quien respecto de los bienes y servicios que se transan en el merca
do, las garantías de ejecutabilidadde los pactos y el resarcimiento por daños que se ocasionen
a terceros.
III. ASPECTOS DE LA U B RE COM PETENCIA
Siguiendo con el tema de la Libre Competencia podemos mencionar cuáles son los beneficios.
Éstos están dados por la competencia de las empresas entre sí, buscando captaren el mercado
