Temas de Com petencia
las preferencias de los consumidores. Esta competencia hace que los mercados tiendan a un
punto de equilibrio donde el precio de la producción de los bienesy servicios está determinado
por las decisiones atomizadas e interdependientes de miles de proveedores y consumidores.
En un escenario competitivo la sociedad se beneficia en su conjunto, pues los consumidores
estarán pagando el menor precio posible, lo que los economistas llaman eficiencia asignativa,
y los proveedores estarán produciendo al menor costo posible, lo que se le llama eficiencia
productiva. Sin embargo, dentro de la teoría del bienestar hay dos requisitos que deben cum
plirse para el logro de estos beneficios, por un lado, que los agentes realicen sus intercambios
voluntarios, con agentes actuando racionalmente en sus elecciones, se producirán eficiencias
"paredañas”. Esto quiere decir, que cuando un intercambio es voluntario, nadie ve su situación
empeorada sino que la de todos mejora, ganando tanto el comprador como el vendedor. Por
otro lado, la intervención estatal debe ser la mínima posible.
¿Qué es lo que debe hacer el Estado?
Con respecto a la regulación y control de la Libre Competencia en el Perú, la Constitución Po
lítica de 1993 señala en su artículo 6i: “El Estado facilita y vigila la libre competencia, combate toda
práctica que la lim ite y el abuso de posiciones dominantes o monopólicas. Ninguna ley ni concertación
puede autorizar ni establecer monopolios
Este artículo está reglamentado por el Decreto Supremo que aprueba el Texto Único Ordena
do de la Ley de Represión de Conductas A nticom petitivas-D . S. N °i i i -2024-PCM, norma que
fue publicada con fecha 12 de octubre de 2024, derogando el D.S. N° 030-2019-PCM, el cual
compendiaba las modificaciones al D.Leg. N°i034, dispuestas mediante el D. Leg. N°i205, De
creto Legislativo que modifica el D. Leg. N° 1034, que aprueba la Ley de Represión de Conduc
tas Anticompetitivas y el D. Leg. N ° i3 9 6 , Decreto Legislativo que modifica la Ley de Represión
de Conductas Anticompetitivas, aprobada por D. Leg. N°i034.
Mediante el D. Leg. N ° i0 3 3 , se aprueba la ley de organización y funciones del Instituto Nacio
nal de Defensa de la Competencia y de la Propiedad Intelectual (INDECOPI) como la entidad
encargada de supervigilary promover el correcto funcionamiento de la economía de mercado
en el Perú.
Entre las principales funciones del INDECOPI figuran im pulsary difundir la libre competen
cia, promover la participación adecuada de los agentes económicos en el mercado, fomentar
una competencia justa, leal y honesta entre los proveedores de bienes y servicios, velar por el
respecto de la libre competencia en el comercio internacional, reducir los costos de acceso y
salida al mercado (hoy reestructuración patrimonial, etc.).
Los Órganos del INDECOPI involucrados en la libre competencia son:
La Comisión de Defensa de la Libre Competencia, órgano colegiado que cuenta con una Se
cretaría Técnica que es el soporte administrativo de la Comisión y su órgano de instrucción
(Primera instancia administrativa).
La Sala de Defensa de la Competencia del Tribunal de Defensa de la Competencia y de la
Protección de la Propiedad Intelectual del Indecopi, los pronunciamientos de la Sala ponen
fin a la vía administrativa, por lo que el administrado que se encuentre disconforme con los
