!¥. ACTOS CONTRARIOS A LA COMPETENCIA: PRÁCTICAS MONOPÓUCAS, ABUSO DE
POSICIÓN DE DOMINIO EN EL MERCADO
El artículo 24o del D. Legislativo N ° i0 3 3 - Ley de Organización y Funciones de INDECOPI es
tablece que la Comisión de Libre Competencia es la encargada de velar por el cumplim iento
del Decreto Legislativo 1034, norma que aprueba la Ley de Represión de Conductas Anticom -
petitivasy de la Ley N °3ni2, que establece el Control Previo de Operaciones de Concentración
empresarial.
El Decreto Supremo que aprueba el Texto Único Ordenado de la Ley de Represión de Con
ductas Anticompetitivas, D. S. N° 111-2024-PCM prohíbe y sanciona el a b u s o d e la p o sició n
d e d o m in io y la s p rá c tic a s c o lu s o ria s h o r iz o n ta le s y v e rtic a le s con el objetivo de fortalecer
sustancialmente el marco regulatorio de defensa de la libre competencia, lo que, a su vez,
incentivará la eficiencia económica en los mercados, promoverá la competitividad económica
del país y mejorará el bienestar de los consumidores, estableciendo un ambiente apropiado
para las inversiones.
Prácticas monopólicas: Se define al monopolio "como aquella forma de mercado en la cual
un solo vendedor (o un grupo de vendedores de común acuerdo) controla(n) la oferta de un
producto o servicio concreto, lo cual le(s) permite determinar la cantidad ofrecida del mismo
y, por consiguiente, su precio".
Así, en un mercado monopolizado, una empresa puede restringir o fijar su oferta, por lo que
al no poder conseguir el producto de parte de otro proveedor, los consumidores tienen que
pagar más, es decir, bajo un mercado monopolizado el precio que tiene que pagar un consu
midor es más alto que en una situación competitiva, o bien el precio es igual y la calidad es
peor. Por el contrario, si el mercado es competitivo existen muchas empresas en la industria
produciendo bienes similares, lo que harían que dichas industrias no les suban el precio a sus
productos, ya que los consumidores cambiarían de proveedor; asimismo, tampoco se busca
que los proveedores bajen sus precios hasta un punto en que no tuvieran ganancias, sino por
el contrario, en un mercado competitivos se busca que tanto los productores como los consu
midores obtengan beneficios.
El D. S. N°m-2024-PCM, incluye este tema de la Libre Competencia en lo que expresamente
llama prácticas colusorias horizontales (Art. 11).
Abuso de posición de dominio en el mercado: Se dice que hay abuso de posición de dominio
en el mercado, cuando una o más empresas pueden actuar independientemente y de ma
nera indebida con prescindencia de sus competidores, compradores, clientes y proveedores,
debido a factores tales como la participación significativa de la empresa en los mercados res
pectivos, las características de la oferta y la demanda de los bienes y servicios, el desarrollo
tecnológico o servicio involucrados, el acceso de competidores a fuentes de fm anciam ientoy
suministros, así como redes de distribución, c o n -e l fm de obtener beneficios y causar perjui
cios a otros, que no hubieran sido posible si no hubiera tal posición de dominio.
