Temas de Com petencia
Según lo dispuesto por el art. 10.2 del D.S. N°t h -2 0 2 4 -PCM el abuso de la posición de dom inio
en el mercado podrá consistir en conductas de efecto exclusorio tales como:
a) Negarse injustificadamente a satisfacer demandas de compra o adquisición, o a aceptar
ofertas de venta o prestación, de bienes o servicios;
b) Aplicar, en las relaciones comerciales o de servicio, condiciones desiguales para prestacio
nes equivalentes que coloquen de manera injustificada a unos competidores en situación
desventajosa frente a otros. No constituye abuso de posición de dom inio el otorgamiento
de descuentos y bonificaciones que correspondan a prácticas comerciales generalmente
aceptadas, que se concedan u otorguen por determinadas circunstancias compensato
rias, tales como pago anticipado, monto, volumen u otras que se otorguen con carácter
general, en todos los casos en que existan iguales condiciones;
c) Subordinar la celebración de contratos a la aceptación de prestaciones adicionales que,
por su naturaleza o arreglo al uso comercial, no guarden relación con el objeto de tales
contratos;
d) Obstaculizar de manera injustificada a un competidor la entrada o permanencia en una
asociación u organización de intermediación;
e) Establecer, imponer o sugerir contratos de distribución o venta exclusiva, cláusulas de no
competencia o similares, que resulten injustificados;
f) Util izar de manera abusiva y reiterada procesos judiciales o procedimientos adm inistrati
vos, cuyo efecto sea restringir la competencia;
g) Incitar a terceros a no proveer bienes o prestar servicios, o a no aceptarlos; o,
h) En general, aquellas conductas que impidan o dificulten el acceso o permanencia de
competidores actuales o potenciales en el mercado por razones diferentes a una mayor
eficiencia económica.
No constituye abuso de posición de dominio el simple ejercicio de dicha posición sin afectara
competidores reales o potenciales.
V. CONDUCTAS RESTRICTIVAS DE LA LIBRE COMPETENCIA: PRACTICAS CONCERTA
DAS» FIJACIÓN DE PRECIOS, REPARTO DEL MERCADO
1. Practicas Concertadas: Se entiende por prácticas restrictivas de la libre competencia los
acuerdos, decisiones, recomendaciones, actuaciones paralelas o prácticas concertadas entre
empresas que produzcan o puedan producir el efecto de restringir, impedir o falsear la com
petencia.
Existen dos principales tipos de prácticas comerciales restrictivas.
Con frecuencia se las denomina prácticas “horizontales” o “verticales.”
• Restricciones horizontales: Tales acuerdos existen entre las empresas (suplidores o con
sumidores) al mismo nivel de la cadena de producción, esto es, que se dedican en gene
ral a las mismas actividades. Generalmente son conocidos como “colusión." La colusión
usualmente adopta la forma de un acuerdo de precios. Tales combinaciones proporcio
nan a las firmas que participan de ellos de un cierto grado de poder sobre la determ i
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1304 of 1506 --

UBILEX
nación de los precios, o en otras palabras, de establecer o cuando menos influenciar el
precio de un producto. La colusión también puede darse respecto de cuotas de mercado o
de producción, que es una forma indirecta de influenciar los precios. La colusión también
involucra acuerdos no relacionados con los precios, por ejemplo, los acuerdos para sumi
nistrarse recíprocamente el mercado o información técnica.
El art. 11 del D.S. N °i i i -2024-PCM, en este punto se refiere a prácticas colusorias horizon
tales como los acuerdos, decisiones, recomendaciones o prácticas concertadas realizadas
por agentes económicos competidores entre sí que tengan por objeto o efecto restringir,
impedir o falsear la libre competencia, tales como:
(a) La fijación concertada, de forma directa o indirecta, de precios o de otras condiciones
comerciales o de servicio;
(b) La limitación o control concertado de la producción, ventas, el desarrollo técnico o
las inversiones;
(c) El reparto concertado de clientes, proveedores o zonas geográficas;
(d) La concertación de la calidad de los productos, cuando no corresponda a normas téc
nicas nacionales o internacionales y afecte negativamente al consumidor;
(e) La aplicación concertada, en las relaciones comerciales o de servicio, de condiciones
desiguales para prestaciones equivalentes, que coloquen de manera injustificada a
unos competidores en situación desventajosa frente a otros;
(f) Concertar injustificadamente la subordinación de la celebración de contratos a la
aceptación de prestaciones adicionales que, por su naturaleza o arreglo al uso co
mercial, no guarden relación con el objeto de tales contratos;
(g) La negativa concertada e injustificada de satisfacer demandas de compra o adquisi
ción, o de aceptar ofertas de venta o prestación, de bienes o servicios;
(h) Obstaculizar de manera concertada e injustificada la entrada o permanencia de un
com petidora un mercado, asociación u organización de intermediación;
(i) Concertar injustificadamente una distribución o venta exclusiva;
(j) Concertar o coordinar ofertas, posturas o propuestas o abstenerse de éstas en las li
citaciones o concursos públicos o privados u otras formas de contratación o adqui
sición pública previstas en la legislación pertinente, así como en subastas públicas y
remates; u,
(k) Otras prácticas de efecto equivalente que busquen la obtención de beneficios por
razones diferentes a una mayor eficiencia económica.
