• Restricciones verticales: Igualmente, los acuerdos también pueden realizarse entre or
ganizaciones situadas a distintos niveles de los estadios de producción y distribución, tal
como suplidory detallista. Esto es conocido como “restricción vertical”. Cuando se trate de
una sola empresa (monopolista o dominante), estará en condiciones de utilizar su poder
en el mercado para imponer una serie de limitaciones a sus distribuidores (fases finales
de la cadena) o sus proveedores (fases iniciales de la cadena). Esta es la razón por la que
las prácticas comerciales restrictivas que sigue la empresa respecto de sus proveedores o
distribuidores se denominan “verticales”. Las prácticas restrictivas de competencia de tipo
vertical son aquellas ejercidas por una o más personas deform a unilateral o concertada,y
dirigidas contra empresas o personas que se encuentran en un nivel diferente del proceso
productivo. Los acuerdos verticales existen donde diferentes firmas en diferentes puntos
de la cadena de producción coluden entre sí, restringiendo la competencia. En la mayoría
de los casos, la colusión vertical ocurre entre suplidores y usuarios de insumos empresa
riales. Tal como en el caso de los acuerdos horizontales, este tipo de acuerdos se refieren
tanto a precios como a otras variables (tales como cuotas, acuerdos exclusivos, etc.).
2. Fijación de Precios: Los acuerdos entre competidores que involucran compras o ventas de
bienes o servicios son acuerdos de fijación de precios. Son ilegales sea que controlen el precio
en forma directa o indirecta.
Si el precio de acuerda, expresa o tácitamente, se tratará de un acuerdo directo de bienes de
fijación de precios (incluye acuerdos de precios fijos, flexibles, uniformes, así como acuerdos
para subir o bajar precios de compra o de venta) acorde a fórmulas de ajuste.
El control del mercado puede lograrse también en forma indirecta. Cualquier acuerdo que
tiene por efecto estabilizar precios o manipularlos a través de la conducta concertada es ilegal.
La fijación de precios puede ocurrir en forma indirecta, sin consentimiento expreso de las par
tes, inclusive sin que exista comunicación directa entre los conspiradores.
Se puede presentar una fijación de precios ilegal a través del proceso que se denomina señali
zación. Esto puede ocurrir en diferentes formas. Puede suceder a través de la publicidad de los
precios o el uso de la prensa.
En ausencia de una evidencia directa de conspiración la prueba de señalización ilegal es difícil
de establecer. En primer lugar, las empresas deben ser capaces de publicitar sus precios pues
los clientes tienen igualmente necesidad de conocer los futuros cambios. Los fabricantes y
vendedores tienen el derecho de participaren todo tipo de debate público.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1306 of 1506 --

UBILEX
3 . Reparto del Mercado: El reparto del mercado o fuentes de aprovisionamiento, se produce
cuando las empresas utilizan determinados recursos o insumo de una fuente proveedora, la
cual acaparan para no permitir a los demás poder usarlay hacerles más difícil el desempeño
de sus actividades comerciales y productivas.
Señala la Comisión Técnica de INDECOPI en la Resolución N° 011-93-INDECOPI/CLC (18.12.93)
como PRECEDENTE DE OBSERVANCIA OBLIGATORIA que “Los acuerdos de fijación de pre
cios y reparto de mercado serán per se ilegales cuando tengan como final idad y efectos únicos
y esenciales restringir la competencia, es decir cuando sean acuerdos desnudos o puros. Por
otro lado, aquellos acuerdos de fijación de precios y reparto de mercado que sean accesorios o
complementarios a una integración o asociación convenida y que hayan sido adoptados para
lograr una mayor eficiencia de la actividad productiva que se trate, deberán ser analizados
caso por caso a fin de determinar la racionalidad o no de los mismos. De ser considerados
irracionales corresponderá declara su ilegalidad.
Si, dependiendo del tipo de actividad productiva a analizarse, se determina que la integración
acordada entre las empresas es esencial para que dicha actividad se pueda llevar a cabo, en
tonces dicho acuerdo de integración así como las restricciones de la competencia que se gene
rarían para que dicha actividad se pueda llevar a cabo, entonces dicho acuerdo de integración
así como las restricciones de la competencia que se generarían para que dicha actividad sea
eficiente, estarán permitidos. Sin embargo, cuando la integración pueda ser beneficiosa pero
no sea considerada esencial para llevar a cabo determinada actividad productiva, el acuerdo
de integración y los acuerdos accesorios y complementarios que restrinjan la competencia es
tarán permitidos si reúnen tres características:
i. Los acuerdos de fijación de precios o de división de mercado se realizan como consecuen
cia de un contrato de integración, es decir que los miembros deben estar realizando una
determinada actividad económica en forma conjunta. Asimismo, dichos acuerdos deben
ser capaces de incrementar la eficiencia del grupo integrado y deben ser aplicados dentro
de los límites necesarios para lograr dicha eficiencia;
ii. Las cuotas de mercado correspondientes a cada integrante del acuerdo no llevan a determinar
que la restricción de la competencia derivada de la integración vaya a ocasionar un daño;
iii. Los integrantes de los acuerdos no deben tener como principal propósito o intención res
tringir la competencia.
De no presentarse lastres condiciones expuestas anteriormente, el acuerdo será considerado ilegal”.
VI. ASPECTOS DE COMPETENCIA DESLEAL
Según lo dispuesto en el artículo 6 del Decreto Legislativo N °1 0 4 4 , se considera acto de com
petencia desleal y, en consecuencia, ilícitoy prohibido, a aquél que resulte objetivamente con
trario a las exigencias de la buena fe empresarial que deben orientar la concurrencia en una
economía social de mercado.
Para Pinkas Flint; competencia desleal es toda conducta que resulte contraria a la buena fe
comercial, al normal desenvolvimiento de actividades económicas y en general a las normas
de corrección que deben regir las actividades económicas.
6 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1307 of 1506 --

Temas de Com petencia
Toda competencia desleal es ¡lícita pero no toda competencia ilícita es desleal porque puede
darse el caso que estemos frente a una competitividad ilícita pero que fue realizada con leal
tad, honestidady corrección sin transgredir las normas de concurrencia al mercado.
En cuanto a la regulación de la Competencia Desleal a nivel nacional, mediante el D. Leg. 1044
publicado el día 26 de junio de 2008, fue aprobada la Ley de Represión de la Competencia
Desleal quedando con ello derogadas entre otras la Ley 26122 (anterior ley de competencia
desleal) y el D. Leg 691 (Normas de publicidad en Defensa del consumidor).
El D. Leg. N °i044 es de aplicación a todas las personas naturales y jurídicas (inclusive las em
presas públicas y las que no tengan fines de lucro) teniendo por objeto reprimir todo acto o
conducta de competencia desleal que tenga por efecto, real o potencialmente afectar o impe
dir la competencia en el mercado. Al igual que su norma antecesora la presente ley establece
una cláusula general así como una lista enunciativa de actos particulares que podrían ser re
putados como de competencia desleal.
La norma en comentario del mismo modo establece las autoridades competentes para la fis
calización sobre el cumplimiento de los deberes instituidos en este dispositivo a los agentes
económicos, precisándose como primera instancia a la Comisión de fiscalización de la Com
petencia desleal y como segunda el Tribunal de Defensa de la Competencia del INDECOPI
estableciéndose para cada caso sus atribuciones y competencias.
A través de esta norma también se reglamenta el proceso administrativo sancionador aplica
ble para los casos de competencia desleal pudiendo este ser promovido a instancia de parte
(procedimiento tri late ral) o de oficio.
Como aspectos importantes a remarcar, se precisa en el artículo 51 que el plazo de prescrip
ción de la infracción será a los 5 años de ejecutado el últim o acto imputado como infractor.
Asimismo, se establece las sanciones a ser aplicables (multas), los criterios para determinar la
sanción, las medidas correctivas (cese del acto, comiso, destrucción de productos, cierre tem
poral o definitivo, otros).
La norma establece que las infracciones leves serán sancionadas con una multa de hasta 50
UIT, equivalentes a 257,500.00 mil soles, sin que supere el diez por ciento de los ingresos bru
tos percibidos por el Infractor relativo a todas sus actividades económicas, y lo mismo se esti
pula para las sanciones de hasta 700 UIT.
El Decreto Legislativo dispone que el Incumplimiento de una medida cautelar ordenada por
la Comisión implicará la Imposición automática de una multa no menor de diez (10) UIT ni
mayor a ciento veinticinco (125) UIT. Si se incumple una medida correctiva ordenada por la
Comisión en una resolución final se impondrá una multa equivalente al veinticinco por ciento
(25%) de la m ulta impuesta por la realización del acto de competencia desleal declarado.
La norma precisa que los perjudicados por actos de competencia desleal declarados por la
comisión, o por el tribunal, podrán demandar ante el Poder Judicial la pretensión civil de in
demnización por daños y perjuicios contra los responsables identificados porel Indecopi.
Derechos de los consumidores: Los actos de competencia desleal prohibidos por el Decreto Le
gislativo son sancionados independientemente de la afectación directa que pudieran produ
cir en perjuicio de los derechos de los consumidores. En tal sentido, si existen consumidores
