dispone que la Comisión de Propiedad Intelectual correspondiente será competente siempre
que la denuncia de parte sea presentada por el titu lar del derecho o por quien éste hubiera
facultado para ello.
Aplicación del Decreto Legislativo a los servicios financieros: El presente Decreto Legislativo no dero
ga la Ley Complementaria a la Ley de Protección al Consumidor en materia de servicios finan
cieros, aprobada mediante Ley N° 28587, ni sus normas reglamentarias ni modificatorias. En
tal sentido, las disposiciones del Decreto Legislativo que alcancen al sistema financiero sólo
serán aplicables en concordancia con la Ley N° 2 8 5 8 7 y disposiciones reglamentarias.
1. Ám bito de protección
De acuerdo a Pinkas Flint, el bien jurídico que pretende tutelar las normas de la “competencia
desleal” es la libre y leal competencia económica en el mercado, regulando esta competencia
en una forma amplia que involucra intereses diversos como son los de las competidores, los
consumidoresy el Estado como guardián del orden económico.
Citado por Pinkas Flint, Jorge Joeckel dice “la normatividad regulatoriade la competencia des
leal protege la transparencia de los medios que se emplean para competir”, en cambio el bien
jurídico tutelado “busca proteger la libertad de acceso y permanencia en el mercado". En otras
palabras, mientras la represión de las prácticas restrictivas se encarga que exista competencia
económica, la competencia desleal persigue que la competencia existente no se vea falseada
con el empleo por parte de los participantes en el mercado por procedimientos ilegítimos.
2. Actos de com petencia desleal
Según lo dispuesto en el artículo 6 del D. Leg. N°i044, un acto de competencia desleal es aquél
que resulte objetivamente contrario a las exigencias de la buena fe empresarial que deben
orientar la concurrencia en una economía social de mercado.
Están prohibidos y serán sancionados los actos de competencia desleal, cualquiera sea la for
ma que adopten y cualquiera sea el medio que permita su realización, incluida la actividad
publicitaria, sin importar el sector de la actividad económica en la que se manifiesten.
La determinación de la existencia de un acto de competencia desleal no requiere acreditar
conciencia o voluntad sobre su realización. Tampoco será necesario acreditar que dicho acto
