El tema de “Derecho de la Publicidad” ha alcanzado en los últimos años un desarrollo pro
gresivo, encontrándose orientado a lograr una tutela efectiva de los agentes económicos que
operan en el mercado peruano, situación que ha quedado corroborada a partir de la expedi
ción del Decreto Legislativo N° 691 -Normas de la Publicidad en Defensa del Consumidor-,
modificado a su vez, por el Decreto Legislativo N° 807, finalmente derogado por el Decreto
Legislativo N°1044.
I. CONCEPTO DE PUBLICIDAD
De manera genérica, puede entenderse por publicidad “toda comunicación insistente de un
mensaje dirigido al público, con el fin de influenciar en la conducta de éste para promover la
contratación de un producto, persona jurídica o servicio realizada a través de los medios de
comunicación”. En este sentido, podemos desagregar las siguientes características de la pu
blicidad:
a. Comunicación de un mensaje.
b. Influencia en la conducta del sujeto receptor del mensaje.
c. Comunicación insistente del mensaje.
d. La comunicación se realiza con fines comerciales.
e. Los objetos de las campañas publicitarias son productos, personas jurídicas y servicios.
f. Es una comunicación pagada.
Asimismo, podemos distinguir los siguientes tipos de publicidad:
a. Publicidad comercial.- es cualquier forma de comunicación pública que tenga por fin a li
dad o como efecto, fomentar, directa o indirectamente, la adquisición de bienes o la con
tratación de servicios, captando o desviando, las preferencias de los consumidores.
b. Publicidad institucional.- es aquella que tiene por finalidad, promover conductas de re
levancia social, tales como el ahorro de energía eléctrica, la preservación del medio am
biente, el pago de impuestos, entre otras.
