c. Propaganda política.- es aquella destinada a campañas de orden político, de candidatos
que postulan a cargos públicos.
En forma específica el D. Leg. N ° i0 4 4 , define la publicidad como “toda forma de comunicación
difundida a través de cualquier medio o soporte, y objetivamente apta o dirigida a promover
directa o indirectamente, la imagen, marcas, productos o servicios de una persona, empresa o
entidad en el ejercicio de su actividad comercial, industrial o profesional, en el marco de una
actividad de concurrencia, promoviendo la contratación o la realización de transacciones para
satisfacer sus intereses empresariales”.
Define también al anunciante como “toda persona, natural o jurídica, que desarrolla actos
cuyo efecto o finalidad directa o indirecta sea concurrir en el mercado y que, por medio de la
difusión de publicidad, se propone.- (i) ilustrar al público, entre otros, acerca de la naturaleza,
características, propiedades o atributos de los bienes o servicios cuya producción, intermedia
ción o prestación constituye el objeto de su actividad; o, (ii) motivar transacciones para satis
facer sus intereses empresariales.”
II. PRINCIPIOS PUBLICITARIOS
Los principios publicitarios son “directrices básicas que deben ser respetadas por todos los que
intervienen en el ejercicio de la actividad publicitaria”. Los principios admitidos por nuestra
actual legislación son los siguientes:
Principio de sustanciación previa en materia de publicidad: El artículo 8.4 del D. Leg. N°
1044 recoge el principio de sustanciación previa, según el cual los anunciantes deben contar
previamente con las pruebas que sustenten la veracidad de cualquier mensaje publicitario
referido a características comprobables de un bien o un servicio anunciado antes.de que dicho
mensaje sea difundido.
Principio de legalidad: Al igual que la norma anterior, el D. Leg. N° 1044 regula el principio
de legalidad, en virtud del cual se dispone que los anuncios publicitarios deben respetar las
normas imperativas del ordenamiento jurídico que se aplican a la actividad publicitaria. En
particular, el Decreto Legislativo establece que constituyen actos contra el principio de legali
dad, entre otros, los siguientes:
a. Omitir la presentación del precio total de un bien o servicio sin incluir los tributos aplicables
y todo cargo adicional indispensable para su adquisición, cuando el precio es anunciado.
b. O m itir en aquellos anuncios que ofrezcan directamente, presentando tasas de interés, la
realización de operaciones financieras pasivas o activas, la consignación de la tasa de in
terés efectiva anual api ¡cable y del monto y detalle de cualquier cargo adicional aplicable.
c. O m itir en aquellos anuncios que ofrezcan directamente productos con precios de venta
al crédito, la consignación del importe de la cuota inicial si es aplicable al caso, del monto
total de intereses, de la tasa de interés efectiva anual aplicable al producto anunciado y
del monto y detalle de cualquier cargo adicional aplicables.
d. Omitir, en cada uno de los anuncios que difundan publicidad de promociones de venta, la
indicación clara de su duración y la cantidad mínima de unidades disponibles de produc
tos ofrecidos.
