SI!. NORMAS SOBRE PUBLICIDAD
Mediante Decreto Legislativo N° 1044, publicado el 26.06.2008 en el Diario Oficial “El
Peruano”, se aprobó la nueva Ley de Represión de la Competencia Desleal. Este Decreto
Legislativo ha unificado en un solo texto normativo, tanto las disposiciones propias sobre
competencia desleal como tam bién las normas sobre publicidad comercial, a nteriorm en
te reguladas en el TUO del Decreto Ley N° 26122, Ley de Represión sobre la Competencia
Desleal y en el Texto Único Ordenado del Decreto Legislativo N° 691, Normas de la Publi
cidad en Defensa del Consumidor, respectivamente.
Dentro de los aspectos nuevos y principales introducidos por la norma vigente tenemos
los siguientes:
Uso de licencias publicitarias: el Decreto Legislativo señala que para los anuncios p u b li
citarios se encuentra perm itido el uso del humor, lafantasíay la exageración, siempre que
ello no im plique la comisión de actos de competencia desleal.
Libertad de expresión empresarial: El Decreto Legislativo establece que el desarrollo de
la actividad publicitaria perm ite el ejercicio de la libertad de expresión en la actividad em
presarial y es vehículo de la libre iniciativa privada que garantiza la Constitución Política
del Perú. No obstante, debe advertirse que ello no debe im plicar la realización de actos de
competencia desleal que afecten o lim iten el adecuado funcionam iento del proceso com
petitivo en una economía social de mercado, ni que afecten el derecho a la inform ación de
los consumidores sobre los bienesy servicios.
Responsabilidad administrativa de las agencias de publicidad: De acuerdo con el De
creto Legislativo, las agencias de publicidad serán responsables adm inistrativam ente
cuando el acto de competencia desleal se genere como consecuencia de un aspecto dis
tin to de las características propias del bien o servicio anunciado530. En este supuesto, la
530 Debe advertirse que las agencias de publicidad no serán responsables por el contenido de las afirmaciones
publicitarias difundidas sobre las características propias del bien o servicio anunciado sino por la elaboración
y difusión de un anuncio de modo tal que se infrinja lo dispuesto en el Decreto Legislativo y sus normas regla
mentarias.
