ASPECTOS PENALES VINCULADOS A LA COMPETENCIA
En nuestro país, en materia de protección de la libre competencia, la regulación positiva asu
mía el modelo de protección conjunta, lo que significaba tener una protección tanto admi
nistrativa como penal de la libre competencia. La protección administrativa se materializaba
en la Ley contra las Prácticas Monopólicas, Controlistasy Restrictivas de la Libre Competencia
(Decreto Legislativo N°701), mientras que la penal se llevaba a cabo mediante los delitos con
templados en los hoy derogados artículos 232, 233, 238, 239, 240 y 241 inciso 3) del Código
Penal.
El derogado artículo 232o del Código Penal sancionaba a aquel que abusando de su posición
monopólica u oligopólica en el mercado, participaba en prácticas y acuerdos restrictivos en la
actividad productiva, mercantil o de servicios, con el objeto de restringir o distorsionar la libre
competencia, se le reprimía con no menos de dos ni mayor de seis años de pena privativa de la
libertad y con ciento ochenta a trescientos sesenta y cinco días m ulta e inhabilitación confor
