me al artículo 36o inciso 2 y 4, del mismo cuerpo de leyes. Cabe precisar que esta norma tenía
las características de norma penal en blanco, pues condicionaba la penalidad a la remisión a
una ley específica, en este caso al también derogado Decreto Legislativo 701 que disponía la
eliminación de las prácticas monopólicas, controlistasy restrictivas de la libre competencia.
Hoy, con la dación del Decreto Legislativo N ° i0 3 4 , aprobado con la finalidad de adecuar nues
tra legislación al Tratado de Libre Comercio, se sacó del ámbito penal las figuras delictivas de
abuso de poder económico en el mercado (232 CP), acaparamiento (233 CP), publicidad enga
ñosa (238 CP), fraude a los consumidores (239 CP), competencia desleal (240 CP) y licitaciones
colusorias (241 inciso 3 CP), constituyendo estas conductas hoy por hoy como infracciones ad
ministrativas.
A partir de 25 de junio de 2008, fecha que entro en vigencia del D.L. N° 1034, es el Instituto
de Defensa de la Competencia y Defensa del Consumidor - INDECOPI, el ente competente
exclusivo para la realización de la investigación del procedimiento sancionadordel ilícito tip i
ficado en el derogado artículo 232 del C.P hoy ilícito administrativo, a través de la Comisión de
Defensa de la Libre Competenciay el Tribunal a través de la Sala de Defensa de la Competen
cia, y las multas pueden ir desde quinientas (500) a más de mil (1000) Unidades Impositivas
Tributarias (UIT), si se comprueba infracciones que van desde leves a muy graves.
Según lo mencionado por Percy García Cavero esta situación "implicaría decir que estos he
chos no tienen ya desvalor social suficiente como para ser penalmente sancionados. Es decir,
que si las empresas de un determinado sector del mercado pactan desnudamente un precio
perjudicando a los consumidores, no podrán recibir una sanción penal o si una empresa con
posición de dom inio realiza prácticas exclusorias de otros competidores, tampoco podrá re
cibir sanción penal alguna. Tampoco podrá recibir sanción penal el competidor que denigra
manifiestamente los productos del competidor o se aprovecha abiertamente de la reputación
del competidor, así como tampoco el productor, fabricante o comerciante que detrae produc
tos del mercado con la finalidad de generar escasez y perjudicar finalmente a los consumi
dores. Y ni qué decir de aquellas personas que participan en una licitación pública y que se
coluden para fijar un precio y defraudar al Estado, consiguiendo un precio mucho mayor al
que habría resultado de una puja entre empresas realmente competidoras”.
Al respecto Carlos E. Manrique N. ofrece dos definiciones que resumirá el punto solicitado:
“Son los derechos subjetivos que se traducen en un poder jurídico del titu lar que se proyecta
sobre la obra del intelecto o del ingenio; o sea son los derechos que tiene el Autor de una obra
científica, literaria o artística, en virtud de los cuales puede disponer de su obra o bien explo
tarla económicamente por cualquier medio. Este poder jurídico se puede oponer a todos los
integrantes de la sociedad, quienes también con respecto a ellos tienen un deber general de
