“Se comprende en los mismos vocablos de “derechos intelectuales” un cierto número de dere
chos que se aproximan al derecho de propiedad en el sentido de que no tienen sujeto pasivo
determinado; pero que difieren de él, sobre todo, por el objeto sobre el cual recaen, que es
