II. DIVISIÓN DE LA MATERIA
Según la OMPI (Organización Mundial de la Propiedad Intelectual)
LA PROPIEDAD INTELECTUAL tiene que ver con las creaciones de la mente: las invenciones,
las obras literarias y artísticas, los símbolos, los nombres, las imágenesy los dibujosy modelos
utilizados en el comercio.
La propiedad intelectual se divide en dos categorías:
- La Propiedad Industrial, que incluye las invenciones, patentes, marcas, dibujos y modelos
industriales e indicaciones geográficas de procedencia.
-E l Derecho de Autor, que abarca las obras literariasy artísticas, tales como las novelas, los poe
mas y las obras de teatro, las películas, las obras musicales, las obras de arte, tales como los di
bujos, pinturas, fotografías y esculturas, y los diseños arquitectónicos. Los derechos relacionados
con el derecho de autorson los derechos de los artistas intérpretesy ejecutantes sobre sus inter-
pretacionesy ejecuciones, los derechos de los productores de fonogramas sobre sus grabaciones
y los derechos de los organismos de radiodifusión sobre sus programas de radioy de televisión.
1. Los derechos de autor
La OMPI se refiere al Derecho de Autor como “un térm ino jurídico que describe los derechos
concedidos a los creadores por sus obras literarias”.
Guillermo Cabanellas precisa“el que tiene toda persona sobre la obra que produce; y especial
mente, el que corresponde por razón de las obras literarias, artísticas, científicas, técnicas, para
disponer de ellas por todos los medios que las leyes autorizan”.
En el Perú, la Ley de Derechos de Autor (D. Leg. 822) y el Decreto Supremo 061-62-DE regulan
los Derechos de Autor. Sin embargo, la Constitución del país confiere a los tratados internacio
nales un rango mayor que la ley nacional.
Objeto del derecho de autor
El objeto de protección de los Derechos de Autor son las creaciones intelectuales en los cam
pos de la literatura de la literatura, de la música, el arte y la ciencia. Más no las ideas en sí, lo
que se protege es la expresión de las ideas del autor.
De acuerdo a lo previsto en el artículo 1 de la Decisión 351 y artículo 3 del Decreto Legislativo
N°822, para la protección que brinda los Derechos de Autor no interesa el género artístico, el
modo de expresión, la calidad o el propósito de la obra.
6 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1317 of 1506 --

Temas de Propiedad Intelectual
Ingresan dentro del ámbito de protección de los Derechos de Autor, los libros, folletos, confe
rencias, sermones, obras drámaticas, coreográficas, composiciones musicales, obras cinema
tográficas, obras fotográficas, dibujo, pintura, grabado, obras plásticas, planos, adaptaciones,
traducciones, entre otros.
Clases de obras protegidas:
Obras originarias: Está protegida exclusivamente la forma de expresión mediante la cual las
ideas del autor son descritas, explicadas, ilustradas o incorporadas a las obras.
Obras derivadas: Sin perjuicio de los derechos que subsistan sobre la obra originaria y de la
correspondiente autorización, son también objeto de protección como obras derivadas siem
pre que revistan características de originalidad:
a) Las traducciones, adaptaciones.
b) Las revisiones, actualizacionesy anotaciones.
c) Los resúmenes y extractos.
d) Los arreglos musicales.
e) Las demás transformaciones de una obra literaria o artística o de expresiones del folklore.
Colecciones y recopilaciones: Se trata de reunir en una sola obra las contribuciones de dife
rentes autores con un propósito determinado o según un plan. Se brinda protección siempre
que la edición y arreglo hayan implicado una labor intelectual creadora.
También podemos clasificar las obras protegidas del modo siguiente:
Obras literarias: artículos, libros, folletos, escritos de cualquier naturaleza; diccionarios en
ciclopedias, antologías, guías, y compilaciones de toda clase, así como lecciones, planes, dis
cursos, sermones, memorias y obras de naturaleza similar, tanto en forma oral, como escrita
o grabada. Se integran en este rango las versiones de manera íntegra o parcial de discursos
expuestos en celebraciones de carácter oficial o científico, además de las publicaciones tales
como: revistas o diarios, entre otros.
Obras artísticas: aquellas obras de carácter artísticos realizadas con o sin texto, obras teatrales
en general; coreografías; composiciones musicales; obras producidas por radio o televisión y
adaptaciones en estos medios de cualquier obra literaria; obras cinematográficas; dibujos, pin
turas y similares; grabados, litografías, fotografías, entre otras formas de expresión artística.
Obras científicas: proyectos arquitectónicos, sistemas de creación de mapas, obras de carác
ter plástico y obras similares, así como cualquier otro arte o ciencia.
Otras obras: lemas, frases, títulos traducciones, adaptaciones de una obra con su correspon
diente autorización, cualquier otra obra o creación no incluida en las modalidades anteriores,
como es el caso del software.
Contenido del derecho de autor: Derechos morales y Derechos Patrimoniales. Titulares.
En el Derecho de Autor están comprendidos dos tipos de derechos.
Los Derechos Patrimoniales, que son los que permiten que el titular obtenga retribución
financiera por el uso de su obra por terceros.
En la mayoría de legislaciones de Derecho de Autor se estipula que el autor o el titu lar de
los derechos de una obra tienen derecho a autorizar o impedir determinados actos en
relación con su obra.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1318 of 1506 --

UBILEX
Según el artículo 31° del D. Leg. 822, el derecho patrimonial comprende, especialmente, el
derecho exclusivo de realizar, autorizar o prohibir:
a) La reproducción de la obra por cualquier forma o procedimiento.
b) La comunicación al público de la obra por cualquier medio.
c) La distribución al público de la obra.
d) La traducción, adaptación, arreglo u otra transformación de la obra.
En el Perú el derecho patrimonial dura toda la vida del autor y 70 AÑOS después de su
fajlecimiento, cualquiera que sea el país de origen de la obra, y se transmite por causa
de muerte de acuerdo a las disposiciones del Código Civil. El vencimiento de este plazo
implica la extinción del derecho patrimonial y determina el pase de la obra al dominio
público y, en consecuencia, al patrimonio cultural común.
Los D e re c h o s M o ra le s , que permiten que el autor pueda tom ar determinadas medidas
para preservar los vínculos personales que le unen a su obra. En el artículo 6 del Convenio
de Berna se estipula la obligación que tienen los Estados contratantes de conceder a los
autores:
i) El derecho de reivindicar la paternidad de la obra (derecho de paternidad); y
ii) El derecho a oponerse a cualquierdeformación uotra modificación de la obra o cual
quier atentado a la misma que cause perjuicio a su honor o a su reputación (derecho
de integridad).
El D. Leg. N° 822 dispone que los derechos morales reconocidos por la Ley, son perpetuos,
inalienables, inembargables, irrenunciables e imprescriptibles. A la muerte del autor, los
derechos morales serán ejercidos por sus herederos, mientras la obra esté en dominio
privado, salvo disposición legal en contrario.
Son derechos morales:
a) El derecho de divulgación.
b) El derecho de paternidad.
c) El derecho de integridad.
d) El derecho de modificación o variación.
e) El derecho de retiro de la obra del comercio.
f) El derecho de acceso.
Los Titulares, el autor es el titu lar originario de los derechos exclusivos sobre la obra, de
orden moral y patrimonial. Se presume autor, salvo prueba en contrario, a la persona na
tural que aparezca Indicada como tal en la obra, mediante su nombre, firma o signo que
lo identifique.
Cuando la obra se divulgue en forma anónima o bajo seudónimo, el ejercicio de los dere
chos corresponderá a la persona natural o jurídica que la divulgue con el consentimiento
del autor, mientras éste no revele su identidad y justifique su calidad de tal, caso en que
quedarán a salvo los derechos ya adquiridos por terceros.
En el caso de obras derivadas, el autor es el titu la r de los derechos sobre su aporte, sin per
juicio de la protección de los autores de las obras originarias empleadas para realizarla.
8 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1319 of 1506 --

Temas de Propiedad Intelectual
En cuanto a las obras creadas en colaboración, los coautores serán conjuntamente los
titulares originarios de los derechos moralesy patrimoniales sobre las mismas,y deberán
ejercer sus derechos de común acuerdo. Cuando los aportes sean divisibles o la participa
ción de cada uno de los coautores pertenezca a géneros distintos, cada uno de el los podrá,
salvo pacto en contrario, explotar separadamente su contribución personal, siempre que
no perjudique la explotación de la obra común.
En la obra colectiva se presume, salvo prueba en contrario, que los autores han cedido
en forma ilim itada y exclusiva la titularidad de los derechos patrimoniales a la persona
natural o jurídica que la pública o divulga con su propio nombre, quien queda igualmente
facultada para ejercer los derechos morales sobre la obra.
Para las obras audiovisuales, en las obras creadas en cumplimiento de una relación labo
ral o en ejecución de un contrato por encargo, la titularidad de los derechos que puedan
ser transferidos se regirá por lo pactado entre las partes.
En la sociedad conyugal cada cónyuge es titu lar de las obras creadas porcada uno de el los
sobre los que conservarán respectivamente en forma absoluta su derecho moral, pero
los derechos pecuniarios hechos efectivos durante el matrimonio tendrán el carácter de
bienes comunes salvo régimen de separación de patrimonios.
Límites al derecho de explotación:
Según lo previsto por el artículo 41o del D. Leg. 822, las obras del ingenio protegidas por la Ley
podrán ser comunicadas lícitamente, sin necesidad de la autorización del autor ni el pago de
remuneración alguna, en los casos siguientes:
a) Cuando se realicen en un ámbito exclusivamente doméstico, siempre que no exista un
interés económico, directo o indirecto y que la comunicación no fuere deliberadamente
propalada al exterior, en todo o en parte, por cualquier medio.
b) Las efectuadas en el curso de actos oficiales o ceremonias religiosas, de pequeños frag
mentos musicales o de partes de obras de música, siempre que el público pueda asistirá
ellos gratuitamente y ninguno de los participantes en el acto perciba una remuneración
específica por su interpretación o ejecución en dicho acto.
c) Las verificadas con fines exclusivamente didácticos, en el curso de las actividades de una
institución de enseñanza por el personal y los estudiantes de tal institución, siempre que la
comunicación no persiga fines lucrativos, directos o indirectos,y el público esté compuesto
exclusivamente por el personal y estudiantes de la institución o padres o tutores de alumnos
y otras personas directamente vinculadas con las actividades de la institución.
d) Las que se realicen dentro de establecimientos de comercio, para los fines demostrativos
de la clientela, de equipos receptores, reproductores u otros similares o para la venta de
los soportes sonoros o audiovisuales que contienen las obras, siemprey cuando la comu
nicación no fuere deliberadamente propalada al exterior, en todo o en parte.
e) Las realizadas como indispensables para llevar a cabo una prueba judicial o administrativa.
No son objeto de protección por el derecho de autor: a) Las ideas contenidas en las obras lite
rarias o artísticas, los procedimientos, métodos de operación o conceptos matemáticos en sí,
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1320 of 1506 --

UBILEX
los sistemas o el contenido ideológico o técnico de las obras científicas, ni su aprovechamiento
industrial o comercial, b) Los textos oficiales de carácter legislativo, administrativo o judicial,
ni las traducciones oficiales de los mismos, sin perjuicio de la obligación de respetar los textos
y citar la fuente, c) Las noticias del día, pero, en caso de reproducción textual, deberá citarse la
fuente de donde han sido tomadas, d) Los simples hechos o datos.
La protección de la obra no alcanza al uso privado o gratuito. El principio consiste en que si no
existen objetivos de lucro, cualquier persona puede fotocopiar las obras que necesita para uso
estrictamente personal.
La reproducción efectuada por archivos o bibliotecas está autorizada, puesto que garantizan
la conservación de las obras depositadas y las ponen a disposición del público en general.
La reproducción de obras de arte, monumentos y edificios ubicados de manera permanente
en lugares públicos, sin autorización del autor.
Una vez caducados los Derechos de Autor (70 años después de su muerte) las obras pasan al
dominio público.
Infracciones: Se considera infracción la vulneración de cualquiera de las disposiciones conte
nidas en el Decreto Legislativo N° 822.
A requerimiento del titu lar del respectivo derecho o de la sociedad de gestión colectiva que
lo represente, la Autoridad Policial, comprobará, de inmediato, la comisión de cualquier acto
infractorio a la Ley, entregando copia de la constatación al interesado.
Cuando los hechos materia del procedimiento administrativo constituyan presunto delito, la
Oficina de Derechos de Autor podrá form ular denuncia penal ante el Ministerio Público. En
caso que la Oficina de Derechos de Autor hubiera destruido o dispuesto de los ejemplares
que constituían materia de la infracción del Derecho de Autor o de los Derechos Conexos, se
acompañará a la denuncia copia certificada de la resolución administrativa correspondiente,
así como copias de las actas vinculadas con tales medidas en las que conste la relación de los
bienes objeto de las mismas, a efectos de su valoración como prueba del presunto delito.
Tipificación de infracciones: La legislación vigente tipifica las infracciones dentro del ámbito
penal como delitos las conductas siguientes:
Plagio: Se configura cuando se produce en forma parcial o completamente una obra ajena
que se presenta como si fuera propia. Del mismo modo, se produce cuando se desfigura, alte
ra o suprime el nombre del verdadero autor (art. 219 CP).
Piratería: Si se produce la modificación, reproducción, distribución, difusión total o parcial así
como la representación o distribución excesiva al autorizado por escrito; quien la ejecute res
pecto de una obra, interpretación o ejecución artística, fonograma, emisión de radiodifusión,
grabación audiovisual, imagen fotográfica sin la autorización previa y por escrito del autor o
titu lar de los derechos; estará incurso en esta infracción (art. 217 CP).
Admitiendo además formas agravadas de los tipos penales básicos.
2. Propiedad industrial: características y contenido
La propiedad industrial es un tipo especial de propiedad que recae sobre bienes de carácter
inmaterial, como son las creaciones e invenciones, con aplicación en la industriay en el mer
cado. El derecho de propiedad se adquiere mediante el registro de la invención desarrollada,
obteniéndose una patente.
32 ■ BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1321 of 1506 --

Temas de Propiedad Intelectual
Las principales características de la propiedad industrial son las siguientes:
Recae sobre bienes de naturaleza inmaterial, es decir las invenciones.
Tiene carácter patrimonial ya que puede cederse, transmitirse, licenciarse.
Tiene duración limitada, luego de la cual lainvención pasaaser de dom inio público.
Tiene limitación territorial o validez sólo donde se solicitay concede.
Confiere a su titu lar un derecho de exclusividad para su explotación.
Confiere a su titular una protección respecto de la imitación o reproducción no autorizada.
Permite capitalizar los esfuerzos de la actividad investigativa.
Incentiva la investigación.
Contribuye a formar fondos documentales.
Según la OMPI la Propiedad Industrial, involucra la protección de las creaciones nuevas (pa
tentes de invención, certificados de protección, diseños industriales, modelos de útil idad, y se
cretos industriales) y los Signos Distintivos (marcas de producto y de servicio, marcas de certi
ficación y de garantía, nombres comerciales, lemas comercialesy denominaciones de origen).
Las siguientes son las normas legales que protegen la propiedad industrial en el Perú:
Convenio de París de 1884.
Tratado Bilateral Firmado con Francia de 1896.
Convención Panamericana de Washington dei929.
Acuerdo por el que se establece la organización Mundial del Comercio y los Acuerdos Co
merciales Multilaterales contenidos en el acta final de la Ronda Uruguay.
Decisión 344 del Acuerdo de Cartagena.
Decisión 486- Régimen Común sobre Propiedad Industrial.
Decreto Legislativo que aprueba Disposiciones Complementarias a la Decisión 486 de la
Comunidad Andina que establece el Régimen Común sobre Propiedad Industrial- Decre
to Legislativo N°1075.
Reglamento del Decreto Legislativo N° 1075- Decreto Supremo N° 059-2017-PCM.
Para efectos del Decreto Legislativo N°i075, constituyen elementos de la propiedad industrial:
a) Las patentes de invención; b) Los certificados de protección; c) Las patentes de modelos de
utilidad; d) Los diseños industriales; e) Los secretos empresariales; f) Los esquemas de trazado
de circuitos integrados; g) Las marcas de productos y de servicios; h) Las marcas colectivas; i)
Las marcas de certificación; j) Los nombres comerciales; k) Los lemas comerciales; I) Las deno
minaciones de origen; m) Las indicaciones geográficas; y n) Las especialidades tradicionales
garantizadas.
3. Patentes de invención
Una patente de invención se define como el título que se le da a la persona que lleve acabo el
registro de su invención ante el INDECOP1. La patente convierte al creador en el dueño de su
invención protegiéndola de las posibles copias de otras personas y evitando que se utilice sin
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1322 of 1506 --

UBI LEX
que él obtenga algún beneficio. Es decir, el Estado le concede al dueño de la patente el derecho
exclusivo de explotación de su invención, a cambio de que el inventor dé a conocer su invento
para que pueda contribuir con el desarrollo del país.
La patente confiere a su titu lar el derecho de impedir que terceras personas - que no partici
paron en su creación, ni cuentan con la autorización del o los creadores - fabriquen, ofrezcan
en venta, utilicen o importen, en el territorio peruano la patente de invención porel tiempo de
duración de la patente.
Puede ser objeto de una patente de invención un procedimiento, un método de fabricación,
una máquina o aparato, o un producto. No se pueden proteger mediante una patente de in
vención los descubrimientos, las teorías científicas o métodos matemáticos, los métodos eco
nómico-comerciales, los programas de ordenador, las razas animales, las variedades vegeta
les, o las invenciones que sean contrarias al orden público o las buenas costumbres. Tampoco
se pueden proteger por patentes de invención las obras literarias, artísticas o científicas, cuya
protección legal se realiza a través de los derechos de autor.
Requisitos de patentabilidad: Para que la invención sea protegida mediante una patente de
invención, debe cumplir con tres requisitos fundamentales:
Novedad: el invento debe ser absolutamente novedoso en la medida en que el inventor
no puede haber tenido acceso a él por ningún medio más que el de su creatividad.
Nivel Inventivo: es indispensable que la invención tenga un nivel inventivo razonable, es de
cir, que no sea una invención muy obvia o elemental que se le pueda ocurrir a cualquiera.
Aplicación en la industria: debe tener la posibilidad de ser fabricado o utilizado en ella.
La patente de invención se otorga por 20 años contados a partir de la fecha de presentación de
la solicitud correspondiente.
No invenciones
