3.1. Modelos de utilidad
Un modelo de utilidad es una invención relacionada a toda nueva forma, configuración o dis
posición de elementos de algún artefacto, herramienta, instrumento, mecanismo u otro obje
to o de alguna parte del mismo que permita un m ejoro diferente funcionamiento, utilización
o fabricación del objeto que lo incorpora o que le proporcione alguna utilidad, ventaja o efecto
técnico que antes no tenía.
322 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1323 of 1506 --

Temas de Propiedad Intelectual
No se considerarán modelos de utilidad: las obras plásticas, las de arquitectura, ni los objetos
que tuvieran únicamente carácter estético. Asimismo, no podrán ser objeto de una patente de
modelo de utilidad, los procedimientosy las materias excluidas de la protección por la paten
te de invención.
El plazo de duración del modelo de utilidad será de 10 años contados desde la fecha de pre
sentación de la solicitud en el respectivo País Miembro.
3.2. Diseños industriales
Se considerará como diseño industrial la apariencia particular de un producto que resulte de
cualquier reunión de líneas o combinación de colores, o de cualquierform a externa bidimen-
sional o tridimensional, línea, contorno, configuración, textura o material, sin que cambie el
destino o finalidad de dicho producto. Los diseños industriales pueden ser aplicados a una
gran variedad de productos de la industria y la artesanía, desde joyas y otros artículos de lujo,
instrumentos técnicos, médicos a relojes, electrodomésticos, aparatos eléctricos, vehículos y
estructuras arquitectónicas, desde estampados textiles a bienes recreativos. Los titulares de
diseños industriales registrados gozaran de un derecho exclusivo de explotación comercial, el
cual tiene unaduración de 10 años contados a partirde la presentación de lasolicitud.
3.3. Secretos industriales
Son susceptibles de protección como secreto industrial tanto el conocimiento tecnológico in
tegrado por procedimientos de fabricación y producción en general como el conocimiento re
lativo al em pleoy aplicación de técnicas industriales, resultantes del conocimiento, experien
cia o habilidad intelectual que guarde una persona con carácter confidencial y que le permita
obtener o mantener una ventaja competitiva o económica frente a terceros.
No se considerará como secreto industrial aquella información que sea del dom inio público, la
que resulte evidente para un técnico en la materia o laque deba ser divulgada por disposición
legal o por orden judicial. Asimismo, no constituye secreto de producción la habilidad manual
o la aptitud personal de uno o varios trabajadores. No se considerará que entre al dom inio pú
blico o que sea divulgada por disposición legal, aquella información que sea proporcionada a
cualquier autoridad por una persona que la posea, cuando la proporcione a efecto de obtener
licencias, permisos, autorizaciones, registros o cualesquiera otros actos de autoridad.
Quien lícitamente tenga control de un secreto industrial, estará protegido contra la revelación,
adquisición o uso de tal secreto sin su consentimiento, de manera contraria a las prácticas
leales de comercio, por parte de terceros, en la medida que:
a) La información sea secreta en el sentido que como conjunto o en la configuración y com
posición precisas de sus elementos, no sea conocida en general ni fácilmente accesible a
las personas integrantes de los círculos que normalmente manejan el tipo de información
de que se trate;
b) La información tenga un valor comercial efectivo o potencial por ser secreta; y,
c) En las circunstancias dadas, la persona que legalmente la tenga bajo control, haya adop
tado medidas razonables para mantenerla secreta.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1324 of 1506 --

La información de un secreto industrial necesariamente deberá estar referida a la naturaleza,
características o finalidades de los productos; a los métodos o procesos de producción; o, a los
medios o formas de distribución o comercialización de productos o prestación de servicios.
4 . l a r c a s
Doctrinariamente se entiende por marca, aquel signo que sirve para distinguir en el mercado,
los productos y/o servicios de una persona, de los productos y/o servicios de otra persona, el
cual debe ser perceptible, suficientemente distintivo y susceptible de representación gráfica;
conforme lo establece el Título VI de la Decisión 486, concordante con el Título VI del Decreto
Legislativo 1075 (Arts. 45 al 74).
Las Marcas son: M arca de Producto: Distingue al bien o producto puesto en el comercio por un
fabricante o comerciante. M arca de Servicio: Distingue un servicio de otro realizado por los co
merciantes, no distingue un artículo material sino un servicio el cual posee determinadas ca
racterísticas; como ejemplo tenemos a los servicios de hotelería, de restaurant, de limpieza, de
transporte. M arca C olectiva y de C ertificación: A rts 77 y 8 o, respectivamente, del D. Leg. N ° i0 7 5 ,
se señala que una marca colectiva o una marca de certificación podrán estar conformadas por
cualquierelemento que identifique al producto al cual se aplique como originario de un lugar
geográfico determinado. Cuando determinada calidad, reputación, u otra característica del
producto sea atribuible fundamentalmente a su origen geográfico significa que estas marcas
colectivas y de certificación pueden ser denominativas, figurativas o mixtas y que cualquiera
de sus elementos puede identificar el lugar geográfico originario del producto o servicio. El
D. Leg. N°i075 se refiere a que las marcas colectivas y las marcas de certificación pueden es
tar conformadas por la indicación o identificación al producto pero combinada con otros ele
mentos figurativos o denominativos que le den al conjunto marcario suficiente distintividady
cumpla con el artículo 134 de la exigencia de distintividad para la validez de la marca.
Las principales funciones de la marca son.-
i .- Indicadora de Origen; 2.- Garantía; 3.- Publicidad; y 4.- Distintiva:
Es importante mencionar que nuestra ley ha adoptado el sistema atributivo para la adquisi
ción del derecho exclusivo sobre la marca, mediante este sistema se le “otorga” o “atribuye” el
derecho a quien obtiene el registro de la marca ante el organismo nacional competente, en tal
sentido, los principales derechos que otorgue al titu lar de una marca, cuando ésta se encuen
tra registrada, son:
Derecho de uso exclusivo: Entendido como el derecho del titu la r de “excluir a los demás” del uso
de ese signo para los mismos productos o servicios.
Derecho de Prioridad: Este derecho está directamente relacionado con los convenios internacio
nales o legislaciones comunitarias, y es mediante el cual un solicitante o titu lar de una marca
tiene la posibilidad de presentar su solicitud en otro país miembro (del acuerdo o convenio)
dentro de un plazo que generalmente es de seis meses a un año,y se le considerará presentada
el mismo día que en el primer país donde obtuvo el registro o presentó su solicitud.
Derecho de Acción: El derecho de uso exclusivo o también considerado como contraparte “Jus
Prohibendi" se manifiesta en el derecho de acción que el titu la r del derecho de propiedad podrá
