ejercer para impedir a terceros, que realicen actividad económica usando el signo registrado.
Al adquirir una persona el derecho sobre una marca también adquiere el derecho de interpo
ner una acción adm inistrativay judicial.
4.1. Nombres com erciales
Es aquel signo que sirve para identificar a una persona natural o jurídica en el ejercicio de su
actividad económica.
A diferencia de las marcas y demás elementos de la propiedad industrial, la Ley de Propiedad
Industrial establece, que el derecho a un nombre comercial se adquiere por el uso de éste en
el país, de tal forma que, para beneficiarse de los derechos sobre el nombre comercial, no es
necesario contar con su registro.
Para llevar a cabo el registro de un nombre comercial es necesario acreditar su uso. El registro
confiere derechos sobre el nombre comercial a nivel nacional.
El registro es válido por diez años, renovables indefinidamente por períodos consecutivos.
4.2= Lemas comerciales
Es la palabra o conjunto de palabras que se utilizan como complemento de una marca o nom
bre comercial,ysu función principal es publ icitar a aquel los.
El registro de un lema comercial se concederá por un período de diez años renovables, conta
dos a partir de la resolución que concede el derecho.
No podrán registrarse lemas comerciales que contengan alusiones a productos o marcas sim i
lares o expresiones que puedan perjudicar a dichos productos o marcas.
4.3. Certificados de protección
Cualquier inventordomiciliado en el paísque tengaen estudio un proyecto de invencióny que
necesite experimentar o construir algún mecanismo que le obligue a hacer pública su idea,
podrá solicitar un certificado de protección que la Dirección competente le otorgará por el
término de un año.
4.4. Denominaciones de origen
Condensan un conjunto de valores comerciales, de calidad, de tradiciones culturales. La unici
dad que distingue el lugar geográfico con el producto que denomina le da a la denominación
un valor toponímico que permanece en el tiempo y, en la medida de su uso, puede alcanzar
renombrey llegara identificar la región o todo el país.
El Estado es el titu lar de las denominaciones de origen reconocidas, según lo dispuesto en el
Art. 88 del D Li075;y es quien actualmente otorga las autorizaciones de uso y controla la cali
dad de los productos con denominaciones de origen. Sin embargo, podría delegar la función
de administración y autorización de uso al consejo regulador de la denominación de origen,
luego de su inscripción, reconocimiento y evaluación realizada por la autoridad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1326 of 1506 --

