4.5. Las indicaciones geográficas
En los Acuerdos sobre los Aspectos de los Derechos de Propiedad Intelectual Relacionados con
el Comercio (ADPIC), se considera que las Indicaciones Geográficas son identificadoras de un
producto como originario de un lugar o región, y se le atribuye su calidad o reputación a dicho
origen, aunque no se deban necesariamente al lugar geográfico.
4.6. Las especialidades tradicionales garantizadas
Las especialidades tradicionales garantizadas a las que hace mención el literal n) del artículo
3 del Decreto Legislativo 1075 buscan proteger las recetas tradicionales, los métodos de pro
ducción o transformación que correspondan a la práctica tradicional aplicable a un producto
o alimento contribuyendo a dar valor agregado a los productos tradicionales en su comercia
lización, producción o transformación; y, a informar a los consumidores de sus atributos. (Art.
3 del D. Leg. N°1397)
NULIDADES Y CANCELACIONES DE REGISTROS
Nulidad de Registro de Marca
El artículo N° 172 de la Decisión 486 señala que la autoridad nacional competente decretará
de oficio o a solicitud de cualquier persona y en cualquier momento, la nulidad absoluta de
un registro de marca cuando se hubiese concedido en contravención con lo dispuesto en los
artículos 134 primer párrafo y 135 del referido Acuerdo de Cartagena.
La autoridad nacional competente decretará de oficio o a solicitud de cualquier persona, la
nulidad relativa de un registro de marca cuando se hubiese concedido en contravención de lo
dispuesto en el artículo 136 o cuando éstese hubiera efectuado de mala fe. Esta acción prescri
birá a los cinco años contados desde la fecha de concesión del registro impugnado.
De acuerdo a lo dispuesto en el artículo 73 del D. Leg. 1075 la solicitud de nulidad del registro
de una marca se presenta ante la Dirección competente y debe cumplir, en cuanto correspon
da con los requisitos para presentar la oposición.
No procede la solicitud de nulidad, si el asunto fue materia de oposición por los mismos fun
damentos entre las mismas partes o la que de ellas derive su derecho.
Recibida la solicitud de nulidad, la Dirección competente notificará al titu la r de la marca, su
jetándose para tales efectos a lo dispuesto en el Art. 72 del D. Leg. 1075, para que dentro del
plazo de 02 meses haga valer los argumentos y presente los medios probatorios que estime
convenientes, los interesados podrán solicitar una prórroga por 02 meses adicionales. Venci
dos los plazos la Dirección competente decidirá sobre la nulidad del registro, lo cual notificará
a las partes mediante resolución.
Cancelación de Registro de Marca:
Cuando una causal de nulidad sólo se aplicará a uno o a algunos de los productos o servicios
para los cuales la marca fue registrada, se declarará la nulidad únicamente para esos produc
tos o servicios, y se eliminarán del registro de la marca.
La cancelación de un registro es una acción legal, que permite que un registro de marca puede
ser cancelado a sol icitud de cualq uier parte i nteresada cuando, si n motivo justificado, la marca
