no hubiese sido usada en al menos uno de los países miembros de la Común idad Andina por
su titular, por un licenciatario o por un tercero autorizado para ello, durante los tres años con
secutivos precedentes a la fecha en que se inicie la acción de cancelación.
Se entenderá que una marca se encuentra en uso cuando los productos o servicios que ella
distingue han sido puestos en el comercio o se encuentran disponibles en el mercado bajo
esa marca, en la cantidad y del modo que normalmente corresponde, teniendo en cuenta la
naturaleza de los productos o servicios y las modalidades bajo las cuales se efectúa su comer
cialización en el mercado.
El artículo N ° i6 s de la Decisión 486 señala que cuando la falta de uso de una marca sólo afec
tara a uno o a algunos de los productos o servicios para los cuales estuviese registrada la marca,
se ordenará una reducción o limitación de la lista de los productos o servicios comprendidos
en el registro de la marca, eliminando aquéllos respecto de los cuales la marca no se hubiese
usado; para ello se tomará en cuenta la identidad o sim ilitud de los productos o servicios.
El registro no podrá cancelarse cuando el titu lar demuestre que la falta de uso se debió, entre
otros, a fuerza mayor o caso fortuito.
LICENCIAS DE MARCAS Y PATENTES
Licencias de marcas: La marca podrá ser objeto de licencias para la totalidad o parte de los
productos o servicios para los cuales se registró. En caso de licencia de marcas, el licenciante
responde ante los consumidores por la calidad e idoneidad de los productos o servicios licen
ciados como si fuese el productor o prestador de éstos.
Licencia de patentes: El titu la r de una patente podrá conceder a otra persona licencia para su
explotación, sólo mediante contrato escrito. Los contratos de licencia deberán ser registrados
ante la Oficina competente, sin lo cual, no surtirán efectos frente a terceros.
La Oficina competente no registrará los contratos de licencia para la explotación de patentes
que no se ajusten a las disposiciones del Régimen Común de Tratamiento a los Capitales Ex
tranjeros y sobre Marcas, Patentes, Licencias y Regalías establecido en la Decisión 291 de la
Comisión del Acuerdo de Cartagena.
DERECHO REG18IRM
El Derecho Registral es el conjunto de principios y normas que estudia la tutela de ciertas si
tuaciones jurídicas subjetivas a través del sistema de publicidad registral (organización pú
blica) que produce diversos y determinados efectos jurídicos sustantivos de derecho privado
(tales como el nacimiento, preferencia^ oponibilidad de dichas situaciones jurídicas), y cuya
finalidad es dotar de seguridad y justicia al tráfico de intereses económicos.
I. FINALIDAD
A decir de Cunther Conzales la finalidad del Derecho Registral es arbitrar un sistema que
permita conocer el estado de los derechos (por ejemplo: el propietario, los gravámenes, la si
tuación física), fa cilita nd o de esta manera su tráfico patrimonial en condiciones armónicas
