d«2 justicia j segwridad. El Registro es una institución para dar respuesta a las apremiantes
necesidades de facilitación del tráfico patrimonial, de certidumbre en la titularidad de los de
rechos y de estabilidad en la circulación de la riqueza, por lo que se debe encuadrar como una
figura de seguridad justa, y no sólo ante un instituto de mera seguridad vaciado de contenido
o sin finalidades valiosas.
1. Principio de Rogación: Este principio se encuentra consagrado en el prim er párrafo
del artículo 2011o del Código Civil: “Los registradores califican la legalidad de los documentos en
cuya virtud se solicita la inscripción, la capacidad de los otorgantesy la validez del acto, por lo que resulta
de ellos, de sus antecedentesy de los asientos de los registros públicos.
Se define como aquel principio en virtud del que las actuaciones regístrales han de ser
solicitadas por la parte interesada o un funcionario legitimado para ello, sin que el regis
trador pueda actuar de oficio.
La rogación es un principio registral, en virtud del cual las inscripciones regístrales deben
ser indefectiblemente a solicitud de parte; sin embargo, esto no impide que se puedan
dar inscripciones de oficio, aunque estas tengan carácter excepcional, tales como la ins
cripción de la hipoteca legal y la inscripción del tracto sucesivo o la rectificación de áreas
dentro del proceso de formalización de los asentamientos humanos (COFOPRI)531.
La rogatoria de inscripción implica a todos aquellos actos inscribibles contenidos en el
título y no sólo aquél o aquellos que estén consignados en el form ulario de solicitud de
inscripción532.
2. Principio de Publicidad: Se encuentra consagrado en el artículo 2012o Código Civil. “Se
presume, sin admitirse prueba en contrario, que toda persona tiene conocimiento del contenido de
las inscripciones".
No es en estricto un principio, sino un efecto de él. El Registrador otorga publicidad jurídi
ca a los diversos actos o derechos inscritos.
Se presume sin adm itir prueba en contrario, que todos conocen del contenido de las ins
cripciones (publicidad material). La publicidad registral formal garantiza que toda perso
na acceda al conocimiento efectivo del contenido de las partidas regístrales y, en general,
obtenga información del archivo Registral (publicidad formal).
Publicidad Material: Dispuesto por Ley. Nadie puede alegar su desconocimiento. El conte
nido de las partidas regístrales afecta a los terceros aun cuando éstos no hubieran tenido
conocimiento efectivo del mismo.
Publicidad Formal: Efectuada por el registrador. Informa a quien solícita la información
contenida en el archivo registral salvo prohibiciones expresas establecidas en el Regla
mento.
