Principio de Legitimación: Se encuentra consagrado en el artículo 2013o del Código Civil: “El
contenido del asiento registral se presume cierto y produce todos sus efectos, mientras no se rectifi
que por las instancias regístrales o se declare su invalidez por el órgano judicial o a rb itra l mediante
resolución o laudo firme.
El asiento registral debe ser cancelado en sede a d m inistrativa cuando se acredite la suplan
tación de identidad o falsedad docum entaría y los supuestos así establecidos con arreglo a las
disposiciones vigentes.
La inscripción no convalida los actos quesean nulos o anulables con arreglo a las disposiciones vigentes".
Los asientos regístrales se presumen exactos y válidos. Producen todos sus efectos y
legitim an al titu la r Registral para actuar conforme a ellos, m ientras no se rectifiquen
en los térm inos establecidos en este Reglamento o se declaresu invalidez por la vía
judicial o a rb itra l.533
Clases de legitimación registral:
-Legitim ación Activa: protege al titular.
-Legitim ación Pasiva.- protege al tercero.
Sin embargo, en nuestro sistema registral las inscripciones no son convalidantes de los actos
inscritos, la inscripción no bonifica ni sanea el título. Su contenido puede ser impugnado en
sede judicial. Sólo el poder judicial puede declarar la nulidad de una inscripción, es decir, ener
var la presunción de exactitudy validez de los asientos regístrales.
En cuanto a la rectificación de los asientos regístrales, ésta podrá efectuarse en sede registral,
bajo los supuestos y exigencias establecidas en el Reglamento. Cuando se trate de errores mate
riales su rectificación será factible ante la autoridad registral. En el caso de errores de concepto,
la rectificación podrá ser practicada directamente en el Registro, si es que la inexactitud consta
claramente de los títulos archivados que dieron lugar a la extensión de los asientos respectivos.
