4. Principio de Tracto Sucesivo: En cuanto a su función, el tracto sucesivo sirve para acreditar,
por un lado, que el derecho en cuestión está en el patrimonio del transm itenteo de la persona
contra la que se dirige el mandamiento judicial o administrativo, en el caso de que lo que se
pretenda sea garantizar la eficacia de la ejecución de la sentencia o resolución administrativa
que, en su día, se dicte, y, por otro, que el derecho subsiste. Por últim o y, si lo ponemos en re
lación con la publicidad material a que antes nos hemos referido, el tracto sucesivo sirve para
inform ara los interesados del historial jurídico de una finca.
El principal efecto que se deriva de la aplicación de este principio es el de servir de base al
juego de la presunción de legitim ación que ampara al titu la r registral.
Se encuentra regulado en el artículo 2015o Código Civil, constituye un m andato esencial
mente de técnica registral dirigido a la actuación del Registrador. Su base es el ordena
m iento y concatenación de los asientos regístrales, de m odo que se produzca la realidad
extraregistral respecto a cada inm ueble inscrito.534
