§. Principio de Prioridad: Cabe definir, siguiendo al repetido García García, a la prioridad
como el principio en virtud del cual los títulos o derechos que acceden al registro prevalecen
en caso de conflicto frente a los títulos o derechos que no han accedido al mismo o sobre los
que lo han hecho con posterioridad, atendiendo a las fechas de presentación en el registro de
la propiedad.
La prioridad se funda en la necesidad de fija r un criterio que, en caso de conflicto entre dos
derechos reales sobre un m ism o bien inmueble, determ ine cuál de ellos hade prevalecer.
Dado el carácter absoluto de los derechos reales, de m odo tal que el reconocido a favor
de una persona excluye la titu la rid a d de ese mismo derecho a favor de cualquiera otra
(piénsese por ejem plo en el caso de la propiedad), es necesario que todas las legislaciones
determ inen cuál es la regla que se aplicará para resolver este conflicto. Caso contrario, no
nos encontraríamos propiam ente ante un Estado de Derechoya que todas las situaciones
estarían rodeadas de una inseguridad que conduciría derechamente a la arbitrariedad. La
prioridad tiene dos aspectos, la preferente y la excluyente.
En cuanto a la preferente, el artículo z o i6 °Código Civil señala:
Los derechos que otorgan los Registros Públicos están determ inados por la fecha de su
inscripción y a su vez la fecha de su inscripción se determ ina por el d ía y hora de su pre
sentación.
Este principio es denom inado tam bién Prioridad de Rango: la prioridad en el tiem po de la
inscripción determ ina la preferencia de los derechos que otorga el Registro.
