La prioridad o preferencia es un efecto derivado de la presentación en el Registro de diver
sos títulos relativos a un mismo inmueble. El prim eram ente presentado goza, en realidad,
de una doble preferencia sobre los presentados con posterioridad535:
i. Preferencia formal: el título que primero llega al Registro se despacha antes que el llega
do después. El Registrador tiene obligación de despachar los títulos porel riguroso orden
de su presentación al Registro.
z. Preferencia sustantiva: el derecho contenido en el título primeramente presentado es
preferente al contenido en el título posteriormente presentado.
V ''i
j£	É	í "El derecho adquirido como consecuencia de la ejecución de la garantía hipotecaria, prevalece
frente a los actos o derechos inscritos con posterioridad a la fecha de! asiento de presentación
de la hipoteca". Resolución N* 757~?.0Q8SUNARP-TR~L
6 . Principio de Impenetrabilidad: Tiene como propósito, impedir que se inscriban derechos
que se opongan o sean incompatibles con otro, aunque sean de igual o fecha anterior. Para
este supuesto, los actos o derechos contenidos en los títulos en conflicto son incompatibles
entre sí, por lo que no procede la inscripción de ambos ni la determinación de su preferencia
y rango, sino que la inscripción o presentación del primero, determinará el “cierre registral”
respecto al presentado en segundo lugar.
No debe confundirse con el principio de prioridad preferente. Pues va dirigida al Registrador
para que se abstengan de inscribir el Título o acto registrable que simplemente resulte incom
patible con otro cuyo asiento de presentación está vigente.
Encontrándose vigente el asiento de presentación, no podrá inscribirse ningún título referente
a la misma partida o asiento. No puede inscribirse un título incompatible con otroya inscrito,
aunque sea de fecha anterior. Esto determina el cierre registral definitivo.
En el caso de un título simplemente presentado con fecha anterior, el cierre registral será pro
visional, en cuanto de no inscribirse éste y caducar la vigencia de su asiento de presentación,
cesarán los efectos del cierre registral, permitiéndose la inscripción del título incompatible
presentado en segundo lugar.
III. TIPOS DE REGISTROS
REGISTRO DE LA PROPIEDAD INMUEBLE:
Es el encargado de la inscripción y publicidad de los actos y contratos sobre bienes inmuebles.
Por ejemplo: terrenos, casas, edificios, predios, etc.
El Registro de Propiedad Inmueble comprende los siguientes Registros:
Registro de predios,
Registro de naves y embarcaciones,
