Registro de concesiones para la explotación de servicios públicos,
Registro de Áreas Naturales Protegidas,
Registro de derechos mineros.
El Registro de Propiedad Inmueble otorga seguridad jurídicay legitima al que tiene su derecho
inscrito. Permite un adecuado tráfico jurídico, ya que el inmueble inscrito puede transferirse o
darse en garantía para solicitar un crédito en alguna entidad financiera. También el Registro
permite brindar información de los distintos actos relacionados con los bienes registrables, así
como conocer su historial registral.
Las inscripciones declarativas que se consignan en el Registro no perfeccionan o modifican el
acto jurídico materia de inscripción, pues lo único que hacen es reconocer una situación de
derecho preexistente.
Los asientos del Registro de la propiedad inmueble gozan de publicidad frente a terceros. Sus
efectos se retrotraen al momento de la inscripción en el asiento respectivo.
Actos y contratos inscribibles (Art. 2019o C. C.): Son inscribibles en el registro del departa
mento o provincia donde esté ubicado cada inmueble:
1.- Los actos y contratos que constituyen, declaren, trasmitan, extingan, modifiquen o lim i
ten los derechos reales sobre inmuebles.
z.- Los contratos de opción.
3. - Los pactos de reserva de propiedad y de retroventa.
4. - El cumplim iento total o parcial de las condiciones de las cuales dependan los efectos de
los actos o contratos registrados.
5 . - Las restricciones en las facultades del titu lar del derecho inscrito.
6 . - Los contratos de arrendamiento.
7. - Los embargosy demandas verosímilmente acreditados.
8 . - Las sentencias u otras resoluciones que a criterio del juez se refieran a actos o contratos
inscribibles.
9. - Las autorizaciones judiciales que permitan practicar actos inscribibles sobre inmuebles.
Los actos o títulos referentes a lasóla posesión, que aún no han cumplido con el plazo de pres
cripción adquisitiva, no son inscribibles.
Si algún inmueble estuviese ubicado en territorio perteneciente a dos o más Distritos, la ins
cripción se verificará en todos ellos.
Cuando en los contratos y otros actos jurídicos sujetos a inscripción, se reserve cualquier de
recho inscribible a favor de persona que no haya sido parte en los contratos o actos, el funcio
nario que autorice el título deberá avisar por escrito a la persona a cuyo favor se ha hecho la
reserva.
La inscripción primera de dominio: O inmatriculación. Ingreso por primera vez al registro.
Para la primera inscripción de dominio, se debe exhibir títulos que consten de instrumentos
públicos por un periodo ininterrum pido de cinco años o, en su defecto, títulos supletorios.
