La primera inscripción de Dominio o ¡nmatriculación da origen a la partida registral del in
mueble o unidad inmobiliaria.
Se extiende en un solo asiento y debe tener tres partes:
a. La descripción del predio.
b. El nombre del Titular.
c. Historia del Dominio.
Partida registral: El artículo 6o del T.U.O. del Reglamento General de los Registros Públicos
establece que la partida registral es la unidad de registro, conformada por los asientos de ins
cripción organizados sobre la base de la determinación del bien o de la persona susceptible
de inscripción; y, excepcionalmente, en función de otro elemento previsto en disposiciones
especiales.
En la Partida se anotarán todos los actos y contratos relativos a dicho bien y servirá para iden
tificarlo y diferenciarlo de otros en los registros de la propiedad inmueble. Antecedente de
dominio, títulos, gravámenes, cancelaciones, reglas.
Registro de Personas Jurídicas:
El Registro de Personas Jurídicas está organizado en función de cada ente societario o no socie
tario. Esto implica abrir una partida por cada persona jurídica, en la que se inscribe su consti
tución, su estatuto, modificación del estatuto, extinción, así como el desenvolvimiento de sus
órganos directivos, entre otros órganos inscribibles.
Con la primera inscripción, la organización adquiere personalidad jurídica. De esta manera,
surge la persona jurídica como centro de imputación de derechosy obligaciones.
• En el ámbito no societario, encontramos los siguientes tipos de persona jurídica:
Asociaciones
Fundaciones
Comités
Comunidades campesinas y nativas
Cooperativas
Organizaciones sociales de base
• En el ámbito societario encontramos, entre otros:
Sociedades Anónimas (abiertas y cerradas)
Sociedades Colectivas
Sociedades en Comandita
Sociedad Comercial de Responsabilidad Limitada
Sociedades Civiles
Actos inscribibles:
a. El acto constitutivo, modificación, ampliación de su constitución y el contenido del esta
tuto.
