La constitución de la persona jurídica se inscribe en el registro correspondiente a su dom ici
lio. No se requiere el otorgamiento de escritura pública para la inscripción del nombramiento
de representantes, mandatarios y otorgamiento de poderes. Para su inscripción basta la pre
