Registro de Personas Naturales:
Es el Registro responsable de la inscripción y publicidad de actos y contratos referidos a perso
nas naturales; por lo que unifica a los siguientes Registros:
i . Registro de Mandatos y Poderes:
La publicidad de los asientos inscritos en este registro en relación con 3 ros registrables.
Los actos jurídicos pueden ser celebrados directamente por el interesado o por medio de
otra persona. La representación facilita la concertación de actos jurídicos pues permite
celebrarlos entre personas ausentes o que porcualquiersituación estén impedidos de ce
lebrarlos por sí y directamente. Las inscripciones se hacen en el lugar donde se va ejercer
el mandato del poder.
Actos inscribibles:
Otorgamiento de poderes y mandatos (Artículo 2036 del C. C.):
Los instrumentos en que conste el mandato o el poder de un modo general o para ciertos
actos.
Los Instrumentos en que conste la sustitución, modificación extinción del poder o man
dato en su caso.
Cabe indicar que el Art. 2037 de mismo código, fija el lugar de inscripción según donde se
ejerza permanentemente la representación.
Es importante que respecto a este registro se ha establecido como precedente de obser
vancia obligatoria ratificado por el Segundo Pleno del Tribunal, la inscripción de ESCRI
TURAS PUBLICAS IMPERFECTAS.
Sustitución de poder (Art. 157 del C.C.): La sustitución consiste en la delegación que hace
el representante de todas o algunas facultades que ha recibido para ejercer la representa
ción. La sustitución en sí es una facultad.
Si bien en la doctrina existe diferencia conceptual entre la sustitución y la delegación de
poder, nuestro ordenamiento les otorga el mismo tratamiento.
Clases de poder:
PODER ESPECIAL Y PODER GENERAL: Poder general comprende los actos de administra
ción y el poder especial sólo los actos para los cuales ha sido conferido.
