PODER IRREVOCABLE: La regla general es la revocabllidad del poder. Según el Art. 15 3 del
Código Civil: El poder es irrevocable siempre que se estipule para un acto especial o por
tiempo lim itado o cuando es otorgado en interés común del representadoy del represen
tante o de un tercero. El plazo del poder i rrevocable no puede ser mayor de un año.
El registrador al calificar el título en cuyo mérito se solicita la inscripción del poder irrevo
cable, verificará que en el mismo se haya estipulado el acto especial para el cual es otorga
do o el tiempo límite del ejercicio del poder o, en su caso, la circunstancia de que el poder
ha sido otorgado en interés común del representadoy del representante o de un tercero.
Si en el título respectivo no consta de manera expresa el carácter irrevocable del poder ni
fluye con claridad la concurrencia de alguno de los supuestos del artículo 153 del Código
Civil, el Registrador se limitará a inscribir el poder sin la calidad de irrevocable.
El Registrador al extender el asiento de inscripción del poder irrevocable, deberá consig
nar expresamente su carácter irrevocable así como el plazo de su vigencia.
PODERES OTORGADOS EN EL EXTRANJERO (Art. 2 0 9 4 del C.C.): Prescribe que la forma
de los actos jurídicos y de los instrumentos se rige por la ley del lugar en que se otorgan o
por la ley que regula la relación jurídica objeto del acto. Se presentarán en idioma español
o traducidos a éste legalizados conforme a la ley de la materia.
2. Registro de Testamentos: Es una fuente de publicidad de la existencia de los testamen
tos. La inscripción tiene por objeto la publicidad, la impenetrabilidad, la retroactividad,y
la seguridad jurídica de la fe pública registral.
Actos inscribibles:
a. Los Testamentos.
b. Las modificaciones y ampliaciones de los mismos.
c. Las revocaciones del testamentoy de las modificaciones y ampliaciones.
d. Las sentencias ejecutoriadas sobre nulidad, falsedad o caducidad de los testamen-
e. Las sentencias ejecutoriadas en los juicios sobre justificación o contradicción de la
desheredación.
f. Las escrituras revocatorias de la desheredación.
Las inscripciones se hacen en el registro del dom icilio del testadory, además, en el lugar
de ubicación de los inmuebles si se designan en el testamento.
3. Registro de Sucesiones Intestadas: La publicidad de los asientos inscritos en este regis
tro. Se inscriben las sucesiones que no han sido otorgadas por testamento. Es importante
porque permite conocer por la publicidad quienes no han sido considerados en la senten
cia como herederos, para que puedan hacer valer sus derechos.
Sus efectos son publicidad, impenetrabilidad, la retroactividad, la fe pública registral.
Actos inscribibles:
a. Las sentencias ejecutoriadas o partes notariales que ponen fin al proceso no conten-
ciososobresucesión intestada y juicios contra
tos.
