1!. FISCALIZACIÓN DE LAS ACTIVIDADES MINERAS
Mediante Ley N° 28964 se crea el Organismo Supervisor de la Inversión en Energía y Minería
(OSINERGMIN), el cual tiene como misión regular, supervisary fiscalizar, en el ámbito nacio
nal, el cumplim iento de las disposiciones legales y técnicas relacionadas con las actividades
de los subsectores de electricidad, hidrocarburos y minería, así como el cumplim iento de las
normas legales y técnicas referidas a la conservación y protección del medio ambiente en el
desarrollo de dichas actividades. Tiene personería jurídica de derecho público internoy goza
de autonomía funcional, técnica, administrativa, económicay financiera.
El OSINERGMIN financiará las funciones de supervisión y fiscalización de las actividades m i
neras mediante sus recursos propios, los montos pagados por concepto de Arancel de Fiscali
zación Minera y el setenta por ciento (70%) de las multas que se impongan por las infraccio
nes detectadas en los procesos de fiscalización minera.
El Arancel de Fiscalización Minera:
a) Comprende los honorarios de los profesionales que intervienen en las diligencias, los viá
ticos, el margen de utilidad de las Empresas Supervisoras, así como los costos de ensayos
de laboratorio y otros que fueran necesarios para la realización de las acciones de fiscali
zación.
b) Será establecido anualmente mediante resolución del Ministerio de Energíay Minas, pre
vio informe técnico-económico de la Dirección General de Minería. El monto total del
Arancel que corresponda a las actividades de fiscalización de cada unidad será deposita
do por los titulares mineros al inicio del ejercicio anual. El incum plim iento del depósito
del monto anual del Arancel será causal de suspensión de las autorizaciones y certifica
ciones expedidas para la realización de las operaciones mineras.
En el caso de existir indicios de peligro inminente, con la finalidad de proteger la viday salud
de los trabajadores y medio ambiente, el OSINERGMIN puede ordenar la paralización tem po
ral de las actividades en cualquier área de trabajo de la unidad minera. De la misma manera,
levantará la orden de paralización y reanudación de las actividades cuando considere que la
situación de peligro ha sido remediada o solucionada.
III. CONCESIONES MINERAS
La concesión minera es el tipo de concesión más utilizada, resulta ser el medio legal idóneo
para la realización de las actividades mineras, en ese sentido la concesión minera otorga a su
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DESELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1340 of 1506 --

UBILEX
titu lar un derecho real consistente en la suma de los atributos que la Ley reconoce al conce
sionario, las concesiones en principio son irrevocables mientras que su titu la r cumpla con las
obligaciones que se detallarán más adelante.
Debe tomarse especial consideración en que la concesión minera es un inmueble distinto y
separado del predio donde se encuentre ubicada.
Ahora bien, la concesión minera otorga a su titu lar el derecho de explorar y explotar los recur
sos minerales concedidos, que se encuentren dentro de un sólido de profundidad indefinida,
ello se encuentra delimitado por planos verticales correspondientes a los lados de un cua
drado, rectángulo o poligonal cerrada, cuyos vértices están referidos a coordenadas Universal
Transversal Mercator (UTM).
IV. CONTRATOS MINEROS
1. Disposiciones generales
Es el acuerdo entre dos o más partes dirigido a crear, regular, m odificar o exting uir una
relación jurídica patrim onial relacionada con las concesiones mineras o vinculadas con
la minería.
Los contratos mineros constarán en escritura pública y deberán inscribirse en el registro
público de minería, para que surtan efecto frente al Estado y a terceros.
Es el acuerdo de dos o más partes d irigid o a realizar actividades de exploración, explota
ción, beneficio, labor general y transporte de productos minerales respecto a una conce
sión minera, según el tip o de concesión que fuere, a fin de conseguir una u tilid a d o prove
cho de carácter económico a favor de las partes intervinientes en mención, incluyéndose
en esta definición de contrato, todas las formas de exploración y explotación posibles que
pudiera realizarse; en estricto cu m p lim ien to de las normas jurídicas mineras y am bienta
les específicas aplicables, y de las normas civiles, comerciales y empresariales de carácter
general, aplicables a los contratos mineros de manera supletoria537.
El Art. 163o del Texto Único Ordenado de la Ley General de Minería, ordena que los contratos
mineros consten en escritura públicay se inscriba en los Registros Públicos de Minería. Laomi-
sión de la forma establecida e inscripción en el Registro Público de Minería determina que el
contrato minero no surta efectos contra el Estado ni contra terceros. Se exceptúa de las forma
lidades a los contratos que celebren la banca de fomento nacional conforme a lo establecido
en su Ley orgánica.
Esta excepción ha sido establecida para favorecer la ejecución de préstamos mineros en los
que interviene la banca estatal.
2. Caracteres generales de los contratos
Los contratos tienen como principales caracteres:
