a) Su liberalidad, consistente en la atribución de las partes intervinientes de d efin ir si con
tratan o no, y una vez definido el contrato, el establecer de común acuerdo el contenido
del contrato.
b) Su fuerza de ley entre los contratantes, dado que los efectos del contrato celebrado no
pueden invalidarse o declararse ineficaz de manera unilateral por una de las partes, sino
sólo de común acuerdo,y en caso de discrepancia o conflicto mediante la intervención del
juez o de un Árbitro.
b) Su carácter patrimonial, puesto que esencialmente el contrato tiene por fin alida d el
generar, regular, modificar o extinguir una relación jurídica patrimonial, y en el ám bito
minero es más valedero este criterio.
c) El imperativo de la voluntad de las partes, característica que se relaciona con la fuerza
de ley del contrato celebrado entre los contratantes.
Según lo establecido por el Código Civil vigente, son elementos de los Contratos en general
los siguientes:
a) El Consentimiento, puesto que el contrato queda perfeccionado en el m om ento y lugar
en que la aceptación es conocida por el oferente o persona que solicitó inicialm ente a la
otra parte (el aceptante) el pactar el contrato.
b) El Objeto del Contrato, consistente en crear, regular, modificar o extinguir relaciones ju
rídicas; siendo que la obligación que es objeto del contrato debe ser lícita, y la prestación
en que consiste la obligación y el bien que es objeto de ella, deben ser posibles.
c) La Forma del Contrato, por cuanto se presume que la forma que las partes convienen
adoptar anticipadamentey por escrito es requisito indispensable para la validez del acto,
bajo sanción de nulidad.
Adicionalm ente es necesario to m a re n cuenta los requisitos generales de to d o acto ju r íd i
co538 debe poseer para ser válido:
a) Plena capacidad de ejercicio.
b) Objeto Físicayjurídicamente posible.
c) Fin lícito.
d) Observancia de la forma prescrita bajo sanción de nulidad.
