ros es uno de los más usuales en el régimen minero común y está regulado en el Art. 164o de
la Ley General de Minería. Respecto a estos contratos rigen las reglas del derecho común en
toda su amplitud.
Los principios esencialesy típicos de este contrato son los siguientes:
