UBILEX
1. - No hay causa de rescisión contractual de transferencia de derechos mineros por lesión539.
Así, se puede vender una concesión de exploración-explotación por cierto precio en di
nero o signo que lo represente pactado con libre arbitrio. Esta transferencia será firme
y el adquiriente no puede impugnarla por lesión ya que la mina en su potencialidad es
indescifrabley la actividad minera es una actividad aleatoria.
2. - El contrato de transferencia de concesiones mineras deber ser extendido por escritura e
inscrito en el Registro Público de Minería para que surta efectos jurídicos a terceros.
3. - Aunque la concesión minera es indivisible, puede transferirse una parte de ella.
t-
4. - La transferencia de concesiones mineras pueden comprender también las concesiones
de beneficio, de las obras auxiliares de una labor general y las del sistema de transporte
minero conforme al régimen jurídico expuesto en el T.U.O. de la Ley General de Minería.
b) Contrato de Opción.- Art. 165o de la Ley General de Minería dice “por el contrato de opción,
el titu lar de una concesión se obliga, incondicional e irrevocablemente a celebraren el futuro
un contrato definitivo, siempre que el opcionista ejercite su derecho de exigir la conclusión de
este contrato, dentro del plazo estipulado".
El contrato de opción deberá contener todos los elementos y condiciones del contrato defini
tivo, pudiendo pactarse que la opción puede ser ejercitada indistintamente por cualquiera de
las partes.
El contrato de opción minera se celebrará por un plazo no mayor de cinco años, contando a
partirde su suscripción.
Si no se fija el plazo, el Reglamento del Texto Único Ordenado de la Ley General de Minería que
establece sean cinco años computados a partir de la suscripción de la minuta. El contrato de
opción debe contener todos los elementos del contrato definitivo de manera tal que al cele
brar este no haya nada que discutir sino simplemente suscribirlo.
Al contrato de opción se aplican las reglas del derecho común. Además, dichos contratos de
ben ser elevados a Escritura Públicay ser registrados para que sean opuestos a terceros, inclu
yendo al Estado.
c) Contrato de Cesión Minera.- Está regulado en el Art. 166o al 171° del T.U.O. de la Ley General
de Minería.
El cedente podrá entregar su concesión minera, de beneficio, labor general o transporte mine
ro a tercero, percibiendo una compensación.
El cesionario se sustituye por este contrato en todos los derechos y obligaciones que tiene el
cedente.
El contrato de cesión minera es un contrato nominado, bilateral, principal, onerosoy detracto
sucesivo.
En este contrato de cesión minera, el cesionario se sustituye en todos los derechos y obligacio
nes que tiene el cedente sobre las concesiones materia de este contrato.
539 La Lesión se encuentra regulada en los Artículos 9.90y del 1447 al 1456 del Código Civil.
