Temas de M inero
El Art. 169oestablece una prohibición absoluta, es decir si el cesionario que este laborando una
concesión, cualquiera sea esta, no podrá a su vez celebrar un contrato de cesión minera con
terceros sobre dicha concesión. Este Art. 169° equivale a una prohibición a la subcesión de este
contrato.
El contrato de cesión minera podrá ser transferido en su totalidad a tercero, con el consenti
miento expreso del cedente.
Serán causales legales de resolución contractual el incumplimiento del amparo, mediante el
trabajo en la modalidad de la producción de sustancias minerales y la falta de pago del dere
cho de vigencia por año y por hectárea.
d) Contratos accesorios.-
Contrato de Hipoteca Minera.- La hipoteca minera es una garantía real, accesoria e indi
visible constituida sobre una concesión minera inscrita que no deja de estar en posesión
del deudoryque concede al acreedor el derecho de perseguir el derecho minero gravado
en hipoteca en poder de quien se encuentre para hacerlo subastar en el caso de que el
deudor no pague el crédito principal con el fin de que sea cubierto con el producto del
remate, con referencia frente a cualquier otro acreedor.
Características.-
- Es un derecho real minero de garantía que otorga a su titu la r las facultades de persecu
ción y preferencia.
- Es entonces un derecho real de garantía inm obiliario y accesorio.
- Es inscrito en el registro público de Minería.
- La Ley dispone que pueden hipotecarse todas las concesiones reguladas por este régimen
minero común siempre que estén inscritas en el Registro Público de Minería.
- Las partes contratantes tiene el derecho de agrupar en una sola unidad diversas conce
siones que forman un conjunto de bienes unidos dependientes entre sí. Este derecho de
agrupación de concesiones facilita la operación creditoria de constitución de hipotecas
ya que no será necesario constituir varias hipotecas sobre distintas concesiones sino un
solo acto de garantía, si existe esta conexión entre dos bienes inmuebles materia de la
hipoteca minera.
Esta facultad de agrupar varias concesiones tiene efectos procesales para la valorización de
un remate eventual de los bienes hipotecados en caso que el crédito principal no sea pagado.
El Art. 174o faculta al acreedor hipotecario el derecho a inspeccionar el bien hipotecado, y si
este comprueba que la garantía real está desmejorando, es decir, es insuficiente para cubrir el
monto de la deuda, tiene el derecho a exigir una mejora en la garantía.
El acreedor hipotecario tiene conferido un triple derecho sobre las concesiones hipotecarias.
De venta, de persecución y de preferencia de los derechos mineros con esta garantía real.
El acreedor tiene derecho a rematar las concesiones hipotecadas. No es necesaria la tasación
previa de estos derechos si está pactado su valor por las partes que constituyeron esta garantía
real minera. El remate debe ejecutarse en acto público con todas las formalidades de la Ley.
