4. Sociedades y centrales de riesgo com partido
4 .1 . La sociedad minera de responsabilidad lim itada
La sociedad minera de responsabilidad limitada es una persona jurídica de derecho privado
y, por el acto de su constitución, se convierte en único titu lar de la concesión que la originó.
Los socios de las sociedades mineras de responsabilidad lim itada no responden personal-
mente por las obligaciones sociales sino hasta el límite de sus participaciones.
La sociedad minera de responsabilidad limitada será constituida de oficio por el jefe del Re
gistro «Público de Minería.
La sociedad minera de responsabilidad limitada se regirá por lo dispuesto en la Ley General de
M ineríay por el estatuto social que, en su caso, convengan en otorgar los socios.
Las sociedades mineras de responsabilidad limitada podrán ejercer, sin restricción alguna, to
das las actividades mineras dentro y fuera del área en que se encuentre ubicada la concesión
que le dio origen, formulando los petitorios y solicitudes que pudieran ser necesarias para
esos efectos.
La sociedad tomará como denominación la que corresponda a la concesión minera.
En caso que la sociedad fuera titu lar de más de una concesión, la denominación y el domici
lio de la misma será la de la concesión más antigua. Si todas las concesiones hubiesen sido
formuladas en la misma fecha, la denominación y el domicilio, será el de la primera en orden
alfabético.
El plazo de duración de estas sociedades es indefinido.
El capital social se formará mediante aporte de dinero, bienes y/o créditos, rigiendo para los
efectos del aporte lo dispuesto por la Ley General de Sociedades.
El capital estará dividido en participaciones iguales, acumulables e indivisibles, que no podrán
ser representadas en título valores ni denominarse acciones.
Las participaciones confieren a su titu lar legítimo, la calidad de socio y le atribuye, cuando
menos, los siguientes derechos en proporción a sus participaciones:
i) Participaren el reparto de utilidades y en el del patrimonio resultante de la liquidación;
z) Interveniry votaren las juntas generales;
3) Fiscalizar la gestión de los negocios sociales del modo prescrito en la Ley General de So
ciedades.
4) Ser preferido para la suscripción de participaciones en caso de aumento de capital social;
5) Separarse de la sociedad en los casos previstos en la Ley General de Sociedades.
El capital ¡nidal de una sociedad constituida en el acto del petitorio será la suma del valor de
los derechos de denuncio y de inscripción, así como los gastos en que se hubiere incurrido
para form ular el petitorio, los aportes se regirán por lo dispuesto en el artículo anterior.
El dom icilio de la sociedad será el de la ciudad donde se ubique la concesión que le dio origen,
salvo que los socios acordasen cambiar el domicilio.
La sociedad estará administrada por la Junta General de Sociosy la Gerencia.
