4.2. Contrato de riesgo com partido 0 jo in t ventare:
El texto del T.U.O. de la Ley General de Minería, regula el contrato de riesgo compartido o
JOINTVENTURE(Arts. 204,205).
El titu lar de actividad minera podrá realizar contratos de riesgo compartido (joint venture)
para el desarrollo y ejecución de cualesquiera de las actividades mineras.
Este contrato no es una sociedad sino un negocio jurídico ASOCIATIVO para un acto único, por
un plazo indeterminado o determinado en el que las partes aportan bienes o recursos en el
caso fundacional.
La gestión del jo in t venture lo realiza cualquiera de las partes o todas ellas. Las utilidades se
dividen conforme a lo regulado por las partes.
El contrato de riesgo compartido debe constaren escritura pública e inscribirse en el Registro
Público de Minería.
5. Cierre de minas
La legislación peruana cuenta desde la década del noventa con un marco normativo am
biental que busca garantizar un adecuado cuidado del ecosistema al momento de realizar
cualquier actividad minera. Dentro de los componentes de esta legislación se encuentra los
planes de cierre de minas (Ley N° 28090, Ley que Regula el Cierre de Minas y su Reglamento
-D.S. N° 033-2005-EM).
El plan de cierre de minas es un instrumento de gestión ambiental conformado por acciones
técnicas y legales efectuadas por los titulares de actividades mineras. Está desti nado a adoptar
las medidas necesarias antes, durante y después del cierre de operaciones, con la finalidad de
eliminar, m itigary controlar los efectos adversos al área utilizada o perturbada por la actividad
minera, para que ésta alcance características de ecosistema compatible con un ambiente salu
dable, adecuado para el desarrollo biológico y la preservación paisajista.
En este sentido, el plan de cierre de minas deberá describir las medidas de rehabilitación, su
costo, laoportunidady los métodos de control y verificación para las etapas de operación, cie
rre final y post cierre. Asimismo, deberá indicar el monto y plan de constitución de garantías
ambientales exigibles.
El titu la r de la actividad minera que no cuente con el plan de cierre de minas aprobado, está
impedido de iniciar el desarrollo de operaciones mineras.
Ciclo de vida de la m in a .-El aprovechamiento de los recursos mineros pasa por las etapas de
exploración, construcción, operación y cierre. No se avanza a una siguiente etapa hasta no ha
ber culminado la anterior, siendo la última de éstas el cierre definitivo de la mina. Una mina,
además, puede tener varias zonas productivas y diversas actividades dentro de toda su área
geográfica. Cuando una de éstas deja de operar se procede a su cierre, considerándose dicha
acción como un “cierre progresivo”. Así, en paralelo a las etapas del ciclo de vida de la mina se
desarrolla programas progresivos de cierre de la misma.
El cierre de mina se diferencia entre cierre progresivo, que se realiza mientras se desarrollan
las operaciones mineras, y cierre definitivo tendiente a la paralización y cierre final de la ope
ración minera.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1346 of 1506 --

UBILEX
H H | La últim a etapa del ciclo minero comienza cuando se pasa al cierre definitivo de la mina. Du-
rante esta etapa se realizan todas las actividades e inversiones comprometidas para retirar los
componentes minerosy rehabilitar las áreas utilizadas por la operación minera.
Un tema importante a tener en consideración es que, si bien una operación minera puede
encontrarse en etapa de cierre definitivo, la misma puede aun ser económicamentey técnica
mente explotable. Por esta razón, existen casos de minas en etapa de cierre definitivo, o que se
encuentran próximas a entrar en cierre definitivo, que han sido vendidas para ser explotadas
por otro titu la r minero.
Caractérísticas.- El plan de cierre de minas es complementario al Estudio de Impacto Am
biental (EIA) y del Programa de Adecuación y Manejo Ambiental (PAMA). El Plan de Cierre de
Minas deberá describir las medidas de rehabilitación, su costo, la oportunidady los métodos
de control y verificación para las etapas de Operación, Cierre Final y Post Cierre. Asimismo,
deberá indicar el monto y plan de constitución de garantías ambientales exigibles. En el caso
del cierre temporal, progresivo y final se debe contemplar el desmantelamiento de equipos e
instalaciones, estabilización de los residuos y revegetación de la zona. La idea es asegurarque
no quede ningún rastro de la actividad minera que cause impactos negativos posteriores al
cierrey así proteger la vida humanay hacer un uso beneficioso de esas tierras. El plan incluye,
además, el presupuesto del cierre, el cronograma de su ejecución y las garantías respectivas.
Las garantías están constituidas por el costo del cierrey todos los gastos directos e indirectos
que se deriven de ejecutarla. La ejecución se da por incum plim iento del plan, por parte de la
empresa m inera,y son los encargados de fiscal izar el cumplimiento:
a. El Organismo de Evaluación y Fiscalización Am biental (OEFA) y el Organismo Supervisor
de la Inversión en Energíay Minería (OSINERGMIN), para las actividades de la medianay
gran minería;
b. Los Gobiernos Regionales, en las actividades de la pequeña mineríay minería artesanal, a
través de las Gerencias o Direcciones Regionales de Energíay Minas;y
c. La Dirección General de Minería del Ministerio de Energíay Minas para el caso de Lima
Metropolitana.
Estas entidades determinan los montos de la inversión no ejecutada por las medidas de cie
rre incumplidas, y comunican a la Dirección General de Minería o al Gobierno Regional para
que soliciten al titu lar de la actividad minera la constitución de la garantía correspondiente, a
fin de asegurar el debido cumplimiento de dichas medidas sin perjuicio de las sanciones que
pudiesen corresponder.
En el caso de venderse la operación minera, el comprador deberá continuar con la ejecución
progresiva del plan, así como el cierre definitivo y su posterior monitoreo. El monitoreo post
cierre permite verificar el plan de cierre ejecutado.
