L DERECHO A LA SEGURIDAD SOCIAL
El artículo 1o° de la Constitución reconoce: "El derecho universal y progresivo de toda persona a la seguridad
social, para su protección frente a las contingencias que precise la leyy para la elevación de su calidad de vida".
Por su parte, el artículo n ° constitucional, estipula la obligación del Estado de garantizary supervi
sar eficazmente el libre acceso a prestaciones de saludy a pensiones, a través de entidades públi
cas, privadas o mixtas.
