La seguridad social: “Es un sistema institucionalizado de prestaciones individualizadas, ba
sado en la prevención del riesgo y en la redistribución de recursos, con el único propósito de
coadyuvaren lacalidadyel proyecto de vida de la comunidad. Es de reconocerse el fuerte con
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 1347

-- 1348 of 1506 --

UBILEX
tenido axioiógico de la seguridad social, cuyo principio de solidaridad genera que los aportes
de los trabajadores activos sirvan de sustento a los retirados mediante los cobros mensuales
de las pensiones”540.
Su condición de sistema institucionalizado imprescindible para la defensa y desarrollo de
diversos principios y derechos fundamentales, permite reconocer a la seguridad social como
una garantía institucional.
Principios
1. Principio de Universalidad
*-
Universalidad subjetiva: Reconoce que la seguridad social tiene como sujetos de su
protección a todos los individuos, sin limitaciones ni discriminaciones.
Universalidad objetiva: Se refiere a los riesgos sociales o contingencias cubiertas por
la seguridad social. Se postula que la seguridad social tiende a alcanzar la eliminación
total o parcial de todos los daños derivados de una alteración desfavorable del equilibrio
entre necesidades y los ingresos de los individuos, independientemente de la naturale
za diversa de los acontecimientos que le dieron origen.
2. Principio de igualdad e integridad o suficiencia
P de igualdad: la asignación de idéntica protección ante situaciones ¡guales. Ante
unos mismos riesgos toda la población recibirá los mismos beneficios.
P. integridad o suficiencia: las prestaciones deben ser suficientes para atender la contin
gencia social de que se trate.
3. Principio de solidaridad.-
Principio básico o principal. Postula que toda la población contribuye al sostenimiento
del sistema con prescindencia de la calidad de acreedor o no de la prestación.
P de solidaridad general: todos los miembros de la sociedad suministran los medios
necesarios con independencia del interés particular en la obtención de la prestación
yen función a su capacidad contributiva. Se sustenta en:-Obligatoriedad del asegu-
ram iento.-Finalidad redistributiva de la seguridad social.
P desolidaridad entre las generaciones-, postula que cada generación activa proveería a la
tutela de las generaciones pasivas (solidaridad Ínter generacional).
4. Principio de sosten ibil idad financiera.- Los sistemas de seguridad social deben ser viables
financieramente. Progresividad en implementadón y asignación de recursos. Evitar des
equilibrios (déficit).
5. Principio del ahorro nacional y mercado de valores.- Este principio es propio del sistema
privado. De contenido esencialmente económico más que social. Afirm a que el sistema
privado generará la acumulación de capital, aumentará el ahorro nacional, desarrollará
el mercado de valores y diversificará la cartera de inversión, todo lo cual promoverá el
crecimiento, el empleoy mejores pensiones.
