Subsidiaridad.- De parte del Estado.
Neves Mujica precisa que la seguridad social se rige por los principios de: (i) universalidad,
quesigniíica laextensión del ámbito de los beneficiarios a toda persona; (i i) integridad, que le
permite cubrir todas las contingencias sociales mediante acciones de prevención, reparación
y recuperación; (iii) solidaridad, que obliga a todos a cooperar con el cumplim iento de sus
objetivos, abonando la proporcionalidad entre aportes y beneficios; (iv) la unidad en sentido
orgánico y estructural; (v) y 1a internacionalidad referida a la adecuación a un sistema unitario
internacional (Kredsalja Baldo y Ochoa César, Derecho Constitucional Económico, Fondo edi
torial PUCR 2009, p. 579)541.
11. REGÍMENES PEN SIO N A R IO S GENERALES ¥ ESPECIALES:
En la actualidad, el Perú cuenta principalmente con dos regímenes previsionales ordinarios
bien definidos que son: (a) El Sistema Nacional de Pensiones - SNP, cuya norma es el D. S.
N° 354-2020-EFy (c) el Sistema Privado de Pensiones, expresado en el Decreto Supremo N°
054''97''EF, que aprobó el TUO de la Ley del Sistema Privado de Administración de Fondos de
Pensiones.
El primer régimen es administrado exclusivamente por el Estado peruano y forman parte
del sistema público de pensiones, mientras que el segundo es administrado por entidades
privadas, denominadas Administradoras de Fondos de Pensiones-AFPs-, En este panorama,
podemos distinguir en el derecho previsional, dos regímenes generales completamente bien
diferenciados por el sujeto que se encarga de su administración:
i. El Sistem a Privado de Pensiones (SPP), cuya administración está a cargo de empresas
privadas-las AFP-y bajo la supervisión del Estado. Este sistema es del tipo de cap italiza
ción individual, es decir, el trabajador que se afilia a una AFP tiene una cuenta personal
en la que realiza los aportes para su vejez, a lo largo de su vida laboral. El afiliado man
tiene una cuenta individual y los aportes que se realizan en ella únicamente sirven para
calcular su pensión en la AFP a laque pertenezca. Adicionalmente, puede realizar aportes
voluntarios con la finalidad de incrementar el saldo de su cuenta y mejorar su pensión en
el futuro.
Fue creado mediante Decreto Ley 25897, el 28.11.1992. Suobjeto es contribuiral desarrollo
y fortalecimiento del sistema de previsión social en el área de pensiones, estando confor
mado por las Administradoras Privadas de Fondos de Pensiones-AFP, otorgando obliga
toriamente a sus afiliados las prestaciones de jubilación, invalidez, sobrevivenciay gastos
de sepelio.
