Las prestaciones que otorga el SPP, al igual que el SNR se orientan a la cobertura de los
riesgos de: (i) vejez, a través de pensiones de jubilación, (ii) invalidez, a través de pensio
nes de invalidez y, (iii) muerte, mediante pensiones de sobrevivencia y pagos por gastos
de sepelio. A continuación, se detalla cada una de estas prestaciones:
i) Pensión de jubilación
a. Régim en General (Jubilación Legal):
Edad de jubilación: 65 años de edad.
Densidad de aportación: No determinada ya que la pensión se financia con lo
que el afiliado haya acumulado en su CIC, independientemente del número de
años que haya aportado.
Pensión mínima a otorgar: S/. 415 (a partir del 2002, con la Ley N° 27617).
Pensión máxima: No existe.
La jubilación legal del SPP es voluntariay se calcula en base al saldo acumulado
en la CIC más el valor de redención del Bono de Reconocimiento (BdR), de ser
el caso. Esta jubilación, al igual que el resto de prestaciones, puede ser ejerci
da a través de tres modalidades básicas que el trabajador elige libremente al
momento de su retiro. Estas modalidades son: el Retiro Programado, la Renta
Vitalicia Familiary la RentaTemporal con Vitalicia Diferida.
b. Régim en de Jubilación A nticipada O rdinaria:
Edad de jubilación: Antes de los 65 años.
Densidad de aportación: El saldo acumulado en la CIC más el valor de reden
ción del BdR, si fuera el caso, debe ser suficiente para que la pensión calculada
supere el 50% del promedio de la remuneración de los últimos 10 años.
Pensión mínima a otorgar: 50% del promedio de la remuneración de los últimos
10 años.
Pensión máxima: No existe.
Esta jubilación anticipada nace con la creación del SPP y está orientada a aque
llos afiliados que no están en posibilidades de esperar la edad legal de jubila
ción y cuentan con recursos suficientes para autofinanciarse pensiones por lo
menos equivalentes a la mitad de sus remuneraciones percibidas en los últimos
años (tasa de reemplazo del 50%).
c. Pensión Mínima: En atención a la problemática de la inexistencia de una Pen
sión Mínima en el SPP que garantizara que los afiliados perciban un flujo de
ingresos suficiente para cubrir sus necesidades, mediante la Ley N° 27617 de
enero del 2002, se estableció el beneficio de la Pensión Mínima financiada par
cialmente por el Estado a través del Bono Complementario de Pensión Mínima
(BCPM) cumpliendo con los siguientes requisitos:
Edad de jubilación: Como mínimo 65 años y haber nacido a más tardar el 31 de
diciembre d e i9 4 5 -
