Densidad de aportación: 20 años de aportaciones entre el SNPy/o el SPP
Pensión mínima a otorgar: La pensión mínim adel SNP para asegurados con 20
años de aportación (S/. 415).
d. Regímenes Especiales de Jubilación A nticipada: De igual forma, en atención
a la problemática de la ausencia de un régimen especial de jubilación para los
trabajadores que realizan labores que implican riesgo para la vida o salud como
la m ineríay la construcción civil (que si existía en el SNP), en el año 2000, me
diante la Ley N° 27252, se creó al interior del SPP la posibilidad para que este
grupo de afiliados pueda jubilarse anticipadamente bajo un régimen especial,
teniendo en consideración que su envejecimiento se produce de manera más
acelerada como resultado del esfuerzo físico que realizan.
2) Pensión de invalidez
En el SPP un afiliado es inválido cuando tiene una pérdida mayor o igual al 50% de su
capacidad de trabajo. Según su grado, esta pérdida puede ser parcial o total y, según su
naturaleza, temporal o permanente. En cualquier caso, el SPP contempla el derecho de
percepción de una pensión de invalidez si se cumplen los siguientes requisitos:
Requisitos: Habersido evaluado y dictaminado como inválido porel Comité Médico
de las AFP (COMAFP) o el Comité Médico de la SBS (COMEC). La pensión se paga
cuando la pérdida en la capacidad de trabajo supera el 50% y el afiliado no alcanza
la edad requerida para jubilarse. Para el otorgamiento de dicho beneficio, el afiliado
debe solicitar a la AFP la evaluación de su caso, mediante la presentación de una
Solicitud de Evaluación y Calificación de Invalidez.
Pensión a otorgar: Si el trabajador es inválido total (menoscabo superior al 6 6 %):
recibe 70% de las últimas 48 remuneraciones.
Si el afiliado es inválido parcial (menoscabo superior a 50% pero menor a 66%): re
cibe 50% de las últimas 48 remuneraciones.
3) Pensión de sobrevivencia
Estas pensiones se generan con el fallecimiento del afiliado y son pagadas a los be
neficiarios debidamente acreditados:
Beneficiarios: (1) la cónyuge o concubina, (2) los hijos menores de 18 años, o mayo
res d e i8 años pero declarados inválidos y, (3) los padres mayores de 65 años, siempre
que hayan dependido económicamente del afiliado.
Pensión a otorgar: Se considera los siguientes porcentajes de la remuneración men
sual:
42% para el cónyuge o concubino sin hijos;
35% para el cónyuge o concubino con hijos;
14% para los hijos menores d e i8 años, o mayores d e i8 incapacitados de manera
total y permanente para el trabajo;
14% tanto para el padre como la madre, siempre que sean inválidos total o par
cialmente o que tengan más de 60 años y que hayan dependido económica
mente del causante.
