aportes para cada trabajador.
El SNP brinda a las/os aseguradas/os diversos tipos de prestaciones que los adquieren
cuando cumplen ciertas condiciones:
2.1. Prestaciones base de derecho propio. Son las prestaciones básicas que perciben
las/os propias/os afiliadas/os cuando sucede una contingencia.
1. Pensiones de discapacidad para el trabajo: Presentada en el Decreto Ley N°
19990 como pensión de invalidez, se produce cuando sucede una contingencia
sanitaria al afiliado que le genera la pérdida de capacidad para realizar el traba
jo, a pesar de los ajustes razonables que hubiera realizado suem pleador/aen su
centro de trabajo.
Se configura la discapacidad, a partir de dos supuestos: i. El afiliado se encuen
tre en una situación de discapacidad física o mental prolongada o presumida
permanente por la cual queda impedida/o en un 50% o más de su capacidad
de trabajo habitual, ii. Cuando habiendo el afiliado gozado de la pensión de in
validez temporal por impedimento calificado, exista evidencia indubitable que
dicha condición no puede ser revertida, en un porcentaje no menor 50% o más
de su capacidad de trabajo habitual.
La discapacidad para el trabajo se determina con los siguientes documentos: i.
El Certificado Médico de Discapacidad para el trabajo, emitido de acuerdo al De
creto Supremo N °i 66-2005-EF. ii. El Certificado o informe del médico especialis
ta de una de las instituciones prestadoras de salud pública (IPRESS) adscrita al
Seguro Social de Salud (ESSALUD), Ministerio de Salud (MINSA) o una empresa
de prestación desalud (EPS) en tanto dure el estado de emergencia sanitaria de
clarada por la COVID19. iü. Certificado de Calificación de la Discapacidad (CCD)
emitido por la ONR en base a las evaluaciones médicas especializadas realiza
das al solicitante, en las IPRESS del MINSA, ESSALUD o EPS, autorizadas por la
ONP
