III. LEY N0 3 2 1 2 3 “ LEY DE MODERNIZACIÓN DEL SISTEMA PREVISIONAL
Con fecha 24 de setiembre de 2024 se ha publicado la Ley N° 32123 que busca modernizar el
Sistema de Pensiones Peruano, esta ley introduce reformas tanto en el SPP como en el SNR
Este dispositivo a la fecha aun no cuenta con su reglamento, el mismo que será implementado
en un plazo no mayor a 180 días hábiles contados a partir del día siguiente de su publicación
en el diario oficial El Peruano.
Estos son los puntos más importantes que buscan m ayorequidadysostenibilidaden el acceso
a pensiones:
1. Edad de la jubilación: La edad de j ubi lación se fija en 65 años para hombresy mujeres. El
requisito de edad para acceder a una pensión adelantada, anticipada ordinaria o antici
pada por desempleo, cuando corresponda, es a partir de los 55 años, manteniéndose los
demás requisitos establecidos para cada régimen especial.
La ley estipula que la edad de jubilación se revisará cada cinco años, con la primera revi
sión prevista para 2026.
2. Cuentas nocionales: El Poder Ejecutivo implementará de forma progresiva un régimen de
cuotas nocionales fiscalmente sostenible a fin de que cada afiliado del SNP acceda a una
pensión determinada según lo aportado, el cual reemplazaría a las actuales prestaciones
del SNP e incluiría a todas las modalidades de pensiones que otorga.
3. Traslado del SPP al SNP: Ahora será posible que las personas afiliadas del SPP pueden
trasladarse al SNP en cualquier momento, siempre que transfieran el 100% de su CIC de
aportes obligatorios con fin previsional, en función de las unidades de aporte que repre
se nte n^ el valor del Bono de Reconocimiento o el Título de Bono de Reconocimiento, de
ser el caso, libre de aportes voluntarios sin fin previsional.
En el caso de que una persona afiliada al SPP regrese al SNR su pensión se calcula toman
do todos los aportes realizados tanto al SNP como al SPP al momento de la jubilación.
4. Unidad de aporte: La unidad de aporte equivale a un mes de aporte en el sistema. Esta
será definida mediante decreto supremo refrendado por el MEF.
