La unidad de aporte considera, para el trabajador dependiente, los periodos de aporta
ciones en meses, semanas o días que presten o hayan prestado servicios efectivos que
generen la obligación de abonar las aportaciones. En el caso de los aportes del trabajador
independiente y los aportes voluntarios con fin previsional que realice cualquier afilia
