5. Nueva pensión mínima será S/600: Tanto los afiliados a laO NPcom o a las AFP recibirán
una pensión mínima de S/600. Para los aportantes en AFR se requiere al menos 240 apor
tes y no retirar fondos tras la ley. Los jubilados de la ONR que antes recibían S/500, verán
un aumento a S/6 0 0 ; además, sus herederos recibirán S/400 en caso defallecimiento.
6. Aporte por Consumo: El 1% de los consumos realizados con boletas de venta electróni
cas será destinado al fondo de pensiones del contribuyente, con un tope anual de 8 UIT
(S/41,200), lo que equivale a un aporte máximo de S/412 al año.
7. Afiliación obligatoria desde los 18 años: La disposición más criticada es la afñ Nación auto
mática a laONP para quienes cumplen 18 años, a menos que expresen su deseo de unirse
a una AFR
Los trabajadores mayores de 18 años que no estén inscritos en ningún sistema serán auto
máticamente afiliados a una AFP, donde podrán elegir entre bancos, cajas municipales y
fondos de inversión para la administración desús pensiones.
8. Competencia para las AFP: Las AFP ahora competirán con bancos, aseguradoras y otras
instituciones financieras para administrar los fondos de pensiones, buscando mejorar la
rentabilidad para los afiliados.
9. Prohibición del retiro del 95,5% : El retiro del 95,5% de los fondos acumulados en el SPP
al momento de la jubilación será eliminado para los nuevos afiliados y para aquellos me
nores de 40 años. A partir de ahora, solo podrán optar por una pensión vitalicia o progra
mada.
