CASOS PRÁCTICOS DESARROLLADOS
1. La Municipalidad del Rímac les niega a los señores Elio y Galio contraer matrimonio ci
vil. Luego su abogado interpone demanda de amparo alegando discriminación legal en
el Código Civil peruano y discriminación funcional en el municipio. Durante el proceso de
presentan los siguientes argumentos:
Alegato del abogado de la pareja:
Sin modificar el texto del Código Civil y vía interpretación -conforme al bloque de consti-
tucionalidad- debe incluirse la relación de parejas del mismo sexo dentro de la cobertura
normatividad que regula el matrimonio; con el objetivo de satisfacer sus fines subyacen
tes como la protección a la familia y al derecho a contraer nupcias de toda persona sin dis
criminación.
Argumento del juez constitucional:
Primera premisa: Solo y siempre q u e X y Z sean personas de diferente sexo entonces X y Z
tienen derecho a contraer matrimonio en el Perú.
Segunda premisa: Elioy Galio no son personas de diferente sexo (sino del mismo).
Conclusión: Elio y Galio no tienen derecho a contraer matrimonio en el Perú.
En atención al caso y a las reglas de la lógica y de la teoría de la argumentación jurídica, podemos
concluir que:
El alegato del abogado de la pareja se basa en una interpretación extensiva de la normativi-
dad relativa al matrimonio y en el argumento ideológico, pero no tiene fundamento legal
en el ordenamiento jurídico peruano. La Constitución Peruana establece que el m atrim onio
es entre personas de diferente sexo, y el Código Civil peruano no contempla la posibilidad de
matrimonio entre personas del mismo sexo.
La argumentación del juez constitucional es lógica y se basa en las premisas establecidas por la
Constitución y el Código Civil. La primera premisa establece que solo y siempre que X y Z sean
personas de diferente sexo entonces X y Z tienen derecho a contraer matrimonio en el Perú. La
segunda premisa establece que Elioy Galio no son personas de diferente sexo (sino del mismo).
La conclusión lógica es que Elioy Callo no tienen derecho a contraer matrimonio en el Perú.
2. El Sr. Constantino, de 65 años, sin renta alguna, interpone un amparo con el objeto de
que lo incluyan como beneficiario de la pensión de viudez de la que fue su esposa y heroí
na de la guerra del Cenepa, al amparo de la siguiente norma Ni: Las viudas de los héroes
del Cenepa tienen derecho a pensión de viudez. A continuación, se presenta el alegato del
abogado y el argumento del juez constitucional.
Alegato del abogado de Constantino:
La norma Ni comete una inconstitucional idad por omisión al obviar el caso de los viudos, por
lo cual se debe interpretar incluyendo el caso no regulado, puesto que este, como el regulado
tienen una relación de semejanza al pertenecer al mismo género de los cónyuges supérstites. Y
la finalidad de Ni es conjurar la discriminación.
Argumento del juez:
Primera premisa: Si X es viuda de un héroe de la guerra del Cenepa entonces X tiene dere
cho a pensión de viudez.
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DESELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1364 of 1506 --

UBILEX
Segunda premisa: Constantino no es viuda (sino viudo) de un héroe de la guerra del Cenepa.
Conclusión: Constantino no tiene derecho a pensión de Viudez.
En atención al caso y a las regias de la lógica y de la teoría de la argumentación jurídica, se men
ciona que:
El alegato del abogado no realiza argumento analógicoy tampoco teleológico.
El alegato del abogado de Constantino se basa en la ¡dea de que la norma Ni comete una
inconstituclonalidad por omisión al obviar el caso de los viudos. Sin embargo, no presenta un
argumento analógico ni teleológico que justifique la Inclusión de los viudos en la norma. En
lugar cíe eso, simplemente sostiene que la norma debe ser interpretada incluyendo el caso no
regulado, pero no proporciona razones jurídicas consistentes y coherentes para apoyar esta
interpretación.
Por otro lado, el argumento del juez constitucional es lógico y tiene una estructura válida. La
primera premisa establece que si X es viuda de un héroe de la guerra del Cenepa entonces X
tiene derecho a pensión de viudez. La segunda premisa establece que Constantino no es viuda
(sino viudo) de un héroe de la guerra del Cenepa. La conclusión lógica es que Constantino no
tiene derecho a pensión de viudez.
1. Mateo ha nombrado a David como su representante en lasJuntas de Asamblea que ce
lebre una Cooperativa de Crédito. David ha desempeñado muy bien la labor de represen
tación por varios días, sin embargo, considera que dicha labor es riesgosa para su salud,
porque a las] untas de las Asambleas de la Cooperativa asisten muchas personas a un local
con poca ventilación y cuando intervienen los asambleístas para expresar su opinión se
retiran la mascarilla.
Como consecuencia de ello David ha renunciado a la representación comunicando del he
cho a Mateo, que le ha pedido que siga con el encargo hasta que nombre a su reemplazo.
El Gobierno anunció que se terminó el estado de emergencia en el país por el COVID19.
¿David puede apartarse del encargo en forma inmediata?
David para dejar su encargo debe esperar que nombren su reemplazo. En este sentido, David
debe cum plir con su compromiso y no puede apartarse del encargo en forma inmediata. La
renuncia de David es válida solo si se cumple con el proceso de nombramiento de un nuevo
representante.
En relación al mismo caso, ¿cómo debe proceder Mateo ante la renuncia del encargo de
David?
Mateo sabe que David no puede dejarel encargo en forma inmediata. Mateo debe respetarla
renuncia de Davidy no obligarlo a permanecer en el encargo. La renuncia de David es válida
y debe ser aceptada. Por lo tanto, Mateo debe nombrar un reemplazo para el encargo de Da
vid, yaque Davidya no puede cumplir con sus responsabilidades. En ese sentido, Mateo debe
asegurar una transición ordenadaysin interrupciones, para que el reemplazo pueda tomar el
control del encargo y continuar con las tareas asignadas.
