2. Juan es propietario de un inmueble (departamento) en San Isidro y se encuentra trami
tando su visa de residente a España, dado que ha tomado ia decisión de realizar su docto
rado en una importante universidad de Barcelona y paralelamente trabajar en el negocio
de su tío, que radica en dicho país hace años. La forma que ha encontrado de financiar sus
estudios doctorales es vendiendo su inmueble.
En virtud de lo cual, Juan ha puesto a la venta su departamento y con fecha 30 de abril de
2022 suscribe un contrato de compraventa del departamento con Pedro pactándose que el
contrato quedará perfeccionado el día 30 de julio de 2022, fecha en que Juan entregará el
departamento y que Pedro pagará el precio.
Asimismo, con fecha 05 de agosto de 2022, ambas partes suscriben la escritura pública de
compraventa en la Notaría Rojas, la cual se inscribe en Registros Públicos el 15 de agosto
de 2022.
¿Cuándo nace la relación jurídica obligacional?
La relación jurídica obligacional entre Juan y Pedro nace el 30 de abril de 2022, fecha en que
ambos suscribieron el contrato de compraventa del departamento, pactando que el contrato
quedaría perfeccionado el 30 de julio de 2022, cuando Juan entregaría el inmueble y Pedro
pagaría el precio acordado. El Código Civil establece que el contrato es obligatorio en cuanto
se haya perfeccionado, es decir, desde que las partes han acordado la obligación principal,
aunque las prestaciones se cumplan en momentos diferentes (artículo 1352). Asimismo, el
artículo 1361 señala que los contratos son obligatorios en cuanto se haya expresado en ellos.
En relación al mismo caso,¿qué elemento accidental del Acto Jurídico identifica?:
Condición suspensiva.
La condición suspensiva es aquella modalidad o elemento accidental del negocio jurídico que
lim ita la voluntad negocial al someter la producción de los efectos jurídicos a un hecho futuro
e Incierto. En el contrato de compraventa entre Juan y Pedro, se pactó que el contrato quedaría
perfeccionado el 30 de julio de 2022, fecha en que Juan entregaría el departamento y Pedro
pagaría el precio acordado. Por lo tanto, la relación obligacional quedó sujeta a la condición
suspensiva de que llegara la fecha pactada para la entrega del inmueble y el pago del precio.
Según el artículo 1353 del Código Civil peruano, si el contrato está sujeto a condición suspensi
va, los efectos se producirán una vez cumplida la condición.
3. Ernesto es amante del mar y desde pequeño ha practicado el surfcomo deporte acuático,
en base a su esfuerzo y el apoyo de su familia ha llegado a ser parte de la selección peruana,
donde ha tenido diversos premios que enorgullecen a su fam iliayal deporte nacional.
En el cuarto trimestre de 2022, la selección peruana se encuentra compitiendo con países
sudamericanos para clasificar al Mundial de Surfque se llevara a cabo en Australia en fe
brero del 2023. Debido al alto costo de los pasajes y de la estadía Ernesto si desea viajar
deberá vender su vehículo.
En tal virtud, Ernesto en noviembre de 2022 ha suscrito un contrato con Susana donde se
pacta que le venderá su carro Honda Accord del año 2020 a un precio de US $ 20,000 si la
selección peruana clasifica al Mundial de Surf.
¿Qué tipo de contrato han suscrito Ernesto y Susana?
Contrato de compraventa con condición suspensiva. En este contrato, la venta del vehículo
Honda Accord de Ernesto a Susana está supeditada a la condición suspensiva de que la selec-
