H H ción peruana clasifique al Mundial de Surf. Esto significa que la venta del vehículo no se pro-
ducirá hasta que se cumpla esta condición. Mientras tanto, laobligación de vender el vehículo
por parte de Ernesto y la obligación de comprarlo por parte de Susana quedan suspendidas
hasta que se cumpla la condición.
En relación al mismo caso, ¿qué sucede si la selección peruana no clasifica al Mundial de Surf?
Ernesto no tendrá que vender su carro, ni Susana pagar el precio. Si la selección peruana no
clasifica al Mundial de Surf, el contrato de compraventa entre Ernesto y Susana no se perfec
cionará,y por lo tanto, Ernesto notendráque vendersucarro Honda Accorda Susana, ni Susa
na tendrá que pagar el precio de US $ 20,000. En este caso, la condición suspensiva de que la
selección peruana clasifique al Mundial deSurf nose cumplirá, loquesignificaqueel contrato
de compraventa no tendrá efectos jurídicos y las obligaciones pactadas no se harán exigibles.
4. Pedro otorga poder por escritura pública a Roberto para que esta venda un inmueble de pro
piedad del primero, por el precio de Doscientos Mil dólares que debe ser cancelado al contado.
Roberto sin ofrecer el inmueble en el mercado, adquiere el bien para él mismo por la suma de
Doscientos Mil dólares pagando al contado, es decir, interviene en el contrato como represen
tante del vendedory por derecho propio como comprador. Respecto a este acto jurídico:
Este acto jurídico consigo mismo es admisible pues no causa perjuicio al interés del poder
dante, excluyendo toda posibilidad de conflicto de intereses entre las partes.
5. Pedro es hijo único, a la muerte de sus padres heredó muchos bienes inmuebles, entre
ellos su vivienda. Pedro es un ebrio habitual, un día en aparente estado ecuánime vende
su vivienda a Alex. Al enterarse Jaime, como curador de Pedro, le consulta a usted. ¿Cuál es
la consecuencia de dicho acto?
El acto jurídico celebrado por Pedro es anulable porque existe falta de manifestación de volun
tad que el legislador ha considerado como causales de anulabilidad conforme a los artículos
44y 219 del Código Civil. Así tenemos los casos de violencia o intimidación, la manifestación
emitida por los retardados mentales, los toxicómanos, los ebrios, los que adolecen de dete
rioro mental entre otros.
6. Alpha S.A. tiene un contrato de suministro de trigo con la empresa Panificadora S.A. desde
2019 por 5 años, mediante el cual Alpha le suminístralo toneladas de trigo mensuales a Panifi
cadora por un precio de US $ 300 por tonelada; las dos empresas están inscritas en el Perú.
Alpha tiene un contrato de compraventa de trigo con la empresa ucraniana Donbasener-
go desde 2019 mediante el cual le compra la tonelada de trigo a US $ 220. Por efectos de
la guerra entre Rusia y Ucrania, la empresa Donbasenergo ha aumentado el precio de la
tonelada de trigo a US $ 500.
Alpha ha resuelto el contrato con la empresa ucraniana Donbasenergo; sin embargo, en el
mercado mundial el precio de la tonelada de trigo está en US $ 400. Por lo cual se ha visto en
la necesidad de conversar con Panificadora S.A. para subir el precio de tonelada de trigo a US
$ 500. Los directivos de Panificadora consideran que es inaceptable ese precio y si no cumple
con el contrato de suministro la demandarán por indemnización por daños y perjuicios.
¿Qué acciones puede realizar Alpha S.A.?
a. Invocar la cláusula de caso fortuito o fuerza mayor. Alpha puede argumentar que la gue
rra entre Rusia y Ucrania es un caso fortuito o fuerza mayor que ha afectado el precio del
