De conformidad con el artículo 9 del Código Civil Juan puede revocar su acto de disposición.
9. En julio del 2012, Alcides Tudela firmó un contrato de mutuo con Carlos Vásquez, por la
suma de S/. 100 mil nuevos soles, para ser cancelados en tres armadas durante los meses
de agosto, setiembre y octubre. Pasados los meses, Carlos Vásquez no cumplió con la obli
gación pactada en el contrato de mutuo, sin embargo, para eludir su obligación otorgó sus
bienes en anticipo de legítima a su único hijo Marcos Vásquez. Habiéndose enterado de
esa situación, Alcides Tudela requirió el pago a su acreedor, quien alegó no tener dinero ni
tampoco bienes con los que pagar ni garantizar el pago de la obligación pactada. Indique
usted, que pretensión debe postular Alcides Tudela:
Ineficacia del Contrato. La ineficacia del contrato se basa en que Carlos Vásquez no cumplió con
la obligación pactada, lo que viola el artículo 1648 del Código Civil, que establece que el contrato
de mutuo implica la obligación del mutuante de entregar una cantidad determinada de dinero o
bienes a cambio de que se le devuelvan otros de la misma especie, calidad o cantidad.
10. Andrés nació y vivió en Arequipa hasta que cumplió 25 años. Hace seis meses, Andrés se
mudó a la capital, trabaja arduamente en el Callao, como juez, lugar a donde se traslada
diariamente desde el departamento que alquila en la ciudad de Lima a pedido de su espo
sa. A partir de ello, es correcto afirmar que:
En aplicación del artículo 35 del Código Civil Alex posee dos domicilios.
11. Susana Rosas le compra un inmueble a Mariela Zapata por la suma de S/. 50,000. Por la
confianza que se tienen no firman contrato de compraventa alguno, pero si un recibo por
la entrega del dinero, en donde se consigna que es por la venta de un bien. Mariela Zapata
le hace entrega física a Susana del inmueble y esta se muda en forma inmediata con su
familia. Transcurren 15 años y Susana quiere formalizar la propiedad en la que vive, pero
se entera que su amiga ha fallecido hace unos meses, dejando como herederos a sus hijos.
¿Cuál sería la mejor forma de hacer valer sus derechos?
Por medio de un proceso de prescripción adquisitiva de dominio, pues se cumplen los requisi
tos para que sea declarada propietaria por usucapión.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1368 of 1506 --

12. Mario y Roberto suscriben un contrato en v irtu d del cual Roberto reconoce adeudar a
Mario la suma de US$ 50,000,00, obligándose a pagar dicha deuda en cuotas mensuales de
ÜS$ 5,000.00. Asimismo, en garantía del pago d e la d e u d a antes indicada, J u lio constituye
una hipoteca sobre su casa a favor de Mario. Posteriormente, Mario suscribe un contrato
de cesión de derechos con Samuel por el cual le cede el derecho de crédito que tiene con
Roberto. Samuel, en su calidad de cesionario, interpone una demanda de ejecución de hi
poteca contra Julio por el no pago los US$ 50,000.00. Julio formula contradicción al man
dato de ejecución alegando la inexigibilidad de la obligación, toda vez que conforme a lo
dispuesto en el artículo 1439 del Código Civil, al no haber manifestado su conformidad con
la cesión, la hipoteca no ha pasado a favor del cesionario demandante. La sentencia de pri
mera instancia declara fundada la contradicción y la improcedencia de la demanda, pues
considera que conforme al artículo 1439 del Código Civil el tercero garante hipotecario de
bió manifestar su conformidad con la cesión. Contra dicha sentencia Samuel interpone re
curso de apelación alegando que el acto jurídico celebrado es una cesión de derechos y no
una cesión de posición contractual, por lo que la norma aplicable es el artículo 1206 y 1211
del Código Civil y no el artículo 1439. La Corte Superior confirma la sentencia de primera
instancia reproduciendo los fundamentos expuestos por el juez en su sentencia. ¿Cuál es
la causal casatoria en la que Samuel debe sustentar su recurso de casación?
La aplicación indebida de una norma de derecho material.
La causal casatoria en la que Samuel debe sustentar su recurso de casación es la aplicación
indebida de una norma de derecho material. Samuel argumenta que la sentencia de primera
instancia y la Corte Superior aplicaron incorrectamente el artículo 1439 del Código Civil, que
se refiere a la cesión de posición contractual, cuando en realidad se trató de una cesión de
derechos. Samuel sostiene que la norma aplicable es el artículo 1206 y 1211 del Código Civil,
que se refieren a la cesión de derechos. Por lo tanto, Samuel debe demostrar que la aplicación
del artículo 1439 fue indebida y que el artículo 1206 y 1211 son los que debieron ser aplicados
en este caso.
13. Juan, Pedro y Felipe se han obligado solidaria e indivisiblemente a pagar la suma de S/.
900,000.00 (Novecientos mil y 00/100 nuevos soles). Si Pedro fallece dejando como here
deros a sus tres hijos, cómo responderán estos por la deuda de Pedro?
Cada uno de los hijos de Pedro debe pagar la suma de S/. 900,000 (Novecientos mil y 00/100
nuevos soles) pues la indivisibilidad se transmite a los herederos.
14. Juan le pide prestada a Felipe una tablet que éste se ha comprado hace algunos días
prometiéndole que solo la usará por unas horas. Sin embargo, luego de que Felipe acepta
realizar el préstamo, Juan vendey realiza la tradición del hermoso aparato a Javier quien la
recibe sin sospechar que Juan no es el dueño, entonces podemos decir que:
Javier ha adquirido la propiedad del bien pues ha recibido la posesión a título oneroso y de
buena fe.
