que el automóvil de Hamilton es el carro que soñó toda su vida. Por ello, a través de una carta
notarial remite una oferta de compra del automóvil por $ 8,000.00, estipulando que Santos
entenderá que Hamilton aceptó la oferta si es que éste no responde dicha carta en 15 días na-
