CASOS PRÁCTICOS DESARROLLADOS
Surales. HamSSton n o contestó dicha caita en al plazo indicado. Luego de los tres meses acude
a Sa casa de Santos)/ le solicita recoger el automóvil, a lo cual Santos se niega sosteniendo que
ellos celebraron un contrato de compraventa. De lo expuesto, es correcto afirmar que:
En este caso no existe contrato de compraventa puesto que no existe ley ni acuerdo entre am
