16. María dueña de una gran cantidad de terrenos cafeteros se obliga frente a la empresa
Cafetal a entregar cierta cantidad de café de manera mensual. A cambio recibe la suma de
US$ 3,000.00 mensuales.
La obligación a cargo de María resulta ser inválida, debido a que no está individualizada por lo
menos en su cantidady calidad.
17. Jorge constituyó hipoteca a favor de Braulio sobre un inmueble, ubicado en la Calle Nro.
A, de un área de 200 mz, inscrita en la Ficha Registral Nro.1021; sin embargo, en realidad el
inmueble tiene un área 220 m2, conforme aparece en los Registros Públicos. Asimismo, la
hipoteca fue constituida para garantizar obligaciones futuras.
El acto jurídico de constitución de hipoteca es válido, por cuanto el mandato contenido en el
artículo 1100o del Código Civil Impone que dicho objeto sea específicamente determinado,
debiendo entenderse que la individualización consiste en su especificación al punto de que
sea posible identificarlo entre el conjunto de bienes de especie similar; tal individualización
supone qué bien va a ser afectado por el derecho de hipoteca, en qué medida, o de ser el caso,
hasta porqué monto.
18. Rosa es representante de Roxana. Roxana al conferirle el poder de representación ha
establecido con toda precisión cuál es el contenido del contrato que ella debe celebrar con
Marcos y ha identificado plenamente el bien objeto de la transferencia. Al momento de
suscribir el contrato en representación de Roxana, Rosa, es engañada por Marcos respecto
del estado del bien que adquirirá, sin embargo, al momento de suscribir el contrato Rosa
lo hace en los mismos términos en los que Roxana había instruido que lo haga. A pesar
de ello, Roxana solicita la anulabilidad de ese contrato. Usted como juez, cómo resolvería:
Se debe declarar infundada la demanda porque el acto jurídico es anulable si la voluntad del
representante hubiere sido viciada. Pero cuando el contenido del acto jurídico fuese total o
parcialmente determinado, de modo previo, por el representado, el acto es anulable solamen
te si la voluntad de éste fuere viciada respecto de dicho contenido.
19. Thiago se encuentra en el Estado de Florida en la ciudad de Miami y su hermano que es
residente le informa que en las tiendas de aparatos electrónicos a veces tienen excelentes
ofertas. En tal sentido, Thiago visita una tienda de artículos electrónicos. En la tienda ob
serva que las PC marca Dell están en oferta y decide comprar una Personal Computer (PC)
marca Dell, con Intel CORE 17.
De regreso a Lima al probar la PC se da cuenta que el teclado no tiene la letra “Ñ” y para
escribir esa letra tiene que configurar el teclado, lo cual le molesta y dificulta.
Thiago decide hacer el reclamo de cambio de PC ante el representante de la marca Dell en
Lima. En dicho local los teclados sí tienen la letra “Ñ”. Dicho representante tiene la misma
PC marca Dell, pero al doble del precio en que Thiago compró la PC en USA.
En este caso ¿cuándo el error es esencial?
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1370 of 1506 --

UBILEX
Cuando recae sobre una cualidad del objeto que resulta importante paraThiago.
En este caso, el error se refiere a la ausencia de la letra “Ñ” en el teclado de la PC marca Dell
comprada por Thiago en Estados Unidos. La letra “Ñ” es una característica importante para
Thiago, ya que es un elemento fundamental para su comunicación y escritura en español. La
ausencia de esta letra en el teclado originalmente comprado porThiago en Estados Unidosy
su presencia en el teclado de la PC marca Dell en Lima, donde se realizó el reclamo, indica que
el error es esencial,ya que afecta directamente a una característica importante paraThiago.
