24. Mario le otorga a Javier un poder por escritura pública con facultades generales, seña
lándose expresamente la facultad de “Transferir bienes, celebrar transacciones y concilia
ciones, así como para realizar cualquier acto procesal”. Javier, en representación de Mario,
demanda a Martín por resolución de contrato. Es correcto indicar que:
Javier carece de representación para demandar. El ordenamiento establece que el poder debe
contener expresamente las facultades de representación que se desean conferir, incluyendo la
facultad de interponer demanda. Por lo tanto, Javier no tiene la representación legal necesaria
para demandar en nombre de Mario.
