CASOS PRÁCTICOS DESARROLLADOS
vier acude al Juez a solicitarle que disponga ia resolución del contrato por incumplimiento.
¿Cómo resuelve el Juez?
Declara improcedente la demanda porque la resolución del contrato ya operó automática
mente, razón por la cual no es necesario que el Juez lo ordene, salvo que se le hubiera pedido
