26. Alpha S.A. tiene un contrato de suministro de trigo con la empresa Paníficadora S.A. desde
2019 por 5 años, mediante el cual Alpha le suminístralo toneladas de trigo mensuales a Panífi-
cadora por un precio de US $ 300 por tonelada; las dos empresas están inscritas en el Perú.
Alpha tiene un contrato de compraventa de trigo con la empresa ucraniana Donbasener-
go desde 2019 mediante el cual le compra la tonelada de trigo a US $ 220. Por efectos de
la guerra entre Rusia y Ucrania, la empresa Donbasenergo ha aumentado el precio de la
tonelada de trigo a US $ 500.
Alpha ha resuelto el contrato con la empresa ucraniana Donbasenergo; sin embargo, en el
mercado mundial el precio de la tonelada de trigo está en US $ 400. Por lo cual se ha visto en
la necesidad de conversar con Paníficadora S.A. para subir el precio de tonelada de trigo a US
$ 500. Los directivos de Paníficadora consideran que es inaceptable ese precio y si no cumple
con el contrato de suministro la demandaran por indemnización por daños y perjuicios.
¿Qué acciones puede realizar Alpha S.A.?
Pedir la resolución del contrato por excesiva onerosidad de la prestación.
La excesiva onerosidad de la prestación es aplicable en los contratos conmutativos de ejecu
ción continuada, periódica o diferida según el Código Civil Peruano (artículo 1440).
En este caso, Alpha S.A. puede argumentar que el aumento del precio de la tonelada de trigo
a US $ 500 es excesivamente oneroso y que no puede cum plir con el contrato de suministro a
ese precio. Al solicitar la resolución del contrato, Alpha S.A. estaría protegiendo sus intereses
yevitando la posibilidad de ser demandada por Indemnización pordañosy perjuicios por no
cumplir con el contrato de suministro a ese precio.
