temer que pueda vivir en Europa. Luego de conversar con sus amigos que viven en Europa,
Marión decide vender su departamento y suscribe un contrato de compraventa con Javier,
un amigo desde la infancia, pactando que, si Marión regresa dentro de un año de celebrado
el contrato, este se resuelve. Así Marlon se asegura que si no se acostumbra al frió de Euro
pa regresará al país y podrá seguir viviendo en su departamento.
Marión regresa al país al cabo de ocho meses de suscrito el contrato. ¿Qué acción es legal
mente posible?
