Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1372 of 1506 --

UBILEX
Javier devuelve el departamentoy Marión devuelve el precio pagado. (Marión y Javier han sus
crito un Contrato de compraventa con condición resolutoria).
Debido a que a condición resolutoria pactada fue que, si Marión regresaba al Perú dentro del
año siguiente a la celebración del contrato, este se resolvería. Marión regresó a los ocho meses,
cumpliéndose la condición. Por lo tanto, el contrato se resuelve de pleno derecho, debiendo
Javier devolver el departamento a Marión y Marión devolver el precio pagado por Javier. Esto
se fundamenta en el artículo 1371 del Código Civil peruano, que establece que la resolución
deja sin efecto un contrato válido por causal sobreviniente a su celebración.
29. Pedro se dirige al banco BBAA acompañado de Juan para pedir un préstamo personal
por S /10,000. En el local del BBAA, Pedro conversa con Ernesto, Jefe de Banca Personal,
quien anota en su computadora los datos del préstamo que solicita, el cual se compromete
a pagar en 11 cuotas mensuales de S/1,000 soles cada uno incluyendo intereses.
Ernesto toma nota de lo solicitadoy le solicita a Pedro un fiador como garante de pago, se
ñalando que es su amigo Juan. Anotado todos los datos del préstamo, le pide a Pedro que
vaya a ventanilla para recabar sus S/10,000. Posteriormente, Pedro le agradece a Juan que
aceptó ser su fiador. Juan se mortifica y le dice que no ha firmado nada y Pedro le dice que
él tampoco ha firmado ningún contrato.
A los tres meses de otorgado el préstamo, el BBAA se comunica con Juan para que pague las
dos primeras cuotas del préstamo como fiador porque Pedro no ha cumplido con dicho pago.
¿El acto celebrado entre Pedro y el BBAA que características tiene?
No es un contrato AD PROBATIONEM: Un contrato AD PROBATIONEM es aquel que se celebra
sin cumplir con los requisitos formales de un contrato, pero que puede ser considerado como
contrato si se cumple con los requisitos de la buena fe y la justicia. En este caso, no se cumplió
con la formalidad contractual, por lo que no se puede considerar un contrato AD PROBATIO-
NEM. Asimismo, tampoco es un contrato por cuanto Ernesto, el Jefe de Banca Personal, no
firm ó un contrato con Pedro. Aunque anotó los datos del préstamo en su computadora, no se
cumplió el requisito de la formalidad contractual.
¿Cuál es la situación legal de Juan en el presente caso?
Juan legalmente no es el fiadorde Pedro, aunque Ernesto le pidió a Pedro que nombrara ajuan
como fiador, Juan no firm ó ningún documento ni aceptó ser fiador. Por lo tanto, no hay un
vínculo legal e n tre ju a n ye l préstamo, y Juan no tiene obligaciones como fiador.
