do en S/. 15,000.00 soles. Jerónimo acepta y toma posesión del bien.
En virtud del artículo 906 del Código Civil Jerónimo sería un poseedor ilegítimo de buena fe,
siempre y cuando no tenga conocimiento que la donación de un inmueble es un acto jurídico
