32. Emilia es una ciudadana argentina que vive en el Perú que es muy emotiva y le gusta mucho
el football, asimismo administra un instituto para adolescentes con problemas de conducta.
Para el mundial de Qatar 2022 ha mandado colocar una TV de 60 pulgadas para que todos
los jóvenes puedan visualizar el mundial de football. Emilia se puso muy triste cuando Ar
gentina perdió su primer partido con Arabia Saudita. La prensa argentina ha criticado el
accionar de su selección después del primer partido.
Sorprendentemente, Argentina ha ¡do ganando todos sus partidos y ha quedado finalista
frente a Francia que tiene una gran selección. ES domingo 18 de diciembre de 2022 es la
fecha en que se jugó la final, y Argentina luego de ir ganando le empataron el partido y
tuvieron que pasar a penales para definir al campeón. Emilia antes de los penales les dice
a los jóvenes que si Argentina campeona ella dona su carro al instituto valorizado en US §
20,000. Argentina es campeona de Qatar 2022.
Han pasado algunas semanas y Em ilia no ha cumplido con su ofrecimiento de donar su
vehículo al instituto.
El instituto no tiene forma de exigir la supuesta donación. Ya que para que exista una dona
ción se requiere que se haga por escrito de fecha cierta. Aunque Emilia prometió donar su
carro al instituto si Argentina ganaba el Mundial, no cumplió con su ofrecimiento. La promesa
no se convirtió en una donación efectiva debido a que no se realizó por escrito de fecha cierta,
como establece el art. 1624 del Código Civil Peruano.
33. Ricardo Valenciatiene una deuda de cien (100) mil dólares con Adolfo Pazos, quien le ha
dicho que si no le paga iniciará un proceso y embargará su casa para poder rematarla y co
brarse la deuda con el producto del remate. Ante ello, Ricardo Valencia aparenta celebrar
un contrato con su cuñado Betito sin tener voluntad para celebrarlo, para que este último
sea el propietario registral y no se pueda embargar su casa. Betito no paga absolutamente
nada por el bien y Ricardo Valencia continúa usándola sin restricción alguna. Es correcto
indicar que:
El contrato celebrado entre Ricardoy Betito es nulo por simulación absoluta.
34. Camino a su trabajo, Juan Fernández, cuando cruzaba la calle en la esquina por el cru
cero peatonal, es atropellado por un vehículo particular que iba a una velocidad no permi
tida en la zona. Como consecuencia de las heridas, se le ordena reposo absoluto, lo que da
lugar a que sea despedido de su trabajo. Tanto la persona que conducía el vehículo, como el
propietario, se niegan a darle reparación alguna, pues indican que con el pago de la indem
nización otorgada por el SOATya cumplieron con su obligación. Ante ello Juan Fernández,
en la vía civil interpone una demanda de indemnización por daños y perjuicios por daño
emergente, lucro cesante y daño moral contra el propietario del vehículo, el conductor y su
empleador (por haberlo despedido). El proceso debe resolverse:
Declarar fundada la demanda respecto del conductory del propietario del vehículo, pues por
tratarse de una actividad riesgosa, es un supuesto de responsabilidad objetiva.
