UBILEX
35„ Richard contrató a Angelito como seguridad personal Al cabo de unos meses, Richard
decide viajar fuera del país y encarga a Angelito el cuidado de su vivienda, señalando que
regresaría en 15 meses. Al cabo de los 15 meses, Richard le comunica a Angelito que residirá
un tiempo mayor en el extranjero, pero que desea que Angelito siga cuidando la casa, mo
tivo por eS cual permanentemente envía dinero para los gastos y otros. Al cabo de 6 años,
Richard retorna a Perú, pero Angelito se niega a devolverle la vivienda, sosteniendo que
ha operado la prescripción adquisitiva a su favor. A partir de ello, es correcto afirm ar que:
Conforme al artículo 905 del Código Civil “es poseedor inmediato el poseedor temporal en vir
tud de un título". Así, Angelito viene a ser un poseedor inm ediatoy de acuerdo a la presunción
de propiedad dispuesta en el artículo 912 del Código Civil. Éste no puede adquirir la propiedad
de la vivienda ni podrá hacerlo puesto que es poseedor inmediato, al estar en ella por encargo
de Richard, quien es el poseedor mediato.
36. El Consorcio formado por las empresas Luna, Sol y Sombra se obligan a construir un
edificio de cinco pisos a favor del Hotel Caribe. La obra debía ser entregada el 5 de agosto
del 2012. Pero sucede que el mencionado Consorcio no entrega la obra en plazo pactado.
¿Cómo tendría que responder el Consorcio frente al Hotel Caribe?
El Consorcio al no ser una persona jurídica, los miembros que la integran son los que responden
de manera solidaria frente al Hotel Caribe, siempre que dicha solidaridad se haya pactado.
37. Pablo, ciegomudo, mayor de edad, interpone directamente una demanda de indemni
zación presentando demanda con su huella y con la firma e identificación de un testigo a
ruego. ¿Qué resuelve el juez?
Debe adm itir a trámite la demanda, pues no existe causal de Improcedencia dispuesta en el
artículo 427 del Código Procesal Civil, ya que Juan no es un Incapaz absoluto, su condición de
ciegomudo no impide que pueda expresar su voluntad de manera indubitable.
38. José se obliga a entregar una computadora portátil a favor de Marco el día 5 de agosto
del 2012. Un día antes de la entrega ocurre un terremoto destruyendo la casa de José y por
ende la computadora portátil. ¿Qué sucede con la obligación?
La obligación queda resuelta sin derecho a contraprestación, es de aplicación la teoría del pe-
riculum estdebitoñs.
39. José y Josefa tienen dos hijos a los que han dado una instrucción en los mejores colegios y
universidades. Desean vivir un retiro tranquilo. Reúnen a sus hijos, Pepita y Pepe, y les indi
can que han decidido darle a ella la casa de playa en Asiaya él el departamento en San Borja,
como anticipo de legítima en el que deben intervenir ellos. La hija no está de acuerdo. Cree
injusta la distribución. Los padres insisten en esta decisión y ella limita sus visitas a casa de
los padres, así como la de sus hijos que son la adoración de los abuelos. Comienza un aleja
miento de ellos cada vez más notorio hasta que no cambien su decisión en el reparto de los
bienes. Los abuelos se sienten muy dolidos por esta actitud y extrañados, ya que no espera
ban una reacción de esta naturaleza. Uno de ellos piensa que la actitud de su hija violenta sus
legítimos derechos como abuelos y ambos se sienten realmente afectados.
¿Es posible que la hija pueda formular una oposición legal a la decisión de sus padres en el
anticipo de herencia?
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1375 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
El anticipo de legítima es un derecho de los padres que no admite oposición de los benefi
ciarios. Los padres tienen la facultad de disponer de sus bienes en vida, siempre y cuando no
afecten la legítima de sus hijos y otros herederos forzosos. En este caso, los padres han deci
dido darle a Josefa la casa de playa y a José el departamento en San Borja como anticipo de
legítima, lo que es un derecho que les corresponde como padres. La hija no puede oponerse a
esta decisión, ya que no tiene derecho a interferir en la disposición de los bienes desús padres.
40. Alpha S.A. tiene un contrato de suministro de trigo con la empresa Panifkadora S.A.
desde 2019 por 5 años, mediante el cual Alpha le suminístralo toneladas de trigo mensua
les a Panifkadora por un precio de US $ 300 por tonelada; las dos empresas están inscritas
en el Perú.
Alpha tiene un contrato de compraventa de trigo con la empresa ucraniana Donbasener-
go desde 2019 mediante el cual le compra la tonelada de trigo a US $ 220. Por efectos de
la guerra entre Rusia y Ucrania, la empresa Donbasenergo ha aumentado el precio de la
tonelada de trigo a US $ 500.
Alpha ha resuelto el contrato con la empresa ucraniana Donbasenergo; sin embargo, en
el mercado mundial el precio de la tonelada de trigo está en US § 400. Por lo cual se ha
visto en la necesidad de conversar con Panifkadora S.A. para subirel precio de tonelada de
trigo a US $ soo. Los directivos de Panifkadora consideran que es inaceptable ese precio y
si no cumple con el contrato de suministro la demandarán por indemnización por daños y
perjuicios.
¿Qué acciones puede realizar Alpha S.A.?
Pedir la nulidad del contrato por objeto física y jurídicamente imposible. La nulidad del con
trato por objeto física y jurídicamente imposible se aplica cuando el objeto del contrato es
física y jurídicamente imposible de cumplir, como, por ejemplo, un contrato de venta de un
objeto que no existe. En este caso, el objeto del contrato de suministro de trigo es posible de
cumplir,ya que Alpha S.A. puede sum inistrartrigo a Panificadora S.A. a un precio razonable.
41. La Superintendencia de Bienes Nacionales (SBN) ha convocado a subasta pública para
vender ocho bienes nacionales. Enzo que tiene el cargo de Ministro de Estado conoce bien
las características de dichos bienes nacionalesyestá interesado en comprar cuatro de ellos.
Para tal efecto, se pone de acuerdo con su amigo Adrián para que él se presente a la subas
ta pública y pague el precio de cuatro bienes nacionales.
Adrián se presenta a la subasta y oferta por los cuatro bienes nacionales y laSBN le otorga
la buena pro de dos bienes nacionales. Pasado algunos meses, Enzo renuncia el cargo de
Ministro de Estado y Adrián le vende los dos bienes nacionales con un incremento del 5 %
del precio ofertado en la subasta.
¿Cómo describiría el caso planteado?
Se trata de un fraude a la ley. Enzo, que tiene el cargo de Ministro de Estado, conoce bien
las características de los bienes nacionales y está interesado en comprar cuatro de ellos. Sin
embargo, en lugar de presentarse él mismo a la subasta pública, se pone de acuerdo con su
amigo Adrián para que él se presente y pague el precio de los bienes nacionales. Adrián se
presenta a la subastay obtiene la buena pro de dos bienes nacionales.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1376 of 1506 --

UBILEX
En relación al mismo caso, ¿qué afism adón es incorrecta?
Se debe probar la finalidad de eludir la norma defraudada. En realidad, el fraude a la ley se
produce cuando se utiliza una norma jurídica como cobertura para eludir otra norma que se
pretende aplicar. En este caso, Enzo y Adrián utilizaron la norma de la subasta pública para
comprar los bienes nacionales, pero con el fin de evitar la aplicación de las normas que regu
lan la adquisición de bienes nacionales por parte de los funcionarios públicos. Por lo tanto, no
se debe probar la finalidad de eludir la norma defraudada, sino que se debe demostrar que
se utilizó una norma jurídica como cobertura para eludir otra norma que se pretende aplicar.
42. Alberto nunca se casó ni convivió con alguien, no tuvo hijos y su única familia son sus
hermanas Amelia con la que no congenia mucho y Beatriz con la que se lleva bien y vive
en París. Al detectársele una enfermedad terminal medita profundamente y otorga testa
mento ológrafo de puño y letra en el que deja bienes a algunos amigos, pero la mayor parte
a Beatriz. Al fallecer Alberto, Beatriz retornó para el entierro y al encontrar el testamento
en el ropero se lo comunicó a Amelia, quien en un acto de ira lo rompe ya que conseguiría
que con la sucesión intestada a ella también se le declare heredera. El abogado al que con
sulta Beatriz le dice que se puede denunciar a Amelia por violencia familiar y excluirla de
la herencia por la censurable destrucción del testamento ológrafo. Al final Beatriz se vería
favorecida porque quedaría como única heredera.
¿Qué repercusión negativa tendría en Amelia la destrucción del testamento ológrafo de
su hermano?
Ser excluida de la sucesión de su hermano Alfonso.
El acto de destrucción del testamento ológrafo acarrea la indignidad de Amelia en la sucesión
de su hermano.
La destrucción del testamento ológrafo de Alberto por parte de Amelia tendría como conse
cuencia que Amelia sea excluida de la sucesión de su hermano. Esto se debe a que el testa
mento ológrafo es el documento que establece la voluntad del testador en cuanto a la distri
bución de sus bienes después de su fallecimiento. Al destruir el testamento, Amelia impide
que se cumplan las disposiciones testamentarias de Alberto, lo que significa que no podrá
heredar según lo establecido en el testamento.
En el ordenamiento jurídico peruano, el Código Civil establece que el testamento es un nego
cio jurídico que permite al testador manifestar su voluntad en cuanto a la distribución de sus
bienes después de su muerte. El testamento ológrafo, en particular, es un tipo de testamento
en el que el testador escribe personalmente el documento, lo que requiere una mayor capaci
dad y autenticidad del testador.
43. TELEPE es una empresa de servicios de telecomunicación, a quien se le ha otorgado la
concesión única para la prestación de servicios públicos, por el plazo de 20 años. Para cum-
plircon sus fines, la empresa necesita instalar antenas e infraestructura en diversas zonas
del territorio peruano.
En la región Cusco, TELEPE identificó un área denominada Amapola que le pertenecía a la
Municipalidad del Cusco, por lo que el concesionario presentó la documentación para so
licitar la “Autorización para la instalación de infraestructura de telecomunicaciones, tal y
como lo dispone su Texto Único de Procedimientos Administrativos-TUPA. Sin embargo,
la municipalidad denegó la solicitud de la empresa, aduciendo que la antena era un riesgo
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1377 of 1506 --

CMOS PRÁCTICOS DESARROLLADOS
para la salyd de los vednos., Ante esla negativa, ensoriilró otro terserio muy cerca, que le
pertenecía a Luis Alcázar, Ambas partes suscsiben un corstrtto, por el que se permitía ¡a
in s t a l a c ió n de la antena.
¿Cuál es la naturaleza del área denominada “Amapola"?
La naturaleza del área denominada “Amapola” es un bien de dom inio público natural. Esto se
debe a que la Municipalidad del Cusco es la titu lar del dom inio público natural, que incluye
los espacios naturales y los recursos naturales que no están sujetos a la propiedad privada.
¿Qué tipo de contrato se ha establecido entre la empresa y el señor Luis?
Dicho contrato se configura como una servidumbre convencional, ya que las partes en mé
rito a su autonomía privada constituyen una servidumbre. Una servidumbre es un derecho
real que permite a una persona utilizar un bien ajeno, siempre y cuando se cumplan ciertas
condiciones y se respeten los derechos del propietario del bien. En este caso, el contrato entre
TELEPE y Luis Alcázar permite a la empresa instalar la antena en el terreno de Luis Alcázar, lo
que se considera una servidumbre convencional.
4 4 4 . Tadeo fallece repentinamente muy joven dejando viuda a Josefina y a su hijo Renzo
de 5 años. En su herencia se incluyen dos casas pequeñas que eran bienes propios porque
él las tiene de su familia, un departamento en una exclusiva zona de Lima que está desocu
pado y una cuenta corriente cuyo saldo a su muerte es de $55,000. Además, había tomado
un seguro de vida particular con una cobertura de $300,000.00 con su hijo como benefi
ciario. Una vez que comienza a superar la dolorosa realidad de no tener más a su esposo,
debe ordenar el aspecto patrimonial que pasa por determinar qué hacer con los bienes en
provecho sobre todo de su hijo que está próximo a pasar del nido al colegio en el que debe
asumir el pago de una pensión que no baja de S/2,500.00 mensuales. Su dilema está en
vender o arrendar los bienes.
¿Cómo se desenvuelve la patria potestad en cuanto a los bienes que hereda su hijo?
Josefina no necesita autorización judicial para invertirel dinerodesu hijo menoren lacompra
de un departamento en Lima.
1. Carmela, estudiante de derecho, siempre se sintió extrañada que nuestra Ley indicara
que la promesa de contraer matrimonio no obligara a los promitentes. Pensaba no haber
razón para que una Ley contradictoriamente señalara no tener obligatoriedad. Paul, su
enamorado de siempre, le pidió matrimonio con la tradicional pedida de mano en casa de
ella, en presencia de los padres de ambos y recepción incluida. El matrimonio sería en un
año. Ya habían separado la iglesia, planeado la recepción para 200 personas y contratado
el servicio de catering a razón de $50 por cada una, pagando el papá de ella el 7 0 % porque
el saldo correría a cargo de Paul, pero 4 meses antes de la boda este último decide cance
larla. En medio de su inmadurez, sentía la presión económicay emocional del compromiso
y, peor cuando se supo que Carmela estaba con un mes de embarazo.
¿Qué efecto legal tiene esta promesa matrimonial entre Carmela y Paul?
No genera obligación legal de contraerlo ni de ajustarse a lo estipulado, empero si se ocasio
nan daños y perjuicios al otro o a terceros, quien lo genera estará obligado a indemnizarlos.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 1377

-- 1378 of 1506 --

UBILEX
Esto se basa en el artículo 240 del Código Civil Peruano, que establece que una promesa de
matrimonio, cuando sea mutuamente hecha por acto público o escritura privada, obliga al
promisoracom pensaral otro partido porlosdañosy perjuicios resultantes.
2o Raói convive con Lucrecia desde hace cinco (05) años. Sin embargo, Lucrecia mantiene
relaciones sexuales con Manolo. Raúl inicia un proceso de separación de cuerpos por infi
delidad, aportando fotos y videos como medios probatorios. Es correcto afirmar que:
La demanda debe ser declarada improcedente porque el concubinato conforme al tercer pá
rrafo del artículo 326 del Código Civil termina por decisión unilateral de cualquiera de sus in
tegrantes sin posibilidad de exigirlo judicialmente.
3. En un proceso de divorcio por la causal de abandono injustificado del domicilio conyugal
por más de dos años continuos, ¿se puede acumular como pretensión accesoria la indem
nización por daño moral?.
Sí procede, si la demandante es la víctima del abandono injustificado.
4. El día de hoy se ha publicado en el diario oficial El Peruano la Ley N° 40005 que modifica
el numeral 5. del artículo 333 del Código Civil, que prevé el caso del abandono injustifica
do de la casa conyugal como causal de separación de cuerpos y ulterior divorcio. Debido a
que los legisladores consideran excesivo el plazo establecido por dicha norma, la Ley N°
40005 reduce el plazo de abandono injustificado de la casa conyugal de dos años a un año.
Francisco se fue de su casa, sin ningún motivo, hace un año y tres meses. María, su cónyuge,
quiere solicitar hoy la separación de cuerpos, pero Francisco ha decidido regresar al hogar
conyugal pues cree que, de este modo, ella no podrá separarse judicialmente de él. A partir
de los hechos descritos en el caso. ¿Se puede amparar la solicitud de Francisco?:
Sise puede emplear la causal de abandono injustificado de la casa conyugal, porque la norma
aplicable al caso-de forma inm ediata-es la Ley N° 40005 y ya ha transcurrido el plazo de un
año previsto en la misma.
5. Carmelo abandona injustificadamente a su cónyuge Josefina; desde que se produjo el
abandono (1998) hasta la fecha, Carmelo ha cumplido con los alimentos de Josefina y de
sus dos hijos. Carmelo demanda separación legal por la causal de separación de hecho;
ahora bien, desde la fecha de la sentencia que ampara la demanda han transcurrido más
de 8 meses, entonces:
En aplicación del artículo 3542 del Código Civil Carmelo o josefina pueden pedir la conversión
a divorcio.
6 . Patricia Poma Ramírez, tiene 16 años y contrae matrimonio con Benito Montoya Nar-
váez de 17 años, y por tal hecho obtiene capacidad de ejercicio; un año más tarde termina
el matrimonio, pero tienen un hijo de nombre Francisco. Es correcto afirmar respecto de
Patricia Poma Ramírez:
Según el artículo 46 del Código Civil la incapacidad de las personas mayores de 16 años cesa
por matrimonio. Asimismo, dispone que la capacidad adquirida no se pierde por la term ina
ción del matrimonio. Por tanto, Benitoy Patriciaya tienen capacidad absoluta pase lo que pase
por haber contraído matrimonio.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1379 of 1506 --

CMOS PRÁCTICOS DESARROLLADOS
7 Carlos es casado con Angélica y tienen un hijo de nombre A Iberio, Carlos se separa de
hecho de Angéüeay en ese estado vive por más de 10 años. Carlos sin divorciarse se casa con
Rieardina, quien no conocía el impedimento de Carlos. Angélica fallece, entonces ¿quién
puede pedir la invalidez del matrimonio de Carlos con Ricardiraa?
La invalidez del segundo matrimonio la puede pedir Ricardina, ya que el primer cónyuge ha
muerto, siempre que Ricardina hubiese actuado de buena fe. La acción caduca si no se interpo
ne dentro del plazo de un año desde el día en que tuvo conocimiento del m atrim onio anterior.
(Art. 2743 del Código Civil)
8. Nelida se casa con Juan, sin conocer que éste es homosexual. Desde el matrimonio a la
fecha no han transcurrido dos años, y Nelida decide accionar judicialmente para dar por
terminado su matrimonio, entonces:
El artículo 276.5 del Código Civil faculta a Nelida a demandar la anulabilidad de su matrimonio.
9. Margot era la niña mimada de su padre. Su familia era una de las más importantes de
La Unión, un bello y pequeño pueblo costeño del país. Se enamoró y se casó con Andrés
al poco tiempo de conocerlo y tanto la boda como la recepción fueron un gran aconteci
miento social de la localidad. Esto estuvo en boca de todo el pueblo. Pero toda la felicidad
se diluyó en la misma noche de la boda cuando ella comprobó que su esposo era homo
sexual, lo que él ocultó convenientemente durante el corto noviazgo. No supo explicar la
razón de su proceder y por qué llegó a contraer matrimonio y su sinceridad esa noche fue
conmovedora. Enterado el padre consultó con el abogado de la empresa quien le propuso
demandar un divorcio, pero un amigo especialista en derecho de familia estudió el caso y
recomendó una nulidad del matrimonio.
¿Cómo afecta este hecho la vigencia del matrimonio de Margot y Andrés?
Se mantiene vigente mientras no se declare su anulación a solicitud de Margot ante juez com
petente. La promesa de m atrimonio entre M argoty Andrés no afecta la vigencia del m atrim o
nio, ya que se considera un hecho privado sometido al honory conciencia del individuo, y no
genera obligación legal de contraer matrimonio ni de ajustarse a lo estipulado.
¿Qué acción legal se puede promover para dejar sin efecto el matrimonio?
Es un caso de anulabilidad del matrimonio que puede Intentar Margot. Si Margot desea dejar
sin efecto el matrimonio, puede promover una acción de anulabilidad del m atrimonio ante
un juez competente,ya que Andrés ocultó su orientación homosexual durante el noviazgo.
10. Fanny y Roberto son peruanos y viven hace varios años en Miami donde trabajan. Tie
nen un hijo y desean casarse en lea donde están sus familiares y a largo plazo es el lugar
donde esperan vivir una vez que reúnan suficiente dinero para un negocio propio, pero
ahora no pueden retornar porque son ilegales. Consultan a un abogado y les dice que sólo
deben otorgar un poder conjunto incluso a la misma persona para casarse en lea, siempre
que indiquen que es para el matrimonio de los dos, señalen que solo se podrá ejercer en la
ciudad de lea y que es irrevocable por lo que tendrá validez de un año. Además, se ahorra
rán el proceso de exequátur para que se reconozca el matrimonio en el Perú si se casan en
Miami. Llegan a casarse a los 7 meses desde otorgado el poder y asumir la nueva gestión
municipal detectan este matrimonio.
Dicho matrimonio es:
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1380 of 1506 --

UBILEX
Esanulable. Al otorgar un poder conjunto irrevocable para casarse en lea, pero celebrar el ma
trim onio en Miami, violaron los requisitos legales para un m atrim onio válido en el Perú.
¿Cómo es que se resolverá el proceso iniciado?
No será posible la celebración del matrimonio a los 7 meses porque el poderya ha caducado.
11. Margot tiene un hijo de dos años. Leonardo, el padre biológico del menor no lo recono
ció y se desconoce el paradero de dicha persona. Luego de un año Margot conoce a Javier
con quien contrae matrimonio. Después de cinco años de casados Javier se encariña con el
hijo d&Margoty decide adoptarlo:
Javier puede adoptar al hijo de Margot, para ello debe solicitarlo ante el juez competente y
cum plir los requisitos de la adopción enumerados en el artículo 378 del Código Civil.
12. Isabel Flores Córdova (65), ante la impotencia de no poder ver, ni disfrutar de sus nietos
Juan y Estefani, pues su nuera Rosangela, madre de los referidos menores, le niega dicho de
recho, conforme al Código del Niñoyel Adolescente, tiene expedito el derecho de solicitar:
Isabel Flores Córdova deberá solicitar vía judicial el Régimen de visitas para ver a sus nietos
conforme al artículo 90 del Código del N iño yel Adolescente.
13. El señor Carlos Ríos desde hace siete años mantiene una relación conyugal con Raquel
Ruíz quien tiene un hijo de trece años, producto de su anterior compromiso con Rafael Do
mínguez; persona que, jamás asistió al menor ni moral ni materialmente; sin embargo, ese
afecto y cuidado se le otorgó Carlos Ríos, por lo que el último de los citados tiene el derecho
de demandar ante el Juez de Familia la:
Custodia del menor o un régimen de visitas.
14. Amelia Sánchez quiere demandar alimentos, porque el dinero ya no le alcanza, a favor
de su hijo Joel Romero Sánchez, quien tiene 19 años y está estudiando en una Universidad
Privada. Al respecto pregunta si ella puede demandary ante qué juzgado.
Joel el hijo de Amelia puede demandar directamente por alimentos a su padre en virtud de
estar soltero (así se debe entender) siguiendo estudios de una profesión en una universidad
privada hasta los 28 años, siemprey cuando éstos sean exitosos, la demanda deberá interpo
nerse ante el Juez de Paz Letrado (Artículo 424 del Código Civil).
15. Pablo y Lucrecita, casados durante 15 años, con un hijo de 12 años, deciden separarse
porque Pablo comienza una relación extramatrimonial con Raquel. Pablo asumiendo su
culpa se retira del domicilio conyugal. Transcurridos un año y medio de separados, Pablo
decide formalizar su relación extramatrimonial para lo cual plantea a Lucrecita una sepa
ración convencional y divorcio ulterior.
En este caso para demandar separación convencional y divorcio ulterior Pablo y Lucrecita de
berán hacerlo de manera conjunta debido a que debe existir m utuo acuerdo (Arts. 344 C.C;
578 C.RC), lo que no sucede en este caso ya que el interesado en el divorcio es Pablo por tanto
éste tendría que esperar completar los 04 años de separados para demandar el divorcio por
causal de separación de hecho ya que existe un hijo menor de edad. (Art. 333.12 C.C.)
16. Marcos está casado con Angela y se entera que ella le es infiel. Cuando Marcos conversa
con Angela, ella reconoce infidelidad y le dice que nunca más pasará. Marcos decide per
donar a Angela y quedarse a vivir con ella, pero pasados cuatro meses desde esa conver-
■ BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1381 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
sacien, Marcos demanda a Ángela el divorcio por adulterio, sin que éste se haya repetido,
¿Cóm o resuelve Ud. e! caso?
La demanda debe ser declarada improcedente porque Marcos perdonó a Ángela y siguió vi
viendo con ella después de enterado del adulterio. De conformidad con el artículo 336 del
Código Civil que señala: “no puede intentarse la separación de cuerpos por adulterio si el ofen
dido lo provocó, consintió o perdonó. La cohabitación posterior al conocimiento del adulterio
impide iniciar o proseguir la acción”.
17. Ricardo es casado con Paulina. Ricardo demanda divorcio argumentando que Paulina
es adúltera, sin embargo, no llega a probar a cabalidad la causal que invoca, pero el Juez
advierte una posibilidad de reconciliación, entonces el Juez resuelve:
El artículo 346 (Primer párrafo) del Código Civil versa sobre la reconciliación de los cónyuges
respecto de los cuales se tram ita un proceso de divorcioy señala lo siguiente: “Cesan los efectos
de la separación por la reconciliación de los cónyuges. Si la reconciliación se produce durante
el juicio, el juez manda cortar el proceso. Si ocurriere después de la sentencia ejecutoriada, los
cónyuges lo harán presente al juez dentro del mismo proceso”. Reconciliados los cónyuges,
puede demandarse nuevamente la separación sólo por causas nuevas o recién sabidas. En
este proceso no se invocarán los hechos perdonados, sino en cuanto contribuyan a que el juez
aprecie el valor de dichas causas (Art. 346, segundo párrafo).
18. Raquel tiene 2 hijos con Juan, (de 3 y 5 años) de una convivencia de seis años. Al deci
dir ambos terminar su relación, acuerdan ante la Fiscalía de Familia que la tenencia de los
menores las asumiría la madre y a favor del padre se fija un régimen de visitas, asimismo
este último asume pasarle alimentos a su favor. Con los meses Raquel le solicita a Juan que
aumente el monto de la pensión de alimentos, a lo que Juan se niega, por lo que Raquel no
le permite ver más a sus hijos. Raquel realiza una limitación al régimen de visitas y puede
ser forzada a cumplircon lo acordado ante el Ministerio Público.
Juan que se encuentra impedido de ejercer el derecho de visitar a sus hijos podrá interponer
la demanda de régimen de visitas acompañando las partidas de nacimiento que acrediten su
entroncamiento. Si el caso lo requiere podrá solicitar un régimen provisional (Art. 89 CNA).
19. Pedro y Gabriela son enamorados y tienen un hijo, llamado Carlos. Pedro no reconoce
a Carlos y Gabriela quiere reclamarle alimentos a Pedro para su hijo, sin necesidad de que
éste lo reconozca como suyo. ¿Qué debe hacer Gabriela?
Gabriela deberá solicitar, en representación de Carlos, una pensión como hijo alimentista.
Carlos tendrá derecho a percibir una pensión alimenticia hasta la edad de 18 años. La pensión
continúa vigente si Carlos, llegado a la mayoría de edad, no puede proveer a su subsistencia
por incapacidad física o mental. Asimismo, el artículo 415 del Código Civil faculta a Pedro la
posibilidad de solicitar la aplicación de la prueba genética u otra de validez científica con Igual
o mayor grado de certeza para confirmar su paternidad. De comprobarse que no es el padre
podrá demandar ante el mismo juzgado que conoció de la demanda de Gabriela el cese de la
obligación alimentaria.
20. Elizabeht Vargas, tiene 15 años y contrae matrimonio con Joselito Amargo de 19 años,
y por tal hecho obtiene capacidad de ejercicio; un año más tarde termina el matrimonio,
pero tienen un hijo de nombre Juan Carlos. ¿Es correcto afirmar, respecto de Elizabeht Var
gas?:
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 13

-- 1382 of 1506 --

UBILEX
Elizabeht Vargas puede perfectamente representar a su menor hijo Juan Carlos. Si por cual
quier razón terminará su relación matrimonial, ello no hace que se pierda la capacidad de
ejercicio adquirida por dicho acto. A partir del nacimiento del hijo cesa la incapacidad de las
personas que mayores de 14 años para los actos enumerados en el artículo 46o del Código Ci
vil, como el reconocimiento del hijo, demandar gastos de embarazo, alimentos, tenenciay la
filiación extramatrimonial desús hijos.
21. Carla tiene 16 años y es madre de Nicolás. El padre de éste, Darío, no quiere pasarle la
respectiva pensión de alimentos. Ante ello, Carla quiere iniciar un proceso para exigir el
pago de los alimentos. Es correcto afirmar:
Carla puede iniciar un proceso para pedir, en representación de Nicolás, el pago de una pen
sión alimenticia. A partir del matrimonio cesa la incapacidad de las personas mayores de 16
años así lo regula el artículo 46 del Código Civil.
22. Raquel obtiene una pensión de alimentos a su favor dentro del proceso de divorcio por
separación de hecho que siguió contra Roberto. Posteriormente, Roberto contrae matri
monio con Julia; quien le dice a Roberto que al estar nuevamente casado ya no debería
continuar pagando la pensión de alimentos que le corresponde a Raquel. Al respecto, es
correcto afirmar.
La pensión de alimentos de Raquel es de cargo de la sociedad de gananciales del m atrimonio
de Robertoy Julia. En aplicación del artículo 316.23 del Código Civil.
23. A José Rivas Ríos, mediante sentencia, se le ordenó judicialmente pasar una pensión de
alimentos del 6 0 % del total de sus ingresos a favor de sus hijos Andrés, Andrea y Romina
Rivas del Águila, quienes a la actualidad cuentan con 19,1S y 12 años respectivamente. Sin
embargo, José tiene con su nuevo compromiso otros dos niños, unos gemelos de nombres
Augusto y Jesús Rivas López de tres años. ¿Qué debe hacer José,ya que le es imposible man
tener a su segunda familia con el 4 0 % del saldo de sus ingresos?
José puede pedir el prorrateo de la pensión de alimentos y con ello reducir el porcentaje de la
pensión de alimentos a favor de sus hijos mayores, José debe interpone su demanda ante el mis
mo Juez que determino el porcentaje de pensión alimenticia para sus hijos mayores. Mientras
se tramita el proceso de prorrateo, el Juez puede señalar provisionalmente, a pedido de parte, las
porciones que debe percibir cada demandante de la renta afectada (Art. 570 C.PC.).
24. Carlos no ha sido reconocido ni declarado, pero recibe alimentos de Julio, pues se probó
que tuvo trato íntimo en el período de la concepción con la madre de Carlos. Carlos ha cum-
plído 18 años y sigue con éxito una carrera profesional, entonces:
Julio puede ampararse en el artículo 415 del Código Civil y así quedar liberado de la obligación
de alimentar a Carlos.
25. José y Andrea son solo enamorados y durante esa vigencia tienen un hijo, llamado Bar
tolo, José se niega a reconocer al hijo. Dada las circunstancias y necesidad alimentaria in
minente del menor. ¿Qué debe hacer Andrea?
Andrea puede pedir una declaración de paternidad ante un Juez de Paz Letrado, el mismo que
hade expedir resolución declarando la filiación demandada. En este proceso podrá acumular
se como pretensión accesoria, la fijación de una pensión alimentaria. (Art. 1 Ley N° 28457- Ley
que regula el Proceso de Filiación Judicial de Paternidad Extramatrimonial).
382 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1383 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
26. Marcela queda embarazada de Antonio con quien mantiene un enamoramiento de
algunos meses que mantienen con mucha reserva. Los padres d e ella no sabían d e e s t o y
quedan sorprendidos con la noticia, pero tranquilizan a s u h i j a prometiéndole apoyo eco
nómico y emocional y con la natural alegría de estar próximos a ser a b u e lo s . Cuando A n t o
nio se entera del embarazo, rehuye la situación, se torna distante con Marcelay finalmente
se vuelve inubicable. Los padres de ella piensan que el padre debe asumir su responsabili
dad y Marcela piensa iniciar un proceso para que se declare a Antonio como padre. Su abo
gado le explica la Ley 28457 que, según él, es muy rápida y hace posible lograr un resultado
confiable en poco tiempo porque de por medio se tiene la prueba del ADN.
¿Cuáles son los alcances de la Ley 28457 - Ley que regula el proceso de filiación judicial de
paternidad extramatrimonial para la finalidad que persigue Marcela?
La citada Ley tiene como objeto promover y fortalecer el desarrollo de la familia como fu n
damento de la sociedad y espacio fundamental para el desarrollo Integral del ser humano,
basándose en el respeto de los derechos fundamentales y las relaciones equitativas entre sus
miembros y velando especialmente por aquellas familias que se encuentran en situación de
extrema pobreza, pobreza o riesgo social. En el caso de Marcela, que busca declarar a Antonio
como padre, esta Ley ofrece un proceso rápido y confiable que utiliza la prueba del ADN para
determinar la paternidad.
¿Qué aspectos particulares tiene esta Ley que tiene como referencia el sometimiento del
demandado a la prueba de A D N ?
Si se declara la paternidad, el demandado que es declarado padre pierde los derechos suceso
rios o alimentarios respecto de su hijo.
27. Ernesto cuenta con un hijo extramatrimonial a quien no ha reconocido por ser casado.
Transcurridos 10 años se arrepiente de no haberlo reconocido y al intentar hacerlo torna
cuenta que el menor fue reconocido como hijo del actual esposo de la madre. Muy a pesar
de ello decide demandar la impugnación del reconocimiento y ofrecer la prueba del ADN.
En reiterada jurisprudencia la Corte Suprema viene admitiendo la posibilidad de que proceda
la impugnación de paternidad en este caso, aunque haya transcurrido el plazo de caducidad
prevista en el artículo 400o del Código Civil, ello al realizar la aplicación del Control Difuso del
citado dispositivo legal, y dando preferencia al Derecho Fundamental a la Identidad.
28. Cuando la mujer casada alumbra un hijo y éste nace muerto, el marido que tiene dudas
razonables de que ese hijo no era suyo, considera que:
Puede negarlo porque tiene interés en ello.
29. Celso reconoce como hijo extramatrimonial a Andrés, luego de ello toma conocimiento
que fue engañado y que Andrés es hijo biológico de Pedro, entonces:
Celso puede impugnar la paternidad extramatrimonial y dirigir la demanda contra la ma
dre de Andrés. Caso similar fue resuelto por la Sala Civil Transitoria de la Corte Suprema de
justicia a través de la Casación N° 864- 2014-lca, que declaró fundada la sentencia de fecha
20.09.2013, en vista que la Corte Suprema precisó que debe permitirse la invalidación del acto
de reconocimiento cuando se demuestre que la voluntad del reconocedor se encuentre vicia
da. La Sala Suprema precisó que debe permitirse la invalidación del acto de reconocimiento
cuando se demuestre que la voluntad del reconocedor se encuentre viciada.
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1384 of 1506 --

UBILEX
30. Cm ¡Q3}/ í/los ía soy casad os. ‘Cielos fallaos en un acódenos y deja a su viuda sit es? a<Jo de
gestación. María sin esperare! plazo de ley contrae un nuevo ¡naiiim onsocon Pedro, filaría
da a luz un niño de nom ine Juan, esinorres «2! pache lega! de Juan es;
En aplicación del artículo 243.3 del Código Civil el padre legal de Juan sería Pedro. Ya que María
según lo dispuesto en el dispositivo citado estaba prohibida de contraer nuevas nupcias en
tanto no transcurran por lo menos 300 días de la muerte de Carlos ante el caso omiso de las
normas se aplicaría la presunción de paternidad respecto del nuevo marido.
31. Carmen fue reclutada en una campaña de planificación familiar y en su primer parto,
sin recibir información adecuada, la sometieron a una ligadura de trompas que terminó
causándole muchos estragos en su salud. Ya recuperada conoció a Franco y se casó con él.
Cuando estaban buscando tener un hijo se dieron con ia sorpresa de que ella ya no podía
concebir. Franco desea solicitar la anulación de su matrimonio porque Carmen es estéril y
esto ocasiona en él un sentimiento que hace insoportable la vida en común. En este caso,
se puede afirmar que;
Solo podría solicitar la anulación de su matrimonio si Carmen le hubiera ocultado la verdad
de la esterilización y ello haga Insoportable la vida en común. (Artículo 277-5 del Código Civil).
32. Carlos y Ana se enamoran e inician una relación de convivencia, la cual lleva más de tres
años. En el segundo año de convivencia, él adquiere una enfermedad crónica, contagiosa y
transmisible por herencia. A pesar de que Ana sabía de la enfermedad, deciden casarse al
cuarto año de convivencia. ¿Este matrimonio podría ser anulable a petición de Ana?
No es anulable pues Ana conocía de la enfermedad antes de casarse. (Art. 277-2 del Código
Civil).
33. Un varón y una mujer libres de impedimento matrimonial que conforman una unión de
hecho, tienen derecho:
Las uniones de hecho tienen derecho a sucederse recíprocamente en caso de fallecimiento de
uno de ellos. De Igual modo, tienen derecho a dividirse los bienes que conforman la comuni
dad de bienes, bajo las mismas reglas de una sociedad de gananciales (Artículo 326, últim o
párrafo, del Código Civil).
34. Martha cansada de la conducta violenta de su esposo decide demandar el divorcio por
que ya no soporta tanta humillación. Inicialmente lo soportó por sus hijos pequeños y por
temor a quedarse sin el respaldo económico de su esposo, pero ahora está dispuesta hasta
las últimas consecuencias. De otro lado, en varias oportunidades su esposo se ha referido a
ella indicando que es una mantenida y que se casó con ella porque es una “caza maridos" y
que seguro puede encontrarse a otro en cualquier momento. Su abogado le dice que puede
demandar el divorcio por violencia psicológica, injuria grave o por imposibilidad de hacer
vida en común, ya que se trata de ofensas muy serias que no permiten mantener la convi
vencia. Además, le recomienda actuar de inmediato. También debe decidir en la demanda
todos los aspectos referidos a las relaciones con los hijos.
En relación al caso propuesto. Es válido:
La causal de imposibilidad de hacer vida en común no tiene plazo de caducidad a diferencia
de la violenciay la injuria grave.
