36. A n d ré s o b tu v o s e n te n c ia fa v o r a b le en el proceso d e d iv o rc io s e g u id o e n c o n tra d e su es
posa J u lia por la causal de imposibilidad d e hacer vida en común. Durante su matrimonio
p ro c re a ro n a Y e s e n ía . ¿ Q u ién d e b e h a ce rs e carg o d e Y e s e n ia d e 6 m eses d e ed a d ?
Andrés, por ser el cónyuge ¡nocente. Sin embargo, el juez puede determinar, por el bienestar
de Yesenia, que Julia se haga cargo de ella. Asimismo, y de ser el caso si hay un motivo grave
el Juez puede determinar que una tercera personase haga cargo de Yesenia. Esta designación
