37. Ju lio y Anabel se casan e l 2 d e m a y o d e 2 0 0 0 . M a r io , t ío d e Ju lio , no s u p o d e la b o d a sin o
hasta 2 0 1 4 , año en el que llegó a Lima luego de un largo viaje. Al tener c o n o c im ie n to de la
boda, decide regalarle un departamento a propósito de su m a tr im o n io . Diga usted quién
es el dueño.
De acuerdo al artículo 310 del Código Civil Julioy Anabel son copropietarios del departamento
sin necesidad de demostrar la calidad de bien propio, perteneciendo a ambos en partes alí
cuotas.
38. Hoy los jóvenes tienen un mundo con muchas posibilidades de desarrollo y progreso
educativo e integral. Kiara y Eloy, de 17 años que se conocieron en el colegio, tienen las
puertas abiertas a eso y sus condiciones son mejores porque sus padres tienen una situa
ción económica expectante. Se enamoraron, son muy apasionados y románticos así que
decidieron casarse siendo menores de edad, lo que hicieron en presencia de un par de ami
gos del barrio que supieron de esto, en un hermoso pueblo de la serranía peruana. Fuera
del patrimonio familiar él tiene una ingente cuenta de ahorros con dinero propio que he
redó de su abuelo quien le dejó un legado. El padre de ella considera una denuncia penal,
pero demanda la nulidad del matrimonio por la minoría de edad. El juez tiene que c a lific a r
la demanda y ver si abre el proceso.
¿Cuáles son los efectos del matrimonio sin autorización?
Los menores contrayentes no gozan de la posesión, administración, usufructo, hasta que al
cancen la mayoría de edad.
¿Qué consecuencias legales acarrea este acto?
El matrim onio padece de nulidad según el artículo 274.10 del Código Civil.
39. Alejandro se enamoró de Leyla, de nacionalidad chilena, a quien conoció en la ciudad
de Lima, ciudad a la que esta emigró con su hijo pequeño en busca de oportunidades la
borales. Luego de una corta relación se casaron y establecieron su hogar en Lima donde
vivieron varios años. Tuvieron una hija y ella viajó a EE. UU. con los dos niños, siempre para
lograr una mejora económica. Alejandro viajó también a dicho país, pero no vivieron jun
tos, aunque se comunicaban continuamente. La relación fracasó y él regresó a Lima luego
de varios años descubriendo por terceros que Leyla era casada en Chile y de ese matrimo-
