t r u ir u n a p e q u e ñ a casa y n o q u e r ía m a n t e n e r su e s ta d o civil d e casado.
¿Q ué acción Segal p u e d e in ic ia r A le ja n d r o p a ra p o n e r fin d e su m a t r im o n io con Leyla?
Nulidad de m atrimonio según el artículo 274-3 del Código Civil.
¿ Q u é requisitos son necesarios para la acción legal que inicie con esta finalidad?
Alejandro es el único que puede pedir la nulidad del m atrim onio con Leyla si no sabía del
m atrimonio de ella en Chile. Esto procede siempre que Alejandro hubiese actuado de buena
fe. No obstante, la acción caduca si no se interpone dentro del plazo de un año desde el día en
que tuvo conocimiento del matrimonio anterior.
40. A n a b e l y Luis son p rim o s hermanos. Sin embargo, p o r el distanciamiento de sus padres
no c o n o c ía n s u p a re n te s c o . Ellos se casaron y acaban de enterarse de su relación co n s a n
g u ín e a . En c o n se cu en cia, su m a tr im o n io :
Es válido, porque las normas del Código Civil no incluyen dentro de las causales de invalidez el
matrimonio de los consanguíneos de cuarto grado de línea colateral, por tanto, no hay ningún
tipo de impedimento al respecto.
41. P o r p r e s ió n de su f a m ilia , pocos días antes de casarse con Frank, Andrea le pide que m e
jo r rija e n tr e ellos una separación de patrimonios por si en los negocios familiares de ella
surja una contingencia y queden a salvo los bienes de é l. En realidad, ella tiene fortuna y
Frank no, pero igual otorgan la escritura pública en la que expresan esta decisión, pero por
un descuido no la llega a inscribir en el Registro Personal. Durante la convivencia surgen
varias discrepancias y él decide iniciar un proceso de nulidad del acto jurídico de separa
ción de patrimonios y que se declare que entre ellos rige la sociedad de gananciales, por lo
que la casa y los dos carros que se compraron cuando estaban casados pasan a ser bienes
sociales, además de los 3 certificados de depósitos en moneda extranjera que por $150,000
se habían abierto en el Banco. Todos estos actos los hizo sólo Andrea.
Con relación a la situación descrita:
Frank tiene legitim idad para obrar para presentar la mencionada demanda.
¿Qué consecuencias legales acarrea la omisión de alguno de esos requisitos?
La omisión de la Inscripción de la escritura pública de separación de patrimonios acarrea la
ineficacia de este acto.
42. Valentino nació hace dos meses dentro del matrimonio de Edgar y Flor. Es el tercero de
tres hijos y los dos primeros tienen 10 y 7 años. Su nacimiento estuvo precedido de varias
crisis matrimoniales de sus padres que conllevaron varios períodos de separación durante
los cuales Edgar se trasladaba a la localidad de Chosica a casa de su madre, por la cercanía
a su trabajo e n Santa Eulalia. El nacimiento lo tomó de sorpresa porque aseguraba no ha
ber tenido relaciones con su esposa en época cercana a la concepción y nunca planeó esto
sabiendo que su matrimonio no tenía rumboyya tenían dos hijos. Está prácticamente con
vencido que no es su hijo y como tiene legalmente al alcance la prueba del ADN, no duda
en iniciar el proceso judicial para negar la paternidad. La madre monta en ira por la actitud
de Edgar y asegura que es su hijo y no teme el proceso judicial.
