¿Cuáles son las c o n d ic io n e s p a ra el in ic io d e zimlqiúer p ro ceso d irig id o a c o n te s ta r la p a-
ternidad?
Edgar solo tiene 90 días para iniciar el proceso contados desde el nacimiento de Valentino. En
el caso de Edgar, al estar convencido de que Valentino no es su hijo y haber nacido hace dos
meses, tiene un plazo de 30 días más para iniciar el proceso judicial de negación de paterni
dad. Cabe mencionar que, si bien el artículo 364 establece que el plazo para contestar la pater
nidad es de 90 días desde el conocimiento del nacimiento, también señala que, si el marido
estuvo presente en el nacimiento, el plazo se computa desde el día siguiente.
43. Luis, quien domicilia en San Isidro, es una p e rs o n a a la que le g u s ta n r e a liz a r inversio
nes riesgosas que a veces le producen p é rd id a s y en o tra s c u a n tio s a s u tilid a d e s . Cuenta con
diversos bienes inmuebles y a l e n a m o r a r s e de M a r c h a apenas la conoció, le p ro p o n e c e le
