a d q u ir id o h a s ta esa fe c h a a fa v o r d e Sa s o c ie d a d c o n y u g a l. Los h ijo s d e M a r t h a d e n u n c ia n
a n te el a lc a ld e q u e su m a d r e h a q u e d a d o v iu d a h ace tre s m ese s y e s ta b a s e p a ra d a u n añ o
a n te s d e su fa lle c id o esposo. El a lc a id e d e S an B o rja d e s is te d e l t r á m it e d e l matrimonio y
a h o ra Luis y M a r t h a a c u d e n aS d is tr ito d e Catataos, e n Piura, pues es u n a z o n a le ja n a d e
donde se e n c u e n tra n los h ijo s d e M a r t h a , lo q u e les dificulta t o m a r c o n o c im ie n to de estas
gestiones.
¿Procede el matrimonio de Luis y Martha?
El matrim onio no será nulo, pero puede acarrear la sanción de pérdida del usufructo legal
sobre los bienes de los hijos menores.
44. Luis Carlos y Evelyn se casaron en la localidad de Cerro Verde a 5 minutos de la frontera
con Brasil, muy le jo s de Lima donde viven, porque él es sumamente reacio a los convencio
nalismos limeñosy la convenció de que se comprometieran para siempre lejos de la gente
falsa y en contacto con la naturaleza como debían conservar su unión matrimonial. Evelyn
aceptó porque lo quería mucho, ya estaba embarazada y a los pocos meses tuvo a su hijo.
En realidad, Luis Carlos era casado con Teresa y quería que este acto pasara desapercibi
do. Pero Teresa se enteró de todo esto y pidió la anulación de este matrimonio porque le
interesaba una indemnización que su abogado ofreció conseguir, como que finalmente se
invalidó este segundo matrimonioyse le concedió la indemnización de S /2 0 ,0 0 0 .0 0 .
Sobre la invalidación del matrimonio entre los padres y los efectos sobre su hijo menor:
El juez que declare la Invalidez es competente para disponer todo lo concerniente a la patria
potestad del hijo de Luis Carlos y Evelyn.
45. limeña desea adquirir un vehículo para dedicarlo a transporte escolar, lamentable
mente no es sujeto de crédito en el sistema financiero, así que llega donde un prestamista
recomendado por su prima quien le indica las condiciones del préstamo, como la tasa de
interés, el plazo y, sobre todo, la garantía mobiliaria que se debe inscribir en Registros Pú
blicos para asegurar la devolución del dinero. Esto involucra determinar la participación
de su esposo en las diversas operaciones y contratos dado que, como es sabido, la sociedad
