Dicha empresa tiene dos tipos de acciones, acciones clase A con derecho a voto y acciones
clase B sin derecho a voto. Adrián está pensando adquirir las acciones clase B siempre y
cuando le sea más conveniente.
Los estatutos de la empresa otorgan un derecho a percibir el 1 0 % como dividendo prefe
rencia!.
