¿Quiénes íiejie» demedio a percibir d dividendo prsfeí^nciai?
Adrián puede adquirir acciones clase B de Solventa S.A. sin derecho a voto, siempre y cuando le
sea más conveniente. En este caso, tiene derecho a percibir el dividendo preferendal del 10% de
bido a que las acciones clase B tienen derecho a recibir dividendos, aunque no tienen derecho a
voto en la junta general de accionistas. Esto se establece en los estatutos de la empresay no está
relacionado con el derecho a voto, ya que las acciones clase B no tienen este derecho.
2. Los accionistas de la empresa STARTUP S.A. están sorprendidos de los logros alcanzados
con su emprendímiento en Tecnología de la Inform ación (TI); sin embargo, son conscien
tes que para seguir creciendo deben aum entar su capital, por lo que han decidió incremen
tar el capital social en 60% . Para tal efecto, han decidido crear dos clases de acciones, las
acciones clase A que representan el 4 0 % del capital social y las Acciones clase B represen
tan el 6 0 % del capital social, las cuales sería m ateria del aum ento de capital y no tendría
derecho a voto.
Consecuentemente, modifican los estatutos de STARTUP S.A. en el sentido de disponer
que de existir utilidades distríbuibles y de ser acordada la distribución de utilidades por
la Junta de Accionistas, se repartirán las utilidades de la siguiente m anera: Acciones clase
A, el 6 0 % de las utilidades distríbuibles y Acciones clase B, el 40% de las utilidades distri
buí bles.
¿Qué opina de los estatutos sociales de STARTUP S.A .?
Es procedente lo dispuesto por los estatutos en cuanto a la distribución de utilidades entre las
acciones clase A y B. Esto se debe a que los estatutos de la empresa establecen claramente las
condiciones de distribución de utilidades, lo que es un derecho de los accionistas según la Ley
General de Sociedades (artículo 40).
En relación con el mismo caso, ¿en qué proporción las acciones clase A asum en las pérdi
das, si las hubiere?
En 60%, pues en proporción a sus aportes del capital según el artículo 39 de la LGS.
