Usted como asesor legal de la em presa que recom endaciones haría al Directorio:
La propuesta del Gerente General es errónea.
Primero, se deben compensar las pérdidas del ejercicio 2022 con las utilidades anteriores (SI
40,000). Esto dejaría un saldo de pérdidas pendientes de compensar de S/10,000 (S/ 50,000
