Las pérdidas se compensan en primera instancia con las utilidades anteriores o reservas de
libre disposición. En este caso, se deben seguir los siguientes pasos:
1. Compensar las pérdidas del ejercicio 2022 con las utilidades anteriores (S/40,000).
2. Compensar las pérdidas pendientes con las reservas voluntarlas de libre disposición (S/
40,000).
Este proceso de compensación debe ser realizado de manera transparente y documentada,
siguiendo las normas contablesy legales aplicables.
