da de desalojo dirigida al “SEÑ O R JU EZ ESP ECIA LIZA D O EN LO PEN A L DE LIMA”. ¿Cóm o
la califica?
Improcedente porque se ha afectado la competencia por razón de la materia1. El proceso de
desalojo es un proceso civil por naturaleza.
10. A d m itid a a trám ite la d em anda interpuesta por Juan contra Pedro en la vía del proceso
de conocim iento, Pedro decide form ular tacha contra un m edio probatorio ofrecido en la
dem anda, así como una excepción de incom petencia por razón del territorio. De esta m a
nera, Pedro interpone la tacha al día siguiente de notificada la resolución que adm ite la
dem anda y tiene por ofrecidos los m edios probatorios, sin cuestionar la com petencia del
Juez ni hacer reserva de la excepción de incom petencia; y al quinto d ía form ula la excep
ción de incom petencia.
La excepción de incompetencia es improcedente debido a que el demandado ha prorrogado
en forma tácita la competencia territorial.
11. Luis Flores solicitó al Juez de Paz Letrado de I lo medida cautelar fuera de proceso de em
bargo en forma de inscripción, del inmueble de propiedad de Jorge Torres, quien domicilia
en Lima. El Juez, al calificar la solicitud, consideró que contaba con los requisitos legales, la
verosimilitud del derecho, el peligro en la demoray razonabilidad, por ello la concedió. Es
correcto afirmar que:
El juez debió apreciar de oficio su incompetencia territorial.
iz . Juan dom iciliado en la Calle Im perial N ° 322-Cañete dio en arrendam iento a M iguel do
m iciliado en el Jirón Los insurgentes N ° 2527-Puente Piedra, un local com ercial de su pro
