por vencim iento de contrato ante el 14 Juzgado Civil de Lim a. Respecto a la com petencia
territorial del ju ez del 14 Juzgado Civil de Lim a:
Con la interposición de la demanda se ha producido la prórroga tácita de la competencia te
rritorial para el demandante, por lo que el Juez del 14 Juzgado Civil de Lima debe a dm itir a
