BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1396 of 1506 --

UB1LEX
13. Marco y Felipe celebran un comí raro con losé por el cual se compromecen en forma so
lidaría e indivisible con entregar la suma de US $ 90 000,00. Sin embargo, llegada la fecha
para cumplir con el pago de la suma de dinero, ninguno cumple con su obligación por lo
que losé demanda a Marco el pago del íntegro de la obligación y luego de un mes interpo
ne una demanda contra Felipe, también por el íntegro de la obligación. Es correcto afirmar
que:
No existe Iitispendencia debido a que los sujetos demandados son distintos.
“La excepción de litispendencia es una defensa procesal que se puede hacer valeren un proce-
so cuando existe un pleito que todavía no se resuelvey habiendo sido presentado con anterio
ridad én el mismo juzgado o en otro diferente, debiendo existiren ambos conflictos identidad
de sujetos, objetoy pretensión, encontrándose fundada dicha excepción en tres razones prin
cipales: en el principio de economía procesal, que exige se eviten dos procesos sobre el mismo
litigio; en la necesidad de evitar dos sentencias diversas y aun contradictorias sobre el mismo
litigio; y, finalmente, que sería injusto obligar al demandado a defenderse en dos procesos
diversos respecto de una misma demanda”. Casación N° 1036-2004-Cusco.
14 Juan y Pedro suscribieron un contrato de suministro en el cual pactaron que, ante cual
quier discrepancia entre las partes, relacionada a la interpretación y/o ejecución del con
trato, se sometían a un arbitraje de derecho, el cual debía ser decido mediante un árbitro
único designado por acuerdo de las partes. Pese al convenio arbitral, Juan interpuso una
demanda exigiendo el cumplimiento del contrato de suministro ante el Poder Judicial.
¿Como Juez que conoce la demanda, cómo se pronunciaría respecto del caso?
El juez no puede pronunciarse sobre la eficacia del convenio arbitral si la parte demandada no
deduce la excepción de convenio arbitral (Art. 446 C.RC.).
15. En un proceso único de ejecución, dentro del plazo de ley, el ejecutado formula contra
dicción al mandato ejecutivo que se sustenta en título ejecutivo de naturaleza extrajudi-
cial, alegando que por problemas personales y familiares no le ha sido posible cancelar la
obligación demandada a su vencimiento, agregando, que esta situación es de pleno cono
cimiento del ejecutante; ofrece como medio probatorio: la declaración de parte del ejecu
tante. En relación a la contradicción formulada:
Debe rechazarse liminarmente por que se sustenta en causal distinta a las establecidas en la ley.
16. Luis, demanda resolución de contrato de compraventa por falta de pago con entrega
del bien y alternativamente el pago del saldo del precio. Es correcto afirm ar:
El demandado en ejecución de sentencia tendrá la opción de elegir entre la resolución o el
pago del precio restante.
17. Juan interpone demanda en la vía de conocimiento, teniendo como pretensión prin
cipal la resolución del contrato de compra venta por falta de pago, y como pretensión su
bordinada que el demandado le abone el saldo del precio de venta. En la sentencia el Juez
declara infundada la pretensión principal; en consecuencia:
Juez debe pronunciarse sobre la pretensión subordinada.
